window.ATLAS_BUNDLES=window.ATLAS_BUNDLES||{};window.ATLAS_BUNDLES["annotations-032"]={"PPARA":{"hgnc":"HGNC:9232","symbol":"PPARA","accessions":["Q07869"],"name":"Peroxisome proliferator-activated receptor alpha","length":"468","function":"Ligand-activated transcription factor. Key regulator of lipid metabolism. Activated by the endogenous ligand 1-palmitoyl-2-oleoyl-sn-glycerol-3-phosphocholine (16:0/18:1-GPC). Activated by oleylethanolamide, a naturally occurring lipid that regulates satiety. Receptor for peroxisome proliferators such as hypolipidemic drugs and fatty acids. Regulates the peroxisomal beta-oxidation pathway of fatty acids. Functions as a transcription activator for the ACOX1 and P450 genes. Transactivation activity requires heterodimerization with RXRA and is antagonized by NR2C2. May be required for the propagation of clock information to metabolic pathways regulated by PER2","subunit":"Heterodimer; with RXRA. This heterodimerization is required for DNA binding and transactivation activity. Interacts with NCOA3 coactivator. Interacts with CITED2; the interaction stimulates its transcriptional activity. Also interacts with PPARBP in vitro. Interacts with AKAP13, LPIN1, PRDM16 and coactivator NCOA6. Interacts with ASXL1 and ASXL2. Interacts with PER2. Interacts with SIRT1; the interaction seems to be modulated by NAD(+) levels (PubMed:24043310). Interacts with CRY1 and CRY2 (By similarity). In hepatocytes, interacts with PAQR3 and HUWE1; the interactions promote PPARA poylubiquitination and HUWE1-mediated degradation (By similarity)","family":"Belongs to the nuclear hormone receptor family. NR1 subfamily","domains":[],"function_pmids":["10195690","24043310","7629123","7684926","9556573"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Ligand-activated transcription factor. Key regulator of lipid metabolism. Activated by the endogenous ligand 1-palmitoyl-2-oleoyl-sn-glycerol-3-phosphocholine (16:0/18:1-GPC). Activated by oleylethanolamide, a naturally occurring lipid that regulates satiety. Receptor for peroxisome proliferators such as hypolipidemic drugs and fatty acids. Regulates the peroxisomal beta-oxidation pathway of fatty acids. Functions as a transcription activator for the ACOX1 and P450 genes. Transactivation activity requires heterodimerization with RXRA and is antagonized by NR2C2. May be required for the propagation of clock information to metabolic pathways regulated by PER2"},"PPARG":{"hgnc":"HGNC:9236","symbol":"PPARG","accessions":["P37231"],"name":"Peroxisome proliferator-activated receptor gamma","length":"505","function":"Ligand-activated transcription factor that forms obligate heterodimers with the retinoic acid receptor and acts as a key regulator of biological processes, such as adipocyte differentiation, lipid metabolism, glucose homeostasis and beta-oxidation of fatty acids (PubMed:16150867, PubMed:20829347, PubMed:23525231, PubMed:8702406, PubMed:8706692, PubMed:9065481). Activated by lipid ligands: binds peroxisome proliferators, such as hypolipidemic drugs, and fatty acids, such as prostaglandin J2 metabolites (PubMed:16150867, PubMed:20829347, PubMed:23525231, PubMed:8702406, PubMed:8706692, PubMed:9065481). Ligand-binding results in a conformational change in the receptor, promoting dissociation of repressors and recruitment of coactivators, and subsequent activation of target gene expression (PubMed:16150867, PubMed:20829347, PubMed:23525231, PubMed:8702406, PubMed:8706692, PubMed:9065481). Specifically binds to DNA specific PPAR response elements (PPRE) and modulates the transcription of its target genes, such as acyl-CoA oxidase (By similarity). Acts as a critical regulator of gut homeostasis by suppressing NF-kappa-B-mediated pro-inflammatory responses (PubMed:20829347). Plays a role in the regulation of cardiovascular circadian rhythms by regulating the transcription of BMAL1 in the blood vessels (By similarity)\nNuclear receptor that acts as the key factor controlling the development of adipocytes (By similarity). Specifically activated by 15-deoxy-delta12,14-prostaglandin J2 ligand during early adipogenesis, driving differentiation of all types of adipocytes (white, beige and brown) (By similarity). Acts together with retinoic acid receptor RXRA, forming the ARF6 complex, which acts as a key regulator of the tissue-specific adipocyte P2 (aP2) enhancer (By similarity). Following recruitment of TLE3, promotes differentiation of white adipocytes (By similarity). Following recruitment of PRDM16, promotes differentiation of myoblastic precursors into brown adipose cells (BAT), which are specialized in dissipating energy in the form of heat in response to cold or excess feeding (By similarity). Also mediates diffentiation of white adipocytes into beige adipocytes by mediating recruitment of PRDM16 (By similarity)\n(Microbial infection) Upon treatment with M.tuberculosis or its lipoprotein LpqH, phosphorylation of MAPK p38 and IL-6 production are modulated, probably via this protein","subunit":"Heterodimer with retinoic acid receptor, such as RXRA (By similarity). The heterodimer with the retinoic acid receptor RXRA is called adipocyte-specific transcription factor ARF6 (By similarity). Interacts with NCOA6 coactivator, leading to a strong increase in transcription of target genes (PubMed:10681503). Interacts with coactivator PPARBP, leading to a mild increase in transcription of target genes (By similarity). Interacts with NCOA7 in a ligand-inducible manner (PubMed:11971969). Interacts with NCOA1 and NCOA2 LXXLL motifs (PubMed:16919947, PubMed:9744270). Interacts with ASXL1, ASXL2, DNTTIP2, FAM120B, MAP2K1/MEK1, NR0B2, PDPK1, PRMT2 and TGFB1I1 (PubMed:12039952, PubMed:15047147, PubMed:15687259, PubMed:15976031, PubMed:17101779, PubMed:21047783). Interacts (when activated by agonist) with PPP5C (By similarity). Interacts with HELZ2 and THRAP3; the interaction stimulates the transcriptional activity of PPARG (PubMed:16239304, PubMed:23525231). Interacts with PER2, the interaction is ligand dependent and blocks PPARG recruitment to target promoters (By similarity). Interacts with NOCT (By similarity). Interacts with FOXO1 (acetylated form) (By similarity). Interacts with ACTN4 (PubMed:22351778). Interacts (when in the liganded conformation) with GPS2 (By similarity). Interacts with CRY1 and CRY2 in a ligand-dependent manner (By similarity). In the absence of hormonal ligand, interacts with TACC1 (PubMed:20078863). In macrophages, interacts with PAQR3 and STUB1; these interactions promote PPARG poylubiquitination and STUB1-mediated degradation (By similarity). Interacts with YTDC1 (via its intrinsically disordered region); the interaction prevents the ubiquitin-mediated proteasomal degradation of PPARG (By similarity)\nInteracts with CEBPA; promoting activation of the adipogenic program (By similarity). Interacts with PRDM16; promoting activation of brown and beige adipocytes (By similarity)","family":"Belongs to the nuclear hormone receptor family. NR1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16150867","20829347","23525231","25504154","8702406","8706692","9065481"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Ligand-activated transcription factor that forms obligate heterodimers with the retinoic acid receptor and acts as a key regulator of biological processes, such as adipocyte differentiation, lipid metabolism, glucose homeostasis and beta-oxidation of fatty acids (PubMed:16150867, PubMed:20829347, PubMed:23525231, PubMed:8702406, PubMed:8706692, PubMed:9065481).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"PPCS":{"hgnc":"HGNC:25686","symbol":"PPCS","accessions":["Q9HAB8"],"name":"Phosphopantothenate--cysteine ligase","length":"311","function":"Catalyzes the second step in the biosynthesis of coenzyme A from vitamin B5, where cysteine is conjugated to 4'-phosphopantothenate to form 4-phosphopantothenoylcysteine (PubMed:11923312, PubMed:12906824, PubMed:29754768). Has a preference for ATP over CTP as a cosubstrate (PubMed:11923312)","subunit":"Homodimer","family":"Belongs to the PPC synthetase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11923312","12906824","29754768"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Catalyzes the second step in the biosynthesis of coenzyme A from vitamin B5, where cysteine is conjugated to 4'-phosphopantothenate to form 4-phosphopantothenoylcysteine (PubMed:11923312, PubMed:12906824, PubMed:29754768).","function_evidence":"含实验支持条目；ECO:0000269","categories":"未归类"},"PPHLN1":{"hgnc":"HGNC:19369","symbol":"PPHLN1","accessions":["Q8NEY8"],"name":"Periphilin-1","length":"458","function":"RNA-binding component of the HUSH complex, a multiprotein complex that mediates epigenetic repression of mobile genetic elements, such as retroviruses and transposable elements (PubMed:15474462, PubMed:17963697, PubMed:26022416, PubMed:32976585, PubMed:39658355). The HUSH complex mainly represses LINE-1 (L1) retrotransposons that are still capable of transposition (PubMed:32976585, PubMed:39658355). The HUSH complex is recruited to genomic loci rich in H3K9me3 and is probably required to maintain transcriptional silencing by promoting recruitment of SETDB1, a histone methyltransferase that mediates further deposition of H3K9me3, as well as MORC2, a chromatin remodeler that compacts chromatin (PubMed:26022416). The HUSH complex is also involved in the silencing of unintegrated retroviral DNA: some part of the retroviral DNA formed immediately after infection remains unintegrated in the host genome and is transcriptionally repressed (PubMed:30487602). Within the HUSH complex, PPHLN1 acts as a mRNA-binding component, which specifically binds nascent transcripts of mobile genetic elements, enabling HUSH-dependent silencing of transcripts (PubMed:39658355). Contributes to the maintenance of the HUSH complex at chromatin (PubMed:26022416, PubMed:39013473). As part of the HUSH2 complex, promotes epigenetic repression of interferon-stimulated genes (PubMed:33144593, PubMed:39013473). May be involved in epithelial differentiation by contributing to epidermal integrity and barrier formation (PubMed:12853457)","subunit":"Homodimer (PubMed:12853457). Component of the HUSH complex; composed of TASOR, PPHLN1 and MPHOSPH8 (PubMed:26022416, PubMed:32976585, PubMed:39489739, PubMed:39658355). Component of the HUSH2 complex; composed of TASOR2, PPHLN1 and MPHOSPH8 (PubMed:39013473, PubMed:39489739). Interacts with SIN3A and HDAC1 (PubMed:17963697). May interact with PPL (PubMed:12853457)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12853457","15474462","17963697","26022416","30487602","32976585","33144593","39013473","39658355"],"location":"Nucleus；Cytoplasm；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；发育/分化；注释原文：RNA-binding component of the HUSH complex, a multiprotein complex that mediates epigenetic repression of mobile genetic elements, such as retroviruses and transposable elements (PubMed:15474462, PubMed:17963697, PubMed:26022416, PubMed:32976585, PubMed:39658355).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；免疫/炎症/细胞死亡；发育/分化"},"PPIA":{"hgnc":"HGNC:9253","symbol":"PPIA","accessions":["P62937"],"name":"Peptidyl-prolyl cis-trans isomerase A","length":"165","function":"Catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides (PubMed:2001362, PubMed:20676357, PubMed:21245143, PubMed:21593166, PubMed:25678563). Exerts a strong chemotactic effect on leukocytes partly through activation of one of its membrane receptors BSG/CD147, initiating a signaling cascade that culminates in MAPK/ERK activation (PubMed:11943775, PubMed:21245143). Activates endothelial cells (ECs) in a pro-inflammatory manner by stimulating activation of NF-kappa-B and ERK, JNK and p38 MAP-kinases and by inducing expression of adhesion molecules including SELE and VCAM1 (PubMed:15130913). Induces apoptosis in ECs by promoting the FOXO1-dependent expression of CCL2 and BCL2L11 which are involved in EC chemotaxis and apoptosis (PubMed:31063815). In response to oxidative stress, initiates proapoptotic and antiapoptotic signaling in ECs via activation of NF-kappa-B and AKT1 and up-regulation of antiapoptotic protein BCL2 (PubMed:23180369). Negatively regulates MAP3K5/ASK1 kinase activity, autophosphorylation and oxidative stress-induced apoptosis mediated by MAP3K5/ASK1 (PubMed:26095851). Necessary for the assembly of TARDBP in heterogeneous nuclear ribonucleoprotein (hnRNP) complexes and regulates TARDBP binding to RNA UG repeats and TARDBP-dependent expression of HDAC6, ATG7 and VCP which are involved in clearance of protein aggregates (PubMed:25678563). Plays an important role in platelet activation and aggregation (By similarity). Regulates calcium mobilization and integrin ITGA2B:ITGB3 bidirectional signaling via increased ROS production as well as by facilitating the interaction between integrin and the cell cytoskeleton (By similarity). Binds heparan sulfate glycosaminoglycans (PubMed:11943775). Inhibits replication of influenza A virus (IAV) (PubMed:19207730). Inhibits ITCH/AIP4-mediated ubiquitination of matrix protein 1 (M1) of IAV by impairing the interaction of ITCH/AIP4 with M1, followed by the suppression of the nuclear export of M1, and finally reduction of the replication of IAV (PubMed:22347431, PubMed:30328013)\n(Microbial infection) May act as a mediator between human SARS coronavirus nucleoprotein and BSG/CD147 in the process of invasion of host cells by the virus (PubMed:15688292)\n(Microbial infection) Stimulates RNA-binding ability of HCV NS5A in a peptidyl-prolyl cis-trans isomerase activity-dependent manner\n(Microbial infection) May act as a receptor for M.genitalium adhesin protein P140 (also called MgPa) (PubMed:29551599, PubMed:33013867)","subunit":"Interacts with protein phosphatase PPP3CA/calcineurin A (PubMed:12218175, PubMed:12357034). Interacts with PRPF19 isoform 2 (via N-terminus) (By similarity). Interacts with isoform 2 of BSG/CD147 (PubMed:11353871, PubMed:11943775, PubMed:15688292, PubMed:21245143). Interacts with FOXO1; the interaction promotes FOXO1 dephosphorylation, nuclear accumulation and transcriptional activity (PubMed:31063815). Interacts with integrin ITGA2B:ITGB3; the interaction is ROS and peptidyl-prolyl cis-trans isomerase (PPIase) activity-dependent and is increased in the presence of thrombin (By similarity). Interacts with MAP3K5 (PubMed:26095851). Interacts with TARDBP; the interaction is dependent on the RNA-binding activity of TARDBP and the PPIase activity of PPIA/CYPA and the acetylation of PPIA/CYPA at Lys-125 favors the interaction (PubMed:25678563). Interacts with HNRNPA1, HNRNPA2B1, HNRNPC, RBMX, HNRNPK and HNRNPM (PubMed:25678563)\n(Microbial infection) Interacts with HIV-1 capsid protein (PubMed:20364129, PubMed:8513493)\n(Microbial infection) Interacts with human SARS coronavirus nucleoprotein\n(Microbial infection) Interacts with measles virus nucleoprotein\n(Microbial infection) Interacts with influenza A virus matrix protein 1\n(Microbial infection) Interacts with M.genitalium adhesin P140 protein (also called MgPa)\n(Microbial infection) Interacts with HCV NS5A; the interaction stimulates RNA-binding ability of NS5A and is dependent on the peptidyl-prolyl cis-trans isomerase activity of PPIA/CYPA","family":"Belongs to the cyclophilin-type PPIase family. PPIase A subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11943775","15130913","15688292","19207730","2001362","20676357","21245143","21593166","22347431","23180369","25678563","26095851","29551599","30328013","31063815","33013867"],"location":"Cytoplasm；Secreted；Nucleus；Cell membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；RNA加工/剪接；核质运输；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides (PubMed:2001362, PubMed:20676357, PubMed:21245143, PubMed:21593166, PubMed:25678563).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000305","categories":"泛素化/蛋白稳态；RNA加工/剪接；核质运输；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"PPID":{"hgnc":"HGNC:9257","symbol":"PPID","accessions":["Q08752"],"name":"Peptidyl-prolyl cis-trans isomerase D","length":"370","function":"PPIase that catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides and may therefore assist protein folding (PubMed:11350175, PubMed:20676357). Proposed to act as a co-chaperone in HSP90 complexes such as in unligated steroid receptors heterocomplexes. Different co-chaperones seem to compete for association with HSP90 thus establishing distinct HSP90-co-chaperone-receptor complexes with the potential to exert tissue-specific receptor activity control. May have a preference for estrogen receptor complexes and is not found in glucocorticoid receptor complexes. May be involved in cytoplasmic dynein-dependent movement of the receptor from the cytoplasm to the nucleus. May regulate MYB by inhibiting its DNA-binding activity. Involved in regulation of AHR signaling by promoting the formation of the AHR:ARNT dimer; the function is independent of HSP90 but requires the chaperone activity. Involved in regulation of UV radiation-induced apoptosis. Promotes cell viability in anaplastic lymphoma kinase-positive anaplastic large-cell lymphoma (ALK+ ALCL) cell lines\n(Microbial infection) May be involved in hepatitis C virus (HCV) replication and release","subunit":"Identified in ESR1 or NR3C1/GCR steroid receptor-chaperone complexes. Found in HSP90 chaperone complexes with kinase clients LCK or EIF2AK1. Two monomers associate with one HSP90 homodimer. Interacts with HSP90AA1. Interacts with HSP90AB1; PPID and FKBP4 compete for binding to HSP90AB1 and the interaction is mutually exclusive with the PPID:HSPA8 interaction. Interacts with HSPA8; PPID and STIP1 but not FKBP4 compete for binding to HSPA8 and the interaction is mutually exclusive with the PPID:HSP90AB1 interaction. Interacts with S100A1 and S100A2; the interactions dissociate the PPID:HSP90AA1 interaction. Interacts with S100A6. Interacts with MYB, ILF2, XRCC6, RACK1 and RPS3. Interacts with cytoplasmic dynein 1 intermediate chain (DYNC1I1 or DYNC1I2)","family":"Belongs to the cyclophilin-type PPIase family. PPIase D subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11350175","18708059","19932913","20676357","21711559","22681779","23220213","9659917"],"location":"Cytoplasm；Nucleus, nucleolus；Nucleus, nucleoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：PPIase that catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides and may therefore assist protein folding (PubMed:11350175, PubMed:20676357).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"PPIE":{"hgnc":"HGNC:9258","symbol":"PPIE","accessions":["Q9UNP9"],"name":"Peptidyl-prolyl cis-trans isomerase E","length":"301","function":"Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11991638, PubMed:28076346). Combines RNA-binding and PPIase activities (PubMed:18258190, PubMed:20460131, PubMed:20677832, PubMed:8977107). Binds mRNA and has a preference for single-stranded RNA molecules with poly-A and poly-U stretches, suggesting it binds to the poly(A)-region in the 3'-UTR of mRNA molecules (PubMed:18258190, PubMed:20460131, PubMed:8977107). Catalyzes the cis-trans isomerization of proline imidic peptide bonds in proteins (PubMed:18258190, PubMed:20541251, PubMed:20677832, PubMed:8977107). Inhibits KMT2A activity; this requires proline isomerase activity (PubMed:20460131, PubMed:20541251, PubMed:20677832)","subunit":"Identified in the spliceosome C complex (PubMed:11991638, PubMed:28076346). Component of the XAB2 complex, a multimeric protein complex composed of XAB2, PRPF19, AQR, ZNF830, ISY1, and PPIE (PubMed:17981804). Identified in a pentameric intron-binding (IB) complex composed of AQR, XAB2, ISY1, ZNF830 and PPIE that is incorporated into the spliceosome as a preassembled complex (PubMed:25599396). The IB complex does not contain PRPF19 (PubMed:25599396). Interacts (via RNA-binding domain) with KMT2A (via the third PHD-type zinc-finger) (PubMed:20460131, PubMed:20541251, PubMed:20677832)","family":"Belongs to the cyclophilin-type PPIase family. PPIase E subfamily","domains":[],"function_pmids":["11991638","18258190","20460131","20541251","20677832","28076346","8977107"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11991638, PubMed:28076346). Combines RNA-binding and PPIase activities (PubMed:18258190, PubMed:20460131, PubMed:20677832, PubMed:8977107). Binds mRNA and has a preference for single-stranded RNA molecules with poly-A and poly-U stretches, suggesting it binds to the poly(A)-region in the 3'-UTR of mRNA molecules (PubMed:18258190, PubMed:20460131, PubMed:8977107). Catalyzes the cis-trans isomerization of proline imidic peptide bonds in proteins (PubMed:18258190, PubMed:20541251, PubMed:20677832, PubMed:8977107). Inhibits KMT2A activity; this requires proline isomerase activity (PubMed:20460131, PubMed:20541251, PubMed:20677832)"},"PPIG":{"hgnc":"HGNC:14650","symbol":"PPIG","accessions":["Q13427"],"name":"Peptidyl-prolyl cis-trans isomerase G","length":"754","function":"PPIase that catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides and may therefore assist protein folding (PubMed:20676357). May be implicated in the folding, transport, and assembly of proteins. May play an important role in the regulation of pre-mRNA splicing","subunit":"Interacts with CLK1, PNN and with the phosphorylated C-terminal domain of RNA polymerase II","family":"","domains":[],"function_pmids":["20676357"],"location":"Nucleus matrix; Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"PPIase that catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides and may therefore assist protein folding (PubMed:20676357). May be implicated in the folding, transport, and assembly of proteins. May play an important role in the regulation of pre-mRNA splicing"},"PPIH":{"hgnc":"HGNC:14651","symbol":"PPIH","accessions":["O43447"],"name":"Peptidyl-prolyl cis-trans isomerase H","length":"177","function":"PPIase that catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides and may therefore assist protein folding (PubMed:20676357). Participates in pre-mRNA splicing. May play a role in the assembly of the U4/U5/U6 tri-snRNP complex, one of the building blocks of the spliceosome. May act as a chaperone","subunit":"Interacts directly with PRPF4. Part of a heteromeric complex containing PPIH, PRPF3 and PRPF4 that is stable in the absence of RNA. Component of the U4/U6-U5 tri-snRNP complex composed of the U4, U6 and U5 snRNAs and at least PRPF3, PRPF4, PRPF6, PRPF8, PRPF31, SNRNP200, TXNL4A, SNRNP40, DDX23, CD2BP2, PPIH, SNU13, EFTUD2, SART1 and USP39. Heterodimer with PRPF18","family":"Belongs to the cyclophilin-type PPIase family. PPIase H subfamily","domains":[],"function_pmids":["11823439","12875835","20676357","9570313"],"location":"Nucleus speckle; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"PPIase that catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides and may therefore assist protein folding (PubMed:20676357). Participates in pre-mRNA splicing. May play a role in the assembly of the U4/U5/U6 tri-snRNP complex, one of the building blocks of the spliceosome. May act as a chaperone"},"PPIL1":{"hgnc":"HGNC:9260","symbol":"PPIL1","accessions":["Q9Y3C6"],"name":"Peptidyl-prolyl cis-trans isomerase-like 1","length":"166","function":"Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11991638, PubMed:28076346, PubMed:28502770, PubMed:33220177). PPIases accelerate the folding of proteins. Catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides (PubMed:16595688). Catalyzes prolyl peptide bond isomerization in CDC40/PRP17 (PubMed:33220177). Plays an important role in embryonic brain development; this function is independent of its isomerase activity (PubMed:33220177)","subunit":"Identified in the spliceosome C complex (PubMed:11991638, PubMed:28076346, PubMed:28502770). Interacts with SNW1/SKIP (PubMed:16595688, PubMed:20368803, PubMed:33220177). Interacts with CDC40/PRP17; this interaction leads to CDC40 isomerization (PubMed:33220177). Interacts with RBM22 (PubMed:33220177)","family":"Belongs to the cyclophilin-type PPIase family. PPIL1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11991638","16595688","28076346","28502770","33220177"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；发育/分化；注释原文：Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11991638, PubMed:28076346, PubMed:28502770, PubMed:33220177).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；发育/分化"},"PPIL2":{"hgnc":"HGNC:9261","symbol":"PPIL2","accessions":["Q13356"],"name":"RING-type E3 ubiquitin-protein ligase PPIL2","length":"520","function":"Has a ubiquitin-protein ligase activity acting as an E3 ubiquitin protein ligase or as an ubiquitin-ubiquitin ligase promoting elongation of ubiquitin chains on substrates. By mediating 'Lys-48'-linked polyubiquitination of proteins could target them for proteasomal degradation (PubMed:11435423). May also function as a chaperone, playing a role in transport to the cell membrane of BSG/Basigin for instance (PubMed:15946952). Probable inactive PPIase with no peptidyl-prolyl cis-trans isomerase activity (PubMed:20676357). As a component of the minor spliceosome, involved in the splicing of U12-type introns in pre-mRNAs (Probable)","subunit":"Component of the minor spliceosome, which splices U12-type introns. Within this complex, interacts with PRPF8/PRP8, EFTUD2/SNU114 and PLRG1 (PubMed:33509932). Interacts with isoform 2 of BSG (PubMed:15946952). Interacts (via the PPIase cyclophilin-type domain) with CRNKL1; they may form a trimeric complex with HSP90","family":"Belongs to the cyclophilin-type PPIase family. PPIL2 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11435423","15946952","20676357","33509932"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；RNA加工/剪接；注释原文：Has a ubiquitin-protein ligase activity acting as an E3 ubiquitin protein ligase or as an ubiquitin-ubiquitin ligase promoting elongation of ubiquitin chains on substrates.","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"泛素化/蛋白稳态；RNA加工/剪接"},"PPIL3":{"hgnc":"HGNC:9262","symbol":"PPIL3","accessions":["Q9H2H8"],"name":"Peptidyl-prolyl cis-trans isomerase-like 3","length":"161","function":"PPIases accelerate the folding of proteins. It catalyzes the cis-trans isomerization of proline imidic peptide bonds in oligopeptides. May be involved in pre-mRNA splicing","subunit":"Identified in the spliceosome C complex","family":"Belongs to the cyclophilin-type PPIase family. PPIL3 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：PPIases accelerate the folding of proteins.","function_evidence":"数据库整理/推断；按原文限定；","categories":"RNA加工/剪接"},"PPM1A":{"hgnc":"HGNC:9275","symbol":"PPM1A","accessions":["P35813"],"name":"Protein phosphatase 1A","length":"382","function":"Enzyme with a broad specificity. Negatively regulates TGF-beta signaling through dephosphorylating SMAD2 and SMAD3, resulting in their dissociation from SMAD4, nuclear export of the SMADs and termination of the TGF-beta-mediated signaling. Dephosphorylates PRKAA1 and PRKAA2. Plays an important role in the termination of TNF-mediated NF-kappa-B activation through dephosphorylating and inactivating IKBKB/IKKB","subunit":"Monomer. Interacts with SMAD2; the interaction dephosphorylates SMAD2 in its C-terminal SXS motif resulting in disruption of the SMAD2/SMAD4 complex, SMAD2 nuclear export and termination of the TGF-beta-mediated signaling. Interacts with SMAD2; the interaction dephosphorylates SMAD2 in its C-terminal SXS motif resulting in disruption of the SMAD2/SMAD4 complex, SMAD2 nuclear export and termination of the TGF-beta-mediated signaling. Interacts with the phosphorylated form of IKBKB/IKKB","family":"Belongs to the PP2C family","domains":[],"function_pmids":["16751101","18930133"],"location":"Nucleus; Cytoplasm, cytosol; Membrane","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Enzyme with a broad specificity. Negatively regulates TGF-beta signaling through dephosphorylating SMAD2 and SMAD3, resulting in their dissociation from SMAD4, nuclear export of the SMADs and termination of the TGF-beta-mediated signaling. Dephosphorylates PRKAA1 and PRKAA2. Plays an important role in the termination of TNF-mediated NF-kappa-B activation through dephosphorylating and inactivating IKBKB/IKKB"},"PPM1B":{"hgnc":"HGNC:9276","symbol":"PPM1B","accessions":["O75688"],"name":"Protein phosphatase 1B","length":"479","function":"Enzyme with a broad specificity. Dephosphorylates CDK2 and CDK6 in vitro. Dephosphorylates PRKAA1 and PRKAA2. Inhibits TBK1-mediated antiviral signaling by dephosphorylating it at 'Ser-172'. Plays an important role in the termination of TNF-mediated NF-kappa-B activation through dephosphorylating and inactivating IKBKB/IKKB","subunit":"Monomer (By similarity). Interacts with PAK6. Interacts with the phosphorylated form of IKBKB/IKKB","family":"Belongs to the PP2C family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18930133","22750291"],"location":"Cytoplasm, cytosol；Membrane；Lipid-anchor","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"PP2C型丝/苏氨酸磷酸酶，可调节信号磷酸化，具体底物见原文。","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号；免疫/炎症/细胞死亡"},"PPM1G":{"hgnc":"HGNC:9278","symbol":"PPM1G","accessions":["O15355"],"name":"Protein phosphatase 1G","length":"546","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"Interacts with NOL3; may dephosphorylate NOL3","family":"Belongs to the PP2C family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm；Membrane；Lipid-anchor","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"激酶/磷酸化信号"},"PPM1H":{"hgnc":"HGNC:18583","symbol":"PPM1H","accessions":["Q9ULR3"],"name":"Protein phosphatase 1H","length":"514","function":"Dephosphorylates CDKN1B at 'Thr-187', thus removing a signal for proteasomal degradation","subunit":"无可用SUBUNIT段","family":"Belongs to the PP2C family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["22586611"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；激酶/磷酸化信号；注释原文：Dephosphorylates CDKN1B at 'Thr-187', thus removing a signal for proteasomal degradation","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；激酶/磷酸化信号"},"PPM1L":{"hgnc":"HGNC:16381","symbol":"PPM1L","accessions":["Q5SGD2"],"name":"Protein phosphatase 1L","length":"360","function":"Acts as a suppressor of the SAPK signaling pathways by associating with and dephosphorylating MAP3K7/TAK1 and MAP3K5, and by attenuating the association between MAP3K7/TAK1 and MAP2K4 or MAP2K6","subunit":"Interacts with MAP3K7/TAK1 (By similarity). Interacts with MAP3K5","family":"Belongs to the PP2C family","domains":[],"function_pmids":["17456047"],"location":"Membrane","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Acts as a suppressor of the SAPK signaling pathways by associating with and dephosphorylating MAP3K7/TAK1 and MAP3K5, and by attenuating the association between MAP3K7/TAK1 and MAP2K4 or MAP2K6"},"PPME1":{"hgnc":"HGNC:30178","symbol":"PPME1","accessions":["Q9Y570"],"name":"Protein phosphatase methylesterase 1","length":"386","function":"Demethylates proteins that have been reversibly carboxymethylated. Demethylates PPP2CB (in vitro) and PPP2CA. Binding to PPP2CA displaces the manganese ion and inactivates the enzyme","subunit":"Binds PPP2CA and PPP2CB","family":"Belongs to the AB hydrolase superfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10318862"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Demethylates proteins that have been reversibly carboxymethylated.","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"PPP1CA":{"hgnc":"HGNC:9281","symbol":"PPP1CA","accessions":["P62136"],"name":"Serine/threonine-protein phosphatase PP1-alpha catalytic subunit","length":"330","function":"Protein phosphatase that associates with over 200 regulatory proteins to form highly specific holoenzymes which dephosphorylate hundreds of biological targets (PubMed:28216226, PubMed:30158517, PubMed:35768504, PubMed:35830882, PubMed:35831509, PubMed:36175670, PubMed:39603239, PubMed:39603240). Protein phosphatase 1 (PP1) is essential for cell division, transcription elongation, and participates in the regulation of glycogen metabolism, muscle contractility and protein synthesis (PubMed:35768504, PubMed:35830882, PubMed:35831509, PubMed:36175670, PubMed:39603239, PubMed:39603240). Involved in regulation of ionic conductances and long-term synaptic plasticity. May play an important role in dephosphorylating substrates such as the postsynaptic density-associated Ca(2+)/calmodulin dependent protein kinase II. Catalytic component of the PNUTS-PP1 protein phosphatase complex, a protein phosphatase 1 (PP1) complex that promotes RNA polymerase II transcription pause-release, allowing transcription elongation: the PNUTS-PP1 complex mediates the release of RNA polymerase II from promoter-proximal region of genes by catalyzing dephosphorylation of proteins involved in transcription, such as AFF4, CDK9, MEPCE, INTS12, NCBP1, POLR2M/GDOWN1 and SUPT6H (PubMed:39603239, PubMed:39603240). The PNUTS-PP1 complex also regulates transcription termination by mediating dephosphorylation of SUPT5H in termination zones downstream of poly(A) sites, thereby promoting deceleration of RNA polymerase II transcription (PubMed:31677974). PNUTS-PP1 complex is also involved in the response to replication stress by mediating dephosphorylation of POLR2A at 'Ser-5' of the CTD, promoting RNA polymerase II degradation (PubMed:33264625). PNUTS-PP1 also plays a role in the control of chromatin structure and cell cycle progression during the transition from mitosis into interphase (PubMed:20516061). Regulates NEK2 function in terms of kinase activity and centrosome number and splitting, both in the presence and absence of radiation-induced DNA damage (PubMed:17283141). Regulator of neural tube and optic fissure closure, and enteric neural crest cell (ENCCs) migration during development (By similarity). In balance with CSNK1D and CSNK1E, determines the circadian period length, through the regulation of the speed and rhythmicity of PER1 and PER2 phosphorylation (PubMed:21712997). May dephosphorylate CSNK1D and CSNK1E (PubMed:21712997). Dephosphorylates the 'Ser-418' residue of FOXP3 in regulatory T-cells (Treg) from patients with rheumatoid arthritis, thereby inactivating FOXP3 and rendering Treg cells functionally defective (PubMed:23396208). Dephosphorylates CENPA (PubMed:25556658). Dephosphorylates the 'Ser-139' residue of ATG16L1 causing dissociation of ATG12-ATG5-ATG16L1 complex, thereby inhibiting autophagy (PubMed:26083323). Together with PPP1CC (PP1-gamma subunit), dephosphorylates IFIH1/MDA5 and RIG-I leading to their activation and a functional innate immune response (PubMed:23499489). Core component of the SHOC2-MRAS-PP1c (SMP) holophosphatase complex that regulates the MAPK pathway activation (PubMed:35768504, PubMed:35830882, PubMed:35831509, PubMed:36175670). The SMP complex specifically dephosphorylates the inhibitory phosphorylation at 'Ser-259' of RAF1 kinase, 'Ser-365' of BRAF kinase and 'Ser-214' of ARAF kinase, stimulating their kinase activities (PubMed:35768504, PubMed:35830882, PubMed:35831509, PubMed:36175670). The SMP complex enhances the dephosphorylation activity and substrate specificity of PP1c (PubMed:35768504, PubMed:36175670)\n(Microbial infection) Necessary for alphaviruses replication","subunit":"PP1 comprises a catalytic subunit, PPP1CA, PPP1CB or PPP1CC, which is folded into its native form by inhibitor 2 and glycogen synthetase kinase 3, and then complexed to one or several targeting or regulatory subunits. PPP1R12A, PPP1R12B and PPP1R12C mediate binding to myosin. PPP1R3A (in skeletal muscle), PPP1R3B (in liver), PPP1R3C, PPP1R3D and PPP1R3F (in brain) mediate binding to glycogen. Interacts with PPP1R39 (By similarity). Interacts with BTBD10 (By similarity). Interacts with KCTD20 (By similarity). Interacts with PPP1R9A and PPP1R9B. Part of a complex containing PPP1R15B, PP1 and NCK1/2. Interacts with PHACTR4; which acts as an activator of PP1 activity (By similarity). Interacts with PPP1R15A and PPP1R15B; the interactions mediate binding to EIF2S1 (PubMed:26095357). Interacts with PPP1R7. Interacts with YLPM1. Forms a complex with ILF2, ILF3, YLPM1, KHDRBS1, RBMX and NCOA5. Interacts with NOM1 and PPP1R8. Interacts with PPP1R16B. Interacts with RPSA only in the presence of PPP1R16B. Component of the PNUTS-PP1 phosphatase complex, composed of PPP1R10/PNUTS, TOX4, WDR82, and PPP1CA or PPP1CB or PPP1CC (PubMed:20516061, PubMed:31677974, PubMed:33264625, PubMed:39603240, PubMed:39603239, PubMed:39446389). Interacts with PPP1R10/PNUTS and PPP1R8. Interacts with WDR82 in the presence of PPP1R10/PNUTS. Interacts with TRIM28; the interaction dephosphorylates TRIM28 on 'Ser-824' and forms a complex at the p21 promoter site. Interacts with isoform 1 and isoform 4 of NEK2. Interacts with FER; this promotes phosphorylation at Thr-320. Interacts with DAB2; the interaction is mutually exclusive with the AXIN1:PPP1CA interaction. Interacts with FOXP3 (PubMed:23396208). Interacts with CENPA (PubMed:25556658). Interacts with ATG16L1 (PubMed:26083323). Found in a complex with PPP1CA, PPP1CC, SHC1 and PEAK1 (PubMed:23846654). Interacts with tensin TNS1 (PubMed:19826001). Interacts with SAXO4, PPP1R21, PPP1R26, PPP1R27, PPP1R35, PPP1R36, PPP1R37, SH3RF2, ELFN1 and ELFN2 (PubMed:19389623). Interacts with TPRN; the interaction results in inhibition of PPC1A phosphatase activity (PubMed:23213405). Interacts with SKA1 (via C-terminus); the interaction is direct and required for the recruitment of PP1 to the kinetochore (PubMed:26981768). Interacts with the KNL1 complex subunit KNL1; the interaction is direct and mutually exclusive with KNL1 binding to microtubules (PubMed:30100357). Component of the SHOC2-MRAS-PP1c (SMP) complex consisting of SHOC2, GTP-bound M-Ras/MRAS and the catalytic subunit of protein phosphatase 1 (either PPP1CA, PPP1CB or PPP1CC) (PubMed:35768504, PubMed:35830882, PubMed:35831509, PubMed:36175670). SHOC2 and PP1c preferably bind M-Ras/MRAS, but they also bind K-Ras/KRAS, N-Ras/NRAS and H-Ras/HRAS; these interactions are GTP-dependent and both SHOC2 and PP1c are required to form a stable complex (PubMed:35768504, PubMed:35830882, PubMed:35831509, PubMed:36175670). Interacts with SHOC2 in the absence of Ras GTPases (PubMed:35768504, PubMed:35831509). Interacts with LRRC7 (PubMed:39256359)\n(Microbial infection) Interacts with HHV-1 ICP34.5\n(Microbial infection) Interacts with Venezuelan equine encephalitis virus (VEEV) capsid protein; this interaction dephosphorylates the capsid protein, which increases its ability to bind to the viral genome","family":"Belongs to the PPP phosphatase family. PP-1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17283141","20516061","21712997","23396208","23499489","25556658","26083323","28216226","29769351","30158517","31677974","33264625","35768504","35830882","35831509","36175670","39603239","39603240"],"location":"Cytoplasm；Nucleus；Nucleus, nucleoplasm；Nucleus, nucleolus；Postsynaptic density","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Protein phosphatase that associates with over 200 regulatory proteins to form highly specific holoenzymes which dephosphorylate hundreds of biological targets (PubMed:28216226, PubMed:30158517, PubMed:35768504, PubMed:35830882, PubMed:35831509, PubMed:36175670, PubMed:39603239, PubMed:39603240).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"PPP1CB":{"hgnc":"HGNC:9282","symbol":"PPP1CB","accessions":["P62140"],"name":"Serine/threonine-protein phosphatase PP1-beta catalytic subunit","length":"327","function":"Protein phosphatase that associates with over 200 regulatory proteins to form highly specific holoenzymes which dephosphorylate hundreds of biological targets. Protein phosphatase (PP1) is essential for cell division, it participates in the regulation of glycogen metabolism, muscle contractility and protein synthesis. Involved in regulation of ionic conductances and long-term synaptic plasticity. Component of the PTW/PP1 phosphatase complex, which plays a role in the control of chromatin structure and cell cycle progression during the transition from mitosis into interphase. In balance with CSNK1D and CSNK1E, determines the circadian period length, through the regulation of the speed and rhythmicity of PER1 and PER2 phosphorylation. May dephosphorylate CSNK1D and CSNK1E. Dephosphorylates the 'Ser-418' residue of FOXP3 in regulatory T-cells (Treg) from patients with rheumatoid arthritis, thereby inactivating FOXP3 and rendering Treg cells functionally defective (PubMed:23396208). Core component of the SHOC2-MRAS-PP1c (SMP) holophosphatase complex that regulates the MAPK pathway activation (PubMed:35768504, PubMed:35831509, PubMed:36175670). The SMP complex specifically dephosphorylates the inhibitory phosphorylation at 'Ser-259' of RAF1 kinase, 'Ser-365' of BRAF kinase and 'Ser-214' of ARAF kinase, stimulating their kinase activities (PubMed:35768504, PubMed:35831509, PubMed:36175670). The SMP complex enhances the dephosphorylation activity and substrate specificity of PP1c (PubMed:35768504, PubMed:36175670)","subunit":"PP1 comprises a catalytic subunit, PPP1CA, PPP1CB or PPP1CC, which is folded into its native form by inhibitor 2 and glycogen synthetase kinase 3, and then complexed to one or several targeting or regulatory subunits. The targeting or regulatory subunits determine the substrate specificity of PP1. PPP1R12A, PPP1R12B and PPP1R12C mediate binding to myosin. PPP1R3A (in skeletal muscle), PPP1R3B (in liver), PPP1R3C, PPP1R3D and PPP1R3F (in brain) mediate binding to glycogen. Part of a complex containing PPP1R15B, PP1 and NCK1/2 (By similarity). Interacts with PPP1R7 and PPP1R12C. PPP1R15A and PPP1R15B mediate binding to EIF2S1. Interacts with PPP1R16B. Component of the PTW/PP1 phosphatase complex, composed of PPP1R10/PNUTS, TOX4, WDR82, and PPP1CA or PPP1CB or PPP1CC. Interacts with PPP1R8. Interacts with TRIM28; the interaction is weak. Interacts with PPP1R12A and NUAK1; the interaction is direct. Interacts with FOXP3. Interacts with RRP1B (PubMed:20926688). Interacts with SERPINE1 (PubMed:28296156). Interacts with LZTR1 (PubMed:30368668). Component of the SHOC2-MRAS-PP1c (SMP) complex consisting of SHOC2, GTP-bound M-Ras/MRAS and the catalytic subunit of protein phosphatase 1 (either PPP1CA, PPP1CB or PPP1CC) (PubMed:35768504, PubMed:35831509, PubMed:36175670). SHOC2 and PP1c preferably bind M-Ras/MRAS, but they also bind K-Ras/KRAS, N-Ras/NRAS and H-Ras/HRAS; these interactions are GTP-dependent and both SHOC2 and PP1c are required to form a stable complex (PubMed:35768504, PubMed:35831509, PubMed:36175670). Interacts with SHOC2 in the absence of Ras GTPases (PubMed:35768504, PubMed:35831509)","family":"Belongs to the PPP phosphatase family. PP-1 subfamily","domains":[],"function_pmids":["20516061","21712997","23396208","35768504","35831509","36175670"],"location":"Cytoplasm; Nucleus; Nucleus, nucleoplasm; Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Protein phosphatase that associates with over 200 regulatory proteins to form highly specific holoenzymes which dephosphorylate hundreds of biological targets. Protein phosphatase (PP1) is essential for cell division, it participates in the regulation of glycogen metabolism, muscle contractility and protein synthesis. Involved in regulation of ionic conductances and long-term synaptic plasticity. Component of the PTW/PP1 phosphatase complex, which plays a role in the control of chromatin structure and cell cycle progression during the transition from mitosis into interphase. In balance with CSNK1D and CSNK1E, determines the circadian period length, through the regulation of the speed and rhythmicity of PER1 and PER2 phosphorylation. May dephosphorylate CSNK1D and CSNK1E. Dephosphorylates the 'Ser-418' residue of FOXP3 in regulatory T-cells (Treg) from patients with rheumatoid arthritis, thereby inactivating FOXP3 and rendering Treg cells functionally defective (PubMed:23396208). Core component of the SHOC2-MRAS-PP1c (SMP) holophosphatase complex that regulates the MAPK pathway activation (PubMed:35768504, PubMed:35831509, PubMed:36175670). The SMP complex specifically dephosphorylates the inhibitory phosphorylation at 'Ser-259' of RAF1 kinase, 'Ser-365' of BRAF kinase and 'Ser-214' of ARAF kinase, stimulating their kinase activities (PubMed:35768504, PubMed:35831509, PubMed:36175670). The SMP complex enhances the dephosphorylation activity and substrate specificity of PP1c (PubMed:35768504, PubMed:36175670)"},"PPP1CC":{"hgnc":"HGNC:9283","symbol":"PPP1CC","accessions":["P36873"],"name":"Serine/threonine-protein phosphatase PP1-gamma catalytic subunit","length":"323","function":"Protein phosphatase that associates with over 200 regulatory proteins to form highly specific holoenzymes which dephosphorylate hundreds of biological targets (PubMed:17936702, PubMed:25012651). Protein phosphatase 1 (PP1) is essential for cell division, and participates in the regulation of glycogen metabolism, muscle contractility and protein synthesis. Dephosphorylates RPS6KB1 (PubMed:17936702). Involved in regulation of ionic conductances and long-term synaptic plasticity. May play an important role in dephosphorylating substrates such as the postsynaptic density-associated Ca(2+)/calmodulin dependent protein kinase II. Component of the PTW/PP1 phosphatase complex, which plays a role in the control of chromatin structure and cell cycle progression during the transition from mitosis into interphase (PubMed:20516061). In balance with CSNK1D and CSNK1E, determines the circadian period length, through the regulation of the speed and rhythmicity of PER1 and PER2 phosphorylation (PubMed:21712997). May dephosphorylate CSNK1D and CSNK1E (By similarity). Regulates the recruitment of the SKA complex to kinetochores (PubMed:28982702). Dephosphorylates the 'Ser-418' residue of FOXP3 in regulatory T-cells (Treg) from patients with rheumatoid arthritis, thereby inactivating FOXP3 and rendering Treg cells functionally defective (PubMed:23396208). Together with PPP1CA (PP1-alpha subunit), dephosphorylates IFIH1/MDA5 and RIG-I leading to their activation and a functional innate immune response (PubMed:23499489). Core component of the SHOC2-MRAS-PP1c (SMP) holophosphatase complex that regulates the MAPK pathway activation (PubMed:35768504, PubMed:35831509). The SMP complex specifically dephosphorylates the inhibitory phosphorylation at 'Ser-259' of RAF1 kinase, 'Ser-365' of BRAF kinase and 'Ser-214' of ARAF kinase, stimulating their kinase activities (PubMed:35768504, PubMed:35831509). Dephosphorylates MKI67 at the onset of anaphase (PubMed:25012651). The SMP complex enhances the dephosphorylation activity and substrate specificity of PP1c (PubMed:35768504, PubMed:35831509)","subunit":"PP1 comprises a catalytic subunit, PPP1CA, PPP1CB or PPP1CC, which is folded into its native form by inhibitor 2 and glycogen synthetase kinase 3, and then complexed to one or several targeting or regulatory subunits. PPP1R12A, PPP1R12B and PPP1R12C mediate binding to myosin. PPP1R3A (in skeletal muscle), PPP1R3B (in liver), PPP1R3C, PPP1R3D and PPP1R3F (in brain) mediate binding to glycogen. Interacts with cyanobacterial toxin microcystin; disulfide-linked. Interacts with PPP1R3B and PPP1R7. Isoform 2 interacts with SPZ1 (By similarity). Interacts with CDCA2. PPP1R15A and PPP1R15B mediate binding to EIF2S1. Part of a complex containing PPP1R15B, PP1 and NCK1/2. Interacts with IKFZ1; the interaction targets PPP1CC to pericentromeric heterochromatin, dephosphorylates IKAROS, stabilizes it and prevents it from degradation. Interacts with PPP1R42; the interaction is direct (By similarity). Interacts with NOM1 and PPP1R8. Component of the PTW/PP1 phosphatase complex, composed of PPP1R10/PNUTS, TOX4, WDR82, and PPP1CA or PPP1CB or PPP1CC. Interacts with PPP1R8. Interacts with isoform 1 and isoform 4 NEK2. Interacts with URI1; the interaction is phosphorylation-dependent and occurs in a growth factor-dependent manner. Interacts with FOXP3. Interacts with TMEM225 (via RVxF motif) (By similarity). Interacts with MKI67 (PubMed:24867636). Interacts with RRP1B; this targets PPP1CC to the nucleolus (PubMed:20926688). Interacts with PPP1R2B (PubMed:23506001). Found in a complex with PPP1CA, PPP1CC, SHC1 and PEAK1 (PubMed:23846654). Interacts with DYNLT4 (PubMed:23789093). Interacts (via RVxF motif) with FIRRM; regulates PLK1 kinase activity (PubMed:34260926). Interacts with the KNL1 complex subunit KNL1; the interaction is direct and mutually exclusive with KNL1 binding to microtubules (PubMed:30100357). Component of the SHOC2-MRAS-PP1c (SMP) complex consisting of SHOC2, GTP-bound M-Ras/MRAS and the catalytic subunit of protein phosphatase 1 (either PPP1CA, PPP1CB or PPP1CC) (PubMed:35768504, PubMed:35831509). SHOC2 and PP1c preferably bind M-Ras/MRAS, but they also bind K-Ras/KRAS, N-Ras/NRAS and H-Ras/HRAS; these interactions are GTP-dependent and both SHOC2 and PP1c are required to form a stable complex (PubMed:35768504, PubMed:35831509). Interacts with SHOC2 in the absence of Ras GTPases (PubMed:35768504)","family":"Belongs to the PPP phosphatase family. PP-1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17936702","20516061","21712997","23396208","23499489","25012651","28982702","35768504","35831509"],"location":"Cytoplasm；Nucleus；Nucleus, nucleolus；Nucleus, nucleoplasm；Nucleus speckle；Chromosome, centromere, kinetochore；Cleavage furrow；Midbody；Mitochondrion；Cytoplasm, cytoskeleton, microtubule organizing center","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Protein phosphatase that associates with over 200 regulatory proteins to form highly specific holoenzymes which dephosphorylate hundreds of biological targets (PubMed:17936702, PubMed:25012651).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"PPP1R10":{"hgnc":"HGNC:9284","symbol":"PPP1R10","accessions":["Q96QC0"],"name":"Serine/threonine-protein phosphatase 1 regulatory subunit 10","length":"940","function":"Substrate-recognition component of the PNUTS-PP1 protein phosphatase complex, a protein phosphatase 1 (PP1) complex that promotes RNA polymerase II transcription pause-release, allowing transcription elongation (PubMed:39603239, PubMed:39603240). Promoter-proximal pausing by RNA polymerase II is a transcription halt following transcription initiation but prior to elongation, which acts as a checkpoint to control that transcripts are favorably configured for transcriptional elongation (PubMed:39603239, PubMed:39603240). The PNUTS-PP1 complex mediates the release of RNA polymerase II from promoter-proximal region of genes by catalyzing dephosphorylation of proteins involved in transcription, such as AFF4, CDK9, MEPCE, INTS12, NCBP1, POLR2M/GDOWN1 and SUPT6H (PubMed:39603239, PubMed:39603240). The PNUTS-PP1 complex also regulates RNA polymerase II transcription termination by mediating dephosphorylation of SUPT5H in termination zones downstream of poly(A) sites, thereby promoting deceleration of RNA polymerase II transcription (PubMed:31677974). PNUTS-PP1 complex is also involved in the response to replication stress by mediating dephosphorylation of POLR2A at 'Ser-5' of the CTD, promoting RNA polymerase II degradation (PubMed:33264625). The PNUTS-PP1 complex also plays a role in the control of chromatin structure and cell cycle progression during the transition from mitosis into interphase (By similarity). PNUTS-PP1 complex mediates dephosphorylation of MYC, promoting MYC stability by preventing MYC ubiquitination by the SCF(FBXW7) complex (PubMed:30158517). In addition to acts as a substrate-recognition component, PPP1R10/PNUTS also acts as a nuclear targeting subunit for the PNUTS-PP1 complex (PubMed:9450550). In some context, PPP1R10/PNUTS also acts as an inhibitor of protein phosphatase 1 (PP1) activity by preventing access to substrates, such as RB (PubMed:18360108)","subunit":"Component of the PNUTS-PP1 complex (also named PTW/PP1 complex), composed of PPP1R10/PNUTS, TOX4, WDR82, and PPP1CA (or PPP1CB or PPP1CC)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18360108","30158517","31677974","33264625","39603239","39603240","9450550"],"location":"Nucleus；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；注释原文：Substrate-recognition component of the PNUTS-PP1 protein phosphatase complex, a protein phosphatase 1 (PP1) complex that promotes RNA polymerase II transcription pause-release, allowing transcription elongation (PubMed:39603239, PubMed:39603240).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号"},"PPP1R13B":{"hgnc":"HGNC:14950","symbol":"PPP1R13B","accessions":["Q96KQ4"],"name":"Apoptosis-stimulating of p53 protein 1","length":"1090","function":"Regulator that plays a central role in regulation of apoptosis via its interaction with p53/TP53 (PubMed:11684014, PubMed:12524540). Regulates TP53 by enhancing the DNA binding and transactivation function of TP53 on the promoters of proapoptotic genes in vivo","subunit":"Interacts with P53/TP53; the interaction promotes pro-apoptotic activity","family":"Belongs to the ASPP family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11684014","12524540"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"免疫/炎症/细胞死亡；注释原文：Regulator that plays a central role in regulation of apoptosis via its interaction with p53/TP53 (PubMed:11684014, PubMed:12524540).","function_evidence":"含实验支持条目；ECO:0000269","categories":"免疫/炎症/细胞死亡"},"PPP1R7":{"hgnc":"HGNC:9295","symbol":"PPP1R7","accessions":["Q15435"],"name":"Protein phosphatase 1 regulatory subunit 7","length":"360","function":"Regulatory subunit of protein phosphatase 1","subunit":"Interacts with PPP1CA, PPP1CB and PPP1CC/PPP1G isoform 1","family":"Belongs to the SDS22 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Regulatory subunit of protein phosphatase 1","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"激酶/磷酸化信号"},"PPP1R9B":{"hgnc":"HGNC:9298","symbol":"PPP1R9B","accessions":["Q96SB3"],"name":"Neurabin-2","length":"817","function":"Seems to act as a scaffold protein in multiple signaling pathways. Modulates excitatory synaptic transmission and dendritic spine morphology. Binds to actin filaments (F-actin) and shows cross-linking activity. Binds along the sides of the F-actin. May play an important role in linking the actin cytoskeleton to the plasma membrane at the synaptic junction. Believed to target protein phosphatase 1/PP1 to dendritic spines, which are rich in F-actin, and regulates its specificity toward ion channels and other substrates, such as AMPA-type and NMDA-type glutamate receptors. Plays a role in regulation of G protein-coupled receptor signaling, including dopamine D2 receptors and alpha-adrenergic receptors. May establish a signaling complex for dopaminergic neurotransmission through D2 receptors by linking receptors downstream signaling molecules and the actin cytoskeleton. Binds to ADRA1B and RGS2 and mediates regulation of ADRA1B signaling. May confer to Rac signaling specificity by binding to both, RacGEFs and Rac effector proteins. Probably regulates p70 S6 kinase activity by forming a complex with TIAM1 (By similarity). Required for hepatocyte growth factor (HGF)-induced cell migration","subunit":"Interacts with DCLK2 (By similarity). Possibly exists as a homodimer, homotrimer or a homotetramer. Interacts with F-actin, PPP1CA, neurabin-1, TGN38 and D(2) dopamine receptor. Interacts with RGS1, RGS2, RGS4, RGS19 and ADRA1B, ADRA2A, ADRA2B, ADRA2C, CDKN2A, PPP1R2, RASGFR1 and TIAM1. Interacts (via C-terminus) with SPATA13 (via C-terminal tail). Interacts with ADRA2B","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19151759"],"location":"Cytoplasm, cytoskeleton；Nucleus；Cell projection, dendritic spine；Postsynaptic density；Synapse；Cell junction, adherens junction；Cytoplasm；Cell membrane；Cell projection, lamellipodium；Cell projection, filopodium；Cell projection, ruffle membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面；注释原文：Seems to act as a scaffold protein in multiple signaling pathways.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面"},"PPP2CA":{"hgnc":"HGNC:9299","symbol":"PPP2CA","accessions":["P67775"],"name":"Serine/threonine-protein phosphatase 2A catalytic subunit alpha isoform","length":"309","function":"Catalytic subunit of protein phosphatase 2A (PP2A), a serine/threonine phosphatase involved in the regulation of a wide variety of enzymes, signal transduction pathways, and cellular events (PubMed:10801873, PubMed:12473674, PubMed:17245430, PubMed:22613722, PubMed:33243860, PubMed:34004147, PubMed:9920888, PubMed:41986709). PP2A is the major phosphatase for microtubule-associated proteins (MAPs) (PubMed:22613722). PP2A can modulate the activity of phosphorylase B kinase casein kinase 2, mitogen-stimulated S6 kinase, and MAP-2 kinase (PubMed:22613722). Cooperates with SGO2 to protect centromeric cohesin from separase-mediated cleavage in oocytes specifically during meiosis I (By similarity). Can dephosphorylate various proteins, such as SV40 large T antigen, AXIN1, p53/TP53, PIM3, WEE1 (PubMed:10801873, PubMed:12473674, PubMed:17245430, PubMed:9920888). Activates RAF1 by dephosphorylating it at 'Ser-259' (PubMed:10801873). Mediates dephosphorylation of WEE1, preventing its ubiquitin-mediated proteolysis, increasing WEE1 protein levels, and promoting the G2/M checkpoint (PubMed:33108758). Mediates dephosphorylation of MYC; promoting its ubiquitin-mediated proteolysis: interaction with AMBRA1 enhances interaction between PPP2CA and MYC (PubMed:25438055). Mediates dephosphorylation of FOXO3; promoting its stabilization: interaction with AMBRA1 enhances interaction between PPP2CA and FOXO3 (PubMed:30513302). Catalyzes dephosphorylation of the pyrin domain of NLRP3, promoting assembly of the NLRP3 inflammasome (By similarity). Together with RACK1 adapter, mediates dephosphorylation of AKT1 at 'Ser-473', preventing AKT1 activation and AKT-mTOR signaling pathway (By similarity). Dephosphorylation of AKT1 is essential for regulatory T-cells (Treg) homeostasis and stability (By similarity). Catalyzes dephosphorylation of PIM3, promoting PIM3 ubiquitination and proteasomal degradation (PubMed:12473674). Part of the striatin-interacting phosphatase and kinase (STRIPAK) complexes (PubMed:33633399). STRIPAK complexes have critical roles in protein (de)phosphorylation and are regulators of multiple signaling pathways including Hippo, MAPK, nuclear receptor and cytoskeleton remodeling (PubMed:33633399). Different types of STRIPAK complexes are involved in a variety of biological processes such as cell growth, differentiation, apoptosis, metabolism and immune regulation (PubMed:33633399). Key mediator of a quality checkpoint during transcription elongation as part of the Integrator-PP2A (INTAC) complex (PubMed:33243860, PubMed:34004147, PubMed:37080207). The INTAC complex drives premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation: within the INTAC complex, PPP2CA catalyzes dephosphorylation of the C-terminal domain (CTD) of Pol II subunit POLR2A/RPB1 and SUPT5H/SPT5, thereby preventing transcriptional elongation (PubMed:33243860, PubMed:34004147, PubMed:37080207)","subunit":"PP2A consists of a common heterodimeric core enzyme composed of PPP2CA, a 36 kDa catalytic subunit (subunit C), and PPP2R1A, a 65 kDa constant regulatory subunit (PR65 or subunit A), that associates with a variety of regulatory subunits (PubMed:17055435, PubMed:18394995, PubMed:30595372, PubMed:38123684). Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules (PubMed:18394995, PubMed:30595372, PubMed:38123684). Interacts with the PP2A A subunit PPP2R1A (PubMed:37761890, PubMed:38123684). Interacts with the regulatory subunit PPP2R2A (PubMed:38123684). Interacts (via C-terminus) with PTPA (PubMed:25003389). Interacts with NXN; the interaction is direct (By similarity). Interacts with KCTD20 (By similarity). Interacts with BTBD10 (By similarity). Interacts with SGO1 and SGO2 (PubMed:16541025, PubMed:16580887, PubMed:17485487). Interacts with RAF1 (PubMed:10801873). Interaction with IGBP1 protects unassembled PPP2CA from degradative ubiquitination (PubMed:19818709, PubMed:20092282, PubMed:9647778). Interacts with GSK3B (via C2 domain) (PubMed:20080667). Interacts with MFHAS1; retains PPP2CA into the cytoplasm and excludes it from the nucleus (PubMed:28609714). Interacts with PABIR1/FAM122A (PubMed:27588481, PubMed:38123684). Interacts with ADCY8; interaction is phosphatase activity-dependent; antagonizes interaction between ADCY8 and calmodulin (PubMed:16258073). Interacts with CRTC3 (when phosphorylated at 'Ser-391') (PubMed:30611118). Interacts with SPRY2; the interaction is inhibited by TESK1 interaction with SPRY2, possibly by vesicular sequestration of SPRY2 (PubMed:17974561). Interacts with TRAF3IP3 (PubMed:30115741). Interacts with AMBRA1 (via PxP motifs); enhancing interaction between PPP2CA and MYC or FOXO3 (PubMed:25438055, PubMed:30513302). Forms a complex with AMBRA1 and BECN1; AMBRA1 and BECN1 components of the complex regulate MYC stability via different pathways (PubMed:25803737). Part of the core of STRIPAK complexes composed of PP2A catalytic and scaffolding subunits, the striatins (PP2A regulatory subunits), the striatin-associated proteins MOB4, STRIP1 and STRIP2, PDCD10 and members of the STE20 kinases, such as STK24 and STK26 (PubMed:33633399). Phosphatase component of the Integrator-PP2A (INTAC) complex, composed of the Integrator core complex and protein phosphatase 2A subunits PPP2CA and PPP2R1A (PubMed:33243860, PubMed:34004147, PubMed:37080207, PubMed:34762484, PubMed:36869814, PubMed:38570683). Interacts with FBXO42 and CCDC6 (PubMed:41986709)","family":"Belongs to the PPP phosphatase family. PP-1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10801873","12473674","17245430","22613722","25438055","30513302","33108758","33243860","33633399","34004147","37080207","41986709","9920888"],"location":"Cytoplasm；Nucleus；Chromosome；Chromosome, centromere；Cytoplasm, cytoskeleton, spindle pole","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Catalytic subunit of protein phosphatase 2A (PP2A), a serine/threonine phosphatase involved in the regulation of a wide variety of enzymes, signal transduction pathways, and cellular events (PubMed:10801873, PubMed:12473674, PubMed:17245430, PubMed:22613722, PubMed:33243860, PubMed:34004147, PubMed:9920888, PubMed:41986709).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"PPP2CB":{"hgnc":"HGNC:9300","symbol":"PPP2CB","accessions":["P62714"],"name":"Serine/threonine-protein phosphatase 2A catalytic subunit beta isoform","length":"309","function":"Catalytic subunit of protein phosphatase 2A (PP2A), a serine/threonine phosphatase involved in the regulation of a wide variety of enzymes, signal transduction pathways, and cellular events (Probable). PP2A can modulate the activity of phosphorylase B kinase, casein kinase 2, mitogen-stimulated S6 kinase, and MAP-2 kinase. Part of the striatin-interacting phosphatase and kinase (STRIPAK) complexes. STRIPAK complexes have critical roles in protein (de)phosphorylation and are regulators of multiple signaling pathways including Hippo, MAPK, nuclear receptor and cytoskeleton remodeling. Different types of STRIPAK complexes are involved in a variety of biological processes such as cell growth, differentiation, apoptosis, metabolism and immune regulation (PubMed:18782753)","subunit":"PP2A consists of a common heterodimeric core enzyme (composed of a 36 kDa catalytic subunit (subunit C) and a 65 kDa constant regulatory subunit (PR65) (subunit A)) that associates with a variety of regulatory subunits. Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules. Binds PPME1. May indirectly interact with SGO1, most probably through regulatory B56 subunits. Interacts with CTTNBP2NL. Interacts with PTPA (PubMed:12952889). Found in a complex with at least ARL2, PPP2CB, PPP2R1A, PPP2R2A, PPP2R5E and TBCD. Interacts with TBCD (By similarity). Part of the core of STRIPAK complexes composed of PP2A catalytic and scaffolding subunits, the striatins (PP2A regulatory subunits), the striatin-associated proteins MOB4, STRIP1 and STRIP2, PDCD10 and members of the STE20 kinases, such as STK24 and STK26 (PubMed:18782753)","family":"Belongs to the PPP phosphatase family. PP-1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18782753","2555176"],"location":"Cytoplasm；Nucleus；Chromosome, centromere；Cytoplasm, cytoskeleton, spindle pole","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Catalytic subunit of protein phosphatase 2A (PP2A), a serine/threonine phosphatase involved in the regulation of a wide variety of enzymes, signal transduction pathways, and cellular events (Probable).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000305","categories":"激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"PPP2R1A":{"hgnc":"HGNC:9302","symbol":"PPP2R1A","accessions":["P30153"],"name":"Serine/threonine-protein phosphatase 2A 65 kDa regulatory subunit A alpha isoform","length":"589","function":"The PR65 subunit of protein phosphatase 2A serves as a scaffolding molecule to coordinate the assembly of the catalytic subunit and a variable regulatory B subunit (PubMed:15525651, PubMed:16580887, PubMed:33243860, PubMed:33633399, PubMed:34004147, PubMed:8694763). Upon interaction with GNA12 promotes dephosphorylation of microtubule associated protein TAU/MAPT (PubMed:15525651). Required for proper chromosome segregation and for centromeric localization of SGO1 in mitosis (PubMed:16580887). Together with RACK1 adapter, mediates dephosphorylation of AKT1 at 'Ser-473', preventing AKT1 activation and AKT-mTOR signaling pathway (By similarity). Dephosphorylation of AKT1 is essential for regulatory T-cells (Treg) homeostasis and stability (By similarity). Part of the striatin-interacting phosphatase and kinase (STRIPAK) complexes (PubMed:18782753, PubMed:33633399). STRIPAK complexes have critical roles in protein (de)phosphorylation and are regulators of multiple signaling pathways including Hippo, MAPK, nuclear receptor and cytoskeleton remodeling (PubMed:18782753, PubMed:33633399). Different types of STRIPAK complexes are involved in a variety of biological processes such as cell growth, differentiation, apoptosis, metabolism and immune regulation (PubMed:18782753, PubMed:33633399). Key mediator of a quality checkpoint during transcription elongation as part of the Integrator-PP2A (INTAC) complex (PubMed:33243860, PubMed:34004147). The INTAC complex drives premature transcription termination of transcripts that are unfavorably configured for transcriptional elongation: within the INTAC complex, acts as a scaffolding subunit for PPP2CA, which catalyzes dephosphorylation of the C-terminal domain (CTD) of Pol II subunit POLR2A/RPB1 and SUPT5H/SPT5, thereby preventing transcriptional elongation (PubMed:33243860, PubMed:34004147). Regulates the recruitment of the SKA complex to kinetochores (PubMed:28982702)","subunit":"PP2A consists of a common heterodimeric core enzyme, composed of PPP2CA a 36 kDa catalytic subunit (subunit C) and PPP2R1A a 65 kDa constant regulatory subunit (PR65 or subunit A), that associates with a variety of regulatory subunits (PubMed:38123684). Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules (PubMed:38123684). Found in a complex with at least ARL2, PPP2CB, PPP2R1A, PPP2R2A, PPP2R5E and TBCD (By similarity). Interacts with the PP2A C catalytic subunit PPP2CA (PubMed:37761890, PubMed:38123684). Interacts with the PP2A B subunit PPP2R2A (PubMed:38123684). Interacts with the PP2A B subunit PPP2R5D (PubMed:37761890). Interacts with FOXO1; the interaction dephosphorylates FOXO1 on AKT-mediated phosphorylation sites (By similarity). Interacts with IPO9 (PubMed:12670497). Interacts with TP53 and SGO1 (PubMed:16580887, PubMed:17245430). Interacts with PLA2G16; this interaction might decrease PP2A activity (PubMed:17374643). Interacts with CTTNBP2NL (PubMed:18782753). Interacts with GNA12; the interaction promotes protein phosphatase 2A activation causing dephosphorylation of MAPT (PubMed:15525651). Interacts with CIP2A; this interaction stabilizes CIP2A (PubMed:28174209). Interacts with PABIR1/FAM122A (PubMed:27588481). Interacts with ADCY8; antagonizes interaction between ADCY8 and calmodulin (By similarity). Interacts with CRTC3 (when phosphorylated at 'Ser-391') (PubMed:30611118). Interacts with SPRY2 (PubMed:17974561). Part of the core of STRIPAK complexes composed of PP2A catalytic and scaffolding subunits, the striatins (PP2A regulatory subunits), the striatin-associated proteins MOB4, STRIP1 and STRIP2, PDCD10 and members of the STE20 kinases, such as STK24 and STK26 (PubMed:18782753). Component of the Integrator-PP2A (INTAC) complex, composed of the Integrator core complex and protein phosphatase 2A subunits PPP2CA and PPP2R1A (PubMed:34004147, PubMed:33243860, PubMed:34762484, PubMed:36869814, PubMed:38570683). Interacts with ARPP19 (PubMed:28167675)\n(Microbial infection) Interacts with JC virus small t antigen; this interaction inhibits PPP2R1A activity","family":"Belongs to the phosphatase 2A regulatory subunit A family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15525651","16580887","18782753","28982702","33243860","33633399","34004147","8694763"],"location":"Cytoplasm；Nucleus；Chromosome；Chromosome, centromere；Lateral cell membrane；Cell projection, dendrite","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：The PR65 subunit of protein phosphatase 2A serves as a scaffolding molecule to coordinate the assembly of the catalytic subunit and a variable regulatory B subunit (PubMed:15525651, PubMed:16580887, PubMed:33243860, PubMed:33633399, PubMed:34004147, PubMed:8694763).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"PPP2R1B":{"hgnc":"HGNC:9303","symbol":"PPP2R1B","accessions":["P30154"],"name":"Serine/threonine-protein phosphatase 2A 65 kDa regulatory subunit A beta isoform","length":"601","function":"The PR65 subunit of protein phosphatase 2A serves as a scaffolding molecule to coordinate the assembly of the catalytic subunit and a variable regulatory B subunit","subunit":"PP2A consists of a common heterodimeric core enzyme, composed of a 36 kDa catalytic subunit (subunit C) and a 65 kDa constant regulatory subunit (PR65 or subunit A), that associates with a variety of regulatory subunits. Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules. Interacts with IPO9. Interacts with SGO1. Interacts with RAF1","family":"Belongs to the phosphatase 2A regulatory subunit A family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：The PR65 subunit of protein phosphatase 2A serves as a scaffolding molecule to coordinate the assembly of the catalytic subunit and a variable regulatory B subunit","function_evidence":"数据库整理/推断；按原文限定；","categories":"激酶/磷酸化信号"},"PPP2R2A":{"hgnc":"HGNC:9304","symbol":"PPP2R2A","accessions":["P63151"],"name":"Serine/threonine-protein phosphatase 2A 55 kDa regulatory subunit B alpha isoform","length":"447","function":"Substrate-recognition subunit of protein phosphatase 2A (PP2A) that plays a key role in cell cycle by controlling mitosis entry and exit (PubMed:1849734, PubMed:33108758). Involved in chromosome clustering during late mitosis by mediating dephosphorylation of MKI67 (By similarity). Essential for serine/threonine-protein phosphatase 2A-mediated dephosphorylation of WEE1, preventing its ubiquitin-mediated proteolysis, increasing WEE1 protein levels, and promoting the G2/M checkpoint (PubMed:33108758)","subunit":"PP2A consists of a common heterodimeric core enzyme, composed of a 36 kDa catalytic subunit (subunit C) and a 65 kDa constant regulatory subunit (PR65 or subunit A), that associates with a variety of regulatory subunits (PubMed:38123684). Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules (PubMed:38123684). Interacts with the PP2A C catalytic subunit PPP2CA (PubMed:38123684). Interacts with the PP2A A subunit PPP2R1A (PubMed:38123684). Interacts with TP53 (PubMed:17245430). Interacts with IER5 (PubMed:25816751). Interacts with MFHAS1; the interaction is direct (PubMed:28609714). Interacts with PABIR1/FAM122A (via its N-terminus); the interaction is direct and inhibits PP2A activity (PubMed:27588481, PubMed:33108758, PubMed:38123684). Interacts with ARPP19; the interaction is direct and inhibits PP2A activity (PubMed:27588481, PubMed:33108758, PubMed:38123684). Interacts with CRTC3 (PubMed:30611118)","family":"Belongs to the phosphatase 2A regulatory subunit B family","domains":[],"function_pmids":["1849734","33108758"],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Substrate-recognition subunit of protein phosphatase 2A (PP2A) that plays a key role in cell cycle by controlling mitosis entry and exit (PubMed:1849734, PubMed:33108758). Involved in chromosome clustering during late mitosis by mediating dephosphorylation of MKI67 (By similarity). Essential for serine/threonine-protein phosphatase 2A-mediated dephosphorylation of WEE1, preventing its ubiquitin-mediated proteolysis, increasing WEE1 protein levels, and promoting the G2/M checkpoint (PubMed:33108758)"},"PPP2R3B":{"hgnc":"HGNC:13417","symbol":"PPP2R3B","accessions":["Q9Y5P8"],"name":"Serine/threonine-protein phosphatase 2A regulatory subunit B'' subunit beta","length":"575","function":"The B regulatory subunit might modulate substrate selectivity and catalytic activity, and might also direct the localization of the catalytic enzyme to a particular subcellular compartment","subunit":"PP2A consists of a common heterodimeric core enzyme, composed of a 36 kDa catalytic subunit (subunit C) and a 65 kDa constant regulatory subunit (PR65 or subunit A), that associates with a variety of regulatory subunits. Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules. Interacts with N-terminal region of CDC6. Interacts with NOD2 (PubMed:27812135)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：The B regulatory subunit might modulate substrate selectivity and catalytic activity, and might also direct the localization of the catalytic enzyme to a particular subcellular compartment","function_evidence":"数据库整理/推断；按原文限定；","categories":"激酶/磷酸化信号"},"PPP2R3C":{"hgnc":"HGNC:17485","symbol":"PPP2R3C","accessions":["Q969Q6"],"name":"Serine/threonine-protein phosphatase 2A regulatory subunit B'' subunit gamma","length":"453","function":"May regulate MCM3AP phosphorylation through phosphatase recruitment (By similarity). May act as a negative regulator of ABCB1 expression and function through the dephosphorylation of ABCB1 by TFPI2/PPP2R3C complex (PubMed:24333728). May play a role in the activation-induced cell death of B-cells (By similarity)","subunit":"Interacts with MCM3AP/GANP. Interacts with PPP5C, and the phosphatase 2A core enzyme composed of the PPP2CA catalytic subunit and the constant regulatory subunit PPP2R1A. Finds in a complex with ABCB1, TFPI2 and PPP2R3C; leading to the dephosphorylation of ABCB1","family":"","domains":[],"function_pmids":["24333728"],"location":"Nucleus; Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"May regulate MCM3AP phosphorylation through phosphatase recruitment (By similarity). May act as a negative regulator of ABCB1 expression and function through the dephosphorylation of ABCB1 by TFPI2/PPP2R3C complex (PubMed:24333728). May play a role in the activation-induced cell death of B-cells (By similarity)"},"PPP2R5A":{"hgnc":"HGNC:9309","symbol":"PPP2R5A","accessions":["Q15172"],"name":"Serine/threonine-protein phosphatase 2A 56 kDa regulatory subunit alpha isoform","length":"486","function":"The B regulatory subunit might modulate substrate selectivity and catalytic activity, and might also direct the localization of the catalytic enzyme to a particular subcellular compartment","subunit":"PP2A consists of a common heterodimeric core enzyme, composed of a 36 kDa catalytic subunit (subunit C) and a 65 kDa constant regulatory subunit (PR65 or subunit A), that associates with a variety of regulatory subunits. Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules. Interacts with SGO1","family":"Belongs to the phosphatase 2A regulatory subunit B56 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm；Nucleus；Chromosome, centromere","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：The B regulatory subunit might modulate substrate selectivity and catalytic activity, and might also direct the localization of the catalytic enzyme to a particular subcellular compartment","function_evidence":"数据库整理/推断；按原文限定；","categories":"激酶/磷酸化信号"},"PPP2R5B":{"hgnc":"HGNC:9310","symbol":"PPP2R5B","accessions":["Q15173"],"name":"Serine/threonine-protein phosphatase 2A 56 kDa regulatory subunit beta isoform","length":"497","function":"As the regulatory component of the serine/threonine-protein phosphatase 2A (PP2A) holoenzyme, modulates substrate specificity, subcellular localization, and responsiveness to phosphorylation. The phosphorylated form mediates the interaction between PP2A and AKT1, leading to AKT1 dephosphorylation","subunit":"Component of the serine/threonine-protein phosphatase 2A complex (PP2A). This complex consists of a common heterodimeric core enzyme, composed of a 36 kDa catalytic subunit (subunit C) and a 65 kDa constant scaffold subunit (PR65 or subunit A), that associates with a variety of regulatory subunits. Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules (PubMed:23135275). Interacts with SGO1 (PubMed:16541025). Interacts with AKT1 (PubMed:21329884). Interacts with CUL3 and KLHL15; this interaction leads to proteasomal degradation (PubMed:23135275)","family":"Belongs to the phosphatase 2A regulatory subunit B56 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21329884"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：As the regulatory component of the serine/threonine-protein phosphatase 2A (PP2A) holoenzyme, modulates substrate specificity, subcellular localization, and responsiveness to phosphorylation.","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"PPP2R5D":{"hgnc":"HGNC:9312","symbol":"PPP2R5D","accessions":["Q14738"],"name":"Serine/threonine-protein phosphatase 2A 56 kDa regulatory subunit delta isoform","length":"602","function":"The B regulatory subunit might modulate substrate selectivity and catalytic activity, and might also direct the localization of the catalytic enzyme to a particular subcellular compartment","subunit":"PP2A consists of a common heterodimeric core enzyme, composed of a 36 kDa catalytic subunit (subunit C) and a 65 kDa constant regulatory subunit (PR65 or subunit A), that associates with a variety of regulatory subunits. Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules. Interacts with the PP2A A subunit PPP2R1A (PubMed:37761890). Interacts with SGO1 (PubMed:16541025). Interacts with ADCY8 (PubMed:22976297)","family":"Belongs to the phosphatase 2A regulatory subunit B56 family","domains":[],"function_pmids":[],"location":"Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"The B regulatory subunit might modulate substrate selectivity and catalytic activity, and might also direct the localization of the catalytic enzyme to a particular subcellular compartment"},"PPP2R5E":{"hgnc":"HGNC:9313","symbol":"PPP2R5E","accessions":["Q16537"],"name":"Serine/threonine-protein phosphatase 2A 56 kDa regulatory subunit epsilon isoform","length":"467","function":"The B regulatory subunit might modulate substrate selectivity and catalytic activity, and might also direct the localization of the catalytic enzyme to a particular subcellular compartment","subunit":"Found in a complex with at least ARL2, PPP2CB; PPP2R1A, PPP2R2A, PPP2R5E and TBCD (By similarity). PP2A consists of a common heterodimeric core enzyme, composed of a 36 kDa catalytic subunit (subunit C) and a 65 kDa constant regulatory subunit (PR65 or subunit A), that associates with a variety of regulatory subunits. Proteins that associate with the core dimer include three families of regulatory subunits B (the R2/B/PR55/B55, R3/B''/PR72/PR130/PR59 and R5/B'/B56 families), the 48 kDa variable regulatory subunit, viral proteins, and cell signaling molecules. Interacts with SGO1","family":"Belongs to the phosphatase 2A regulatory subunit B56 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：The B regulatory subunit might modulate substrate selectivity and catalytic activity, and might also direct the localization of the catalytic enzyme to a particular subcellular compartment","function_evidence":"数据库整理/推断；按原文限定；","categories":"激酶/磷酸化信号"},"PPP3CA":{"hgnc":"HGNC:9314","symbol":"PPP3CA","accessions":["Q08209"],"name":"Protein phosphatase 3 catalytic subunit alpha","length":"521","function":"Calcium-dependent, calmodulin-stimulated protein phosphatase which plays an essential role in the transduction of intracellular Ca(2+)-mediated signals (PubMed:15671020, PubMed:18838687, PubMed:19154138, PubMed:23468591, PubMed:30254215). Many of the substrates contain a PxIxIT motif and/or a LxVP motif (PubMed:17498738, PubMed:17502104, PubMed:22343722, PubMed:23468591, PubMed:27974827). In response to increased Ca(2+) levels, dephosphorylates and activates phosphatase SSH1 which results in cofilin dephosphorylation (PubMed:15671020). In response to increased Ca(2+) levels following mitochondrial depolarization, dephosphorylates DNM1L inducing DNM1L translocation to the mitochondrion (PubMed:18838687). Positively regulates the CACNA1B/CAV2.2-mediated Ca(2+) release probability at hippocampal neuronal soma and synaptic terminals (By similarity). Dephosphorylates heat shock protein HSPB1 (By similarity). Dephosphorylates and activates transcription factor NFATC1 (PubMed:19154138). In response to increased Ca(2+) levels, regulates NFAT-mediated transcription probably by dephosphorylating NFAT and promoting its nuclear translocation (PubMed:26248042). Dephosphorylates and inactivates transcription factor ELK1 (PubMed:19154138). Dephosphorylates DARPP32 (PubMed:19154138). May dephosphorylate CRTC2 at 'Ser-171' resulting in CRTC2 dissociation from 14-3-3 proteins (PubMed:30611118). Dephosphorylates transcription factor TFEB at 'Ser-211' following Coxsackievirus B3 infection, promoting nuclear translocation (PubMed:33691586). Required for postnatal development of the nephrogenic zone and superficial glomeruli in the kidneys, cell cycle homeostasis in the nephrogenic zone, and ultimately normal kidney function (By similarity). Plays a role in intracellular AQP2 processing and localization to the apical membrane in the kidney, may thereby be required for efficient kidney filtration (By similarity). Required for secretion of salivary enzymes amylase, peroxidase, lysozyme and sialic acid via formation of secretory vesicles in the submandibular glands (By similarity). Required for calcineurin activity and homosynaptic depotentiation in the hippocampus (By similarity). Required for normal differentiation and survival of keratinocytes and therefore required for epidermis superstructure formation (By similarity). Positively regulates osteoblastic bone formation, via promotion of osteoblast differentiation (By similarity). Positively regulates osteoclast differentiation, potentially via NFATC1 signaling (By similarity). May play a role in skeletal muscle fiber type specification, potentially via NFATC1 signaling (By similarity). Negatively regulates MAP3K14/NIK signaling via inhibition of nuclear translocation of the transcription factors RELA and RELB (By similarity). Required for antigen-specific T-cell proliferation response (By similarity). Dephosphorylates KLHL3, promoting the interaction between KLHL3 and WNK4 and subsequent degradation of WNK4 (PubMed:30718414). Negatively regulates SLC9A1 activity (PubMed:31375679)","subunit":"Forms a complex composed of a calmodulin-dependent catalytic subunit (also known as calcineurin A) and a regulatory Ca(2+)-binding subunit (also known as calcineurin B) (PubMed:12218175, PubMed:12357034, PubMed:17498738, PubMed:22343722, PubMed:23468591, PubMed:27974827, PubMed:8524402). There are three catalytic subunits, each encoded by a separate gene (PPP3CA, PPP3CB, and PPP3CC) and two regulatory subunits which are also encoded by separate genes (PPP3R1 and PPP3R2). In response to an increase in Ca(2+) intracellular levels, forms a complex composed of PPP3CA/calcineurin A, calcineurin B and calmodulin (By similarity). Interacts (via calcineurin B binding domain) with regulatory subunit PPP3R1/calcineurin B (PubMed:12218175, PubMed:12357034, PubMed:17498738, PubMed:22343722, PubMed:23468591, PubMed:27974827, PubMed:8524402). Interacts (via calmodulin-binding domain) with CALM1/calmodulin; the interaction depends on calmodulin binding to Ca(2+) (PubMed:18384083, PubMed:19404396, PubMed:25144868, Ref.35). Forms a complex composed of MYOZ2 and ACTN1 (By similarity). Within the complex interacts with MYOZ2 (PubMed:11114196). Interacts with MYOZ1 (PubMed:11114196). Interacts with MYOZ3 (PubMed:11842093). Interacts with CIB1; the interaction increases upon cardiomyocyte hypertrophy (By similarity). Interacts with CHP1 and CHP2 (By similarity). Interacts with CRTC1 (PubMed:30611118). Interacts with CRTC2 (PubMed:15454081, PubMed:30611118). Interacts with DNM1L; the interaction dephosphorylates DNM1L and promotes its translocation to mitochondria (PubMed:18838687). Interacts with CMYA5; this interaction represses calcineurin activity in muscle (By similarity). Interacts (constitutively active form) with SYNPO2 (PubMed:17923693). Interacts with scaffold protein AKAP5 (via IAIIIT motif); the interaction recruits PPP3CA to the plasma membrane following L-type Ca(2+)-channel activation (PubMed:22343722). Interacts with NFATC2 (PubMed:26248042). Interacts with RCAN3 (PubMed:26248042). Interacts with PPIA (PubMed:12218175, PubMed:12357034). Interacts with RCAN1 (PubMed:12809556). Interacts with UNC119 (By similarity). Interacts with CLMB (via PxIxIT motif, when phosphorylated on 'Thr-44'); leading to enhanced recruitment of PPP3CA to the plasma membrane and modulation of calcineurin signaling (PubMed:28881575, PubMed:41224739). Interacts (via N-terminus) with MAP3K14/NIK (via C-terminus and kinase domain) (By similarity). Interacts with TRAF3 (By similarity). Interacts with SPATA33 (via PQIIIT motif) (PubMed:34446558)","family":"Belongs to the PPP phosphatase family. PP-2B subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15671020","17498738","17502104","18838687","19154138","22343722","23468591","26248042","27974827","30254215","30611118","30718414","31375679","33691586"],"location":"Cytoplasm；Cell membrane；Peripheral membrane protein；Cell membrane, sarcolemma；Cytoplasm, myofibril, sarcomere, Z line；Cell projection, dendritic spine","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；线粒体/代谢；黏附/受体/细胞表面；发育/分化；注释原文：Calcium-dependent, calmodulin-stimulated protein phosphatase which plays an essential role in the transduction of intracellular Ca(2+)-mediated signals (PubMed:15671020, PubMed:18838687, PubMed:19154138, PubMed:23468591, PubMed:30254215).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；线粒体/代谢；黏附/受体/细胞表面；发育/分化"},"PPP3CB":{"hgnc":"HGNC:9315","symbol":"PPP3CB","accessions":["P16298"],"name":"Serine/threonine-protein phosphatase 2B catalytic subunit beta isoform","length":"524","function":"Calcium-dependent, calmodulin-stimulated protein phosphatase which plays an essential role in the transduction of intracellular Ca(2+)-mediated signals (PubMed:19154138, PubMed:25720963, PubMed:26794871, PubMed:32753672). Dephosphorylates TFEB in response to lysosomal Ca(2+) release, resulting in TFEB nuclear translocation and stimulation of lysosomal biogenesis (PubMed:25720963, PubMed:32753672). Dephosphorylates and activates transcription factor NFATC1 (PubMed:19154138). Dephosphorylates and inactivates transcription factor ELK1 (PubMed:19154138). Dephosphorylates DARPP32 (PubMed:19154138). Negatively regulates MAP3K14/NIK signaling via inhibition of nuclear translocation of the transcription factors RELA and RELB (By similarity). May play a role in skeletal muscle fiber type specification (By similarity)","subunit":"Forms a complex composed of a calmodulin-dependent catalytic subunit (also known as calcineurin A) and a regulatory Ca(2+)-binding subunit (also known as calcineurin B) (PubMed:26794871). There are three catalytic subunits, each encoded by a separate gene (PPP3CA, PPP3CB, and PPP3CC) and two regulatory subunits which are also encoded by separate genes (PPP3R1 and PPP3R2) (PubMed:26794871). In response to an increase in Ca(2+) intracellular levels, forms a complex composed of PPP3CB/calcineurin A, calcineurin B and calmodulin (PubMed:26794871). Interacts (via calcineurin B binding domain) with regulatory subunit PPP3R1/calcineurin B (PubMed:26794871). Interacts (via calmodulin-binding domain) with calmodulin; the interaction depends on calmodulin binding to Ca(2+) (PubMed:26794871). Interacts with SLC12A1 (By similarity). Interacts with SORL1 (By similarity). Interacts with UNC119 (By similarity). Interacts with MAP3K14/NIK (via C-terminus and kinase domain) (By similarity). Interacts with TRAF3 (By similarity). Interacts with SPATA33 (via PQIIIT motif) (PubMed:34446558). Interacts with IRGM; promoting its association with TFEB and TFEB dephosphorylation (PubMed:32753672)","family":"Belongs to the PPP phosphatase family. PP-2B subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19154138","25720963","26794871","32753672"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；注释原文：Calcium-dependent, calmodulin-stimulated protein phosphatase which plays an essential role in the transduction of intracellular Ca(2+)-mediated signals (PubMed:19154138, PubMed:25720963, PubMed:26794871, PubMed:32753672).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号"},"PPP3CC":{"hgnc":"HGNC:9316","symbol":"PPP3CC","accessions":["P48454"],"name":"Serine/threonine-protein phosphatase 2B catalytic subunit gamma isoform","length":"512","function":"Calcium-dependent, calmodulin-stimulated protein phosphatase which plays an essential role in the transduction of intracellular Ca(2+)-mediated signals. Dephosphorylates and activates transcription factor NFATC1. Dephosphorylates and inactivates transcription factor ELK1. Dephosphorylates DARPP32","subunit":"Forms a complex composed of a calmodulin-dependent catalytic subunit (also known as calcineurin A) and a regulatory Ca(2+)-binding subunit (also known as calcineurin B) (PubMed:19154138). There are three catalytic subunits, each encoded by a separate gene (PPP3CA, PPP3CB, and PPP3CC) and two regulatory subunits which are also encoded by separate genes (PPP3R1 and PPP3R2). In response to an increase in Ca(2+) intracellular levels, forms a complex composed of PPP3CC/calcineurin A, calcineurin B and calmodulin (By similarity). Interacts (via calmodulin-binding domain) with calmodulin; the interaction depends on calmodulin binding to Ca(2+) (By similarity). Interacts with UNC119 (By similarity). Interacts with SPATA33 (via PQIIIT motif) (PubMed:34446558). Interacts with VDAC2 in a SPATA33-dependent manner (By similarity)","family":"Belongs to the PPP phosphatase family. PP-2B subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["19154138"],"location":"Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；注释原文：Calcium-dependent, calmodulin-stimulated protein phosphatase which plays an essential role in the transduction of intracellular Ca(2+)-mediated signals.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号"},"PPP3R1":{"hgnc":"HGNC:9317","symbol":"PPP3R1","accessions":["P63098"],"name":"Calcineurin subunit B type 1","length":"170","function":"Regulatory subunit of calcineurin, a calcium-dependent, calmodulin stimulated protein phosphatase. Confers calcium sensitivity","subunit":"Forms a complex composed of a calmodulin-dependent catalytic subunit (also known as calcineurin A) and a regulatory Ca(2+)-binding subunit (also known as calcineurin B) (PubMed:12218175, PubMed:12357034, PubMed:17498738, PubMed:22343722, PubMed:23468591, PubMed:26794871, PubMed:27974827, PubMed:8524402). There are three catalytic subunits, each encoded by a separate gene (PPP3CA, PPP3CB, and PPP3CC) and two regulatory subunits which are also encoded by separate genes (PPP3R1 and PPP3R2). Interacts with catalytic subunit PPP3CA/calcineurin A (PubMed:12218175, PubMed:12357034, PubMed:17498738, PubMed:22343722, PubMed:23468591, PubMed:27974827, PubMed:31375679, PubMed:8524402). Interacts with catalytic subunit PPP3CB/calcineurin A (PubMed:26794871). Interacts with CIB1 (via C-terminal region); the interaction increases upon cardiomyocyte hypertrophy (By similarity). Interacts with RCAN1 (PubMed:12809556). Interacts with SPATA33 (via PQIIIT motif) (PubMed:34446558)","family":"Belongs to the calcineurin regulatory subunit family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["26794871"],"location":"Cytoplasm, cytosol；Cell membrane；Cell membrane, sarcolemma；Lipid-anchor","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Regulatory subunit of calcineurin, a calcium-dependent, calmodulin stimulated protein phosphatase.","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"PPP4C":{"hgnc":"HGNC:9319","symbol":"PPP4C","accessions":["P60510"],"name":"Serine/threonine-protein phosphatase 4 catalytic subunit","length":"307","function":"Protein phosphatase that is involved in many processes such as microtubule organization at centrosomes, maturation of spliceosomal snRNPs, apoptosis, DNA repair, tumor necrosis factor (TNF)-alpha signaling, activation of c-Jun N-terminal kinase MAPK8, regulation of histone acetylation, DNA damage checkpoint signaling, NF-kappa-B activation and cell migration. The PPP4C-PPP4R1 PP4 complex may play a role in dephosphorylation and regulation of HDAC3. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on Ser-140 (gamma-H2AX) generated during DNA replication and required for DNA double strand break repair. Dephosphorylates NDEL1 at CDK1 phosphorylation sites and negatively regulates CDK1 activity in interphase (By similarity). In response to DNA damage, catalyzes RPA2 dephosphorylation, an essential step for DNA repair since it allows the efficient RPA2-mediated recruitment of RAD51 to chromatin","subunit":"Serine/threonine-protein phosphatase 4 (PP4) occurs in different assemblies of the catalytic and one or more regulatory subunits (PubMed:12668731, PubMed:16085932, PubMed:18614045, PubMed:18715871). Component of the PP4 complexes PPP4C-PPP4R1, PPP4C-PPP4R2, PPP4C-PPP4R2-PPP4R3A, PPP4C-PPP4R2-PPP4R3B and PPP4C-PPP4R4 (PubMed:12668731, PubMed:16085932, PubMed:18614045, PubMed:18715871). The PPP4C-PPP4R2 complex appears to be a tetramer composed of 2 molecules of PPP4C and 2 molecules of PPP4R2 (PubMed:12668731). Interacts with REL, NFKB1/p50 and RELA (PubMed:1336397). Interacts with SMN1 and GEMIN4 (PubMed:12668731). Interacts with IRS4 (phosphorylated) (PubMed:15331607). Interacts with SMEK1/PPP4R3A; the interaction requires PP4R2 (PubMed:16085932). Interacts with HDAC3 (PubMed:15805470). Interacts with FBXO42 (PubMed:41484364)","family":"Belongs to the PPP phosphatase family. PP-4 (PP-X) subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11698396","12668731","12934076","1336397","15805470","18347064","18487071","18614045","18758438","20154705"],"location":"Cytoplasm；Nucleus；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"PP4催化亚基；磷酸化状态/损伤应答等情境调节。","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡"},"PPP4R2":{"hgnc":"HGNC:18296","symbol":"PPP4R2","accessions":["Q9NY27"],"name":"Serine/threonine-protein phosphatase 4 regulatory subunit 2","length":"417","function":"Regulatory subunit of serine/threonine-protein phosphatase 4 (PP4). May regulate the activity of PPP4C at centrosomal microtubule organizing centers. Its interaction with the SMN complex leads to enhance the temporal localization of snRNPs, suggesting a role of PPP4C in maturation of spliceosomal snRNPs. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on 'Ser-140' (gamma-H2AX) generated during DNA replication and required for DNA double strand break repair. Mediates RPA2 dephosphorylation by recruiting PPP4C to RPA2 in a DNA damage-dependent manner. RPA2 dephosphorylation is required for the efficient RPA2-mediated recruitment of RAD51 to chromatin following double strand breaks, an essential step for DNA repair","subunit":"Serine/threonine-protein phosphatase 4 (PP4) occurs in different assemblies of the catalytic and one or more regulatory subunits. Component of the PP4 complexes PPP4C-PPP4R2, PPP4C-PPP4R2-PPP4R3A and PPP4C-PPP4R2-PPP4R3B. The PPP4C-PPP4R2 complex appears to be a tetramer composed of 2 molecules of PPP4C and 2 molecules of PPP4R2. Interacts with DDX20/GEMIN3 and GEMIN4. Interacts with RPA2; this DNA damage-dependent interaction recruits PPP4C leading to RPA2 dephosphorylation. Interacts with FBXO42 (PubMed:41484364)","family":"Belongs to the PPP4R2 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10769191","12668731","18614045","20154705"],"location":"Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；细胞骨架/纤毛；注释原文：Regulatory subunit of serine/threonine-protein phosphatase 4 (PP4).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；细胞骨架/纤毛"},"PPP4R3A":{"hgnc":"HGNC:20219","symbol":"PPP4R3A","accessions":["Q6IN85"],"name":"Serine/threonine-protein phosphatase 4 regulatory subunit 3A","length":"833","function":"Regulatory subunit of serine/threonine-protein phosphatase 4. May regulate the activity of PPP4C at centrosomal microtubule organizing centers. The PPP4C-PPP4R2-PPP4R3A PP4 complex specifically dephosphorylates H2AX phosphorylated on 'Ser-140' (gamma-H2AX) generated during DNA replication and required for DNA DSB repair","subunit":"Serine/threonine-protein phosphatase 4 (PP4) occurs in different assemblies of the catalytic and one or more regulatory subunits. Component of the PP4 complex PPP4C-PPP4R2-PPP4R3A. Interacts with PPP4C; the interaction requires PPP4R2. Interacts with FBXO42 (PubMed:41484364)","family":"Belongs to the SMEK family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["18614045"],"location":"Cytoplasm；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；激酶/磷酸化信号；细胞骨架/纤毛；注释原文：Regulatory subunit of serine/threonine-protein phosphatase 4.","function_evidence":"含实验支持条目；ECO:0000269","categories":"DNA修复/复制；激酶/磷酸化信号；细胞骨架/纤毛"},"PPP4R3B":{"hgnc":"HGNC:29267","symbol":"PPP4R3B","accessions":["Q5MIZ7"],"name":"Serine/threonine-protein phosphatase 4 regulatory subunit 3B","length":"849","function":"Regulatory subunit of serine/threonine-protein phosphatase 4 (PP4). May regulate the activity of PPP4C at centrosomal microtubule organizing centers","subunit":"Serine/threonine-protein phosphatase 4 (PP4) occurs in different assemblies of the catalytic and one or more regulatory subunits. Component of the PP4 complex PPP4C-PPP4R2-PPP4R3B. Interacts with FBXO42 (PubMed:41484364)","family":"Belongs to the SMEK family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Cytoplasm；Cytoplasm, cytoskeleton, microtubule organizing center, centrosome；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；细胞骨架/纤毛；注释原文：Regulatory subunit of serine/threonine-protein phosphatase 4 (PP4).","function_evidence":"数据库整理/推断；按原文限定；","categories":"激酶/磷酸化信号；细胞骨架/纤毛"},"PPP4R3C":{"hgnc":"HGNC:33146","symbol":"PPP4R3C","accessions":["Q6ZMV5"],"name":"Protein PPP4R3C","length":"832","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the SMEK family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"PPP6R1":{"hgnc":"HGNC:29195","symbol":"PPP6R1","accessions":["Q9UPN7"],"name":"Serine/threonine-protein phosphatase 6 regulatory subunit 1","length":"881","function":"Regulatory subunit of protein phosphatase 6 (PP6). May function as a scaffolding PP6 subunit. Involved in the PP6-mediated dephosphorylation of NFKBIE opposing its degradation in response to TNF","subunit":"Protein phosphatase 6 (PP6) holoenzyme is proposed to be a heterotrimeric complex formed of the catalytic subunit, a SAPS domain-containing subunit (PP6R) and an ankyrin repeat-domain containing regulatory subunit (ARS). Interacts with PPP6C and NFKBIE. Interacts with ANKRD28, ANKRD44 and ANKRD52","family":"Belongs to the SAPS family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16769727"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Regulatory subunit of protein phosphatase 6 (PP6).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"},"PPP6R2":{"hgnc":"HGNC:19253","symbol":"PPP6R2","accessions":["O75170"],"name":"Serine/threonine-protein phosphatase 6 regulatory subunit 2","length":"966","function":"Regulatory subunit of protein phosphatase 6 (PP6). May function as a scaffolding PP6 subunit. Involved in the PP6-mediated dephosphorylation of NFKBIE opposing its degradation in response to TNF","subunit":"Protein phosphatase 6 (PP6) holoenzyme is proposed to be a heterotrimeric complex formed by the catalytic subunit, a SAPS domain-containing subunit (PP6R) and an ankyrin repeat-domain containing regulatory subunit (ARS). Interacts with PPP6C and NFKBIE. Interacts with ANKRD28","family":"Belongs to the SAPS family","domains":[],"function_pmids":["16769727"],"location":"Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Regulatory subunit of protein phosphatase 6 (PP6). May function as a scaffolding PP6 subunit. Involved in the PP6-mediated dephosphorylation of NFKBIE opposing its degradation in response to TNF"},"PPP6R3":{"hgnc":"HGNC:1173","symbol":"PPP6R3","accessions":["Q5H9R7"],"name":"Serine/threonine-protein phosphatase 6 regulatory subunit 3","length":"873","function":"Regulatory subunit of protein phosphatase 6 (PP6). May function as a scaffolding PP6 subunit. May have an important role in maintaining immune self-tolerance","subunit":"Protein phosphatase 6 (PP6) holoenzyme is proposed to be a heterotrimeric complex formed by the catalytic subunit, a SAPS domain-containing subunit (PP6R) and an ankyrin repeat-domain containing regulatory subunit (ARS). Interacts with PPP6C and ANKRD28","family":"Belongs to the SAPS family","domains":[],"function_pmids":["11401438","16769727"],"location":"Cytoplasm; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Regulatory subunit of protein phosphatase 6 (PP6). May function as a scaffolding PP6 subunit. May have an important role in maintaining immune self-tolerance"},"PQBP1":{"hgnc":"HGNC:9330","symbol":"PQBP1","accessions":["O60828"],"name":"Polyglutamine-binding protein 1","length":"265","function":"Intrinsically disordered protein that acts as a scaffold, and which is involved in different processes, such as pre-mRNA splicing, transcription regulation, innate immunity and neuron development (PubMed:10198427, PubMed:10332029, PubMed:12062018, PubMed:20410308, PubMed:23512658). Interacts with splicing-related factors via the intrinsically disordered region and regulates alternative splicing of target pre-mRNA species (PubMed:10332029, PubMed:12062018, PubMed:20410308, PubMed:23512658). May suppress the ability of POU3F2 to transactivate the DRD1 gene in a POU3F2 dependent manner. Can activate transcription directly or via association with the transcription machinery (PubMed:10198427). May be involved in ATXN1 mutant-induced cell death (PubMed:12062018). The interaction with ATXN1 mutant reduces levels of phosphorylated RNA polymerase II large subunit (PubMed:12062018). Involved in the assembly of cytoplasmic stress granule, possibly by participating in the transport of neuronal RNA granules (PubMed:21933836). Also acts as an innate immune sensor of infection by retroviruses, such as HIV, by detecting the presence of reverse-transcribed DNA in the cytosol (PubMed:26046437). Directly binds retroviral reverse-transcribed DNA in the cytosol and interacts with CGAS, leading to activate the cGAS-STING signaling pathway, triggering type-I interferon production (PubMed:26046437)","subunit":"Interacts with POU3F2/Brn-2, ATXN1, TXNL4A, HTT and AR (PubMed:10332029, PubMed:10873650, PubMed:19303059, PubMed:24781215). Interaction with ATXN1 correlates positively with the length of the polyglutamine tract (PubMed:12062018). Interacts with RNA polymerase II large subunit in a phosphorylation-dependent manner (PubMed:12062018). Forms a ternary complex with ATXN1 mutant and phosphorylated RNA polymerase II (PubMed:12062018). Interacts (via C-terminus) with TXNL4A and CD2BP2 (PubMed:10873650, PubMed:19303059, PubMed:24781215). Interacts (via WW domain) with ATN1 and SF3B1, and may interact with additional splice factors (PubMed:20410308, PubMed:23512658). Interacts (via WW domain) with WBP11; Leading to reduce interaction between PQBP1 and TXNL4A (PubMed:20410308, PubMed:23512658, PubMed:27314904). Interacts with CAPRIN1 (PubMed:21933836). Interacts with DDX1 (PubMed:21933836). Interacts with SFPQ (PubMed:21933836). Interacts with KHSRP (PubMed:21933836)","family":"","domains":[],"function_pmids":["10198427","10332029","12062018","20410308","21933836","23512658","26046437"],"location":"Nucleus; Nucleus speckle; Cytoplasmic granule","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Intrinsically disordered protein that acts as a scaffold, and which is involved in different processes, such as pre-mRNA splicing, transcription regulation, innate immunity and neuron development (PubMed:10198427, PubMed:10332029, PubMed:12062018, PubMed:20410308, PubMed:23512658). Interacts with splicing-related factors via the intrinsically disordered region and regulates alternative splicing of target pre-mRNA species (PubMed:10332029, PubMed:12062018, PubMed:20410308, PubMed:23512658). May suppress the ability of POU3F2 to transactivate the DRD1 gene in a POU3F2 dependent manner. Can activate transcription directly or via association with the transcription machinery (PubMed:10198427). May be involved in ATXN1 mutant-induced cell death (PubMed:12062018). The interaction with ATXN1 mutant reduces levels of phosphorylated RNA polymerase II large subunit (PubMed:12062018). Involved in the assembly of cytoplasmic stress granule, possibly by participating in the transport of neuronal RNA granules (PubMed:21933836). Also acts as an innate immune sensor of infection by retroviruses, such as HIV, by detecting the presence of reverse-transcribed DNA in the cytosol (PubMed:26046437). Directly binds retroviral reverse-transcribed DNA in the cytosol and interacts with CGAS, leading to activate the cGAS-STING signaling pathway, triggering type-I interferon production (PubMed:26046437)"},"PRAC2":{"hgnc":"HGNC:30143","symbol":"PRAC2","accessions":["D3DTV9"],"name":"Protein PRAC2","length":"90","function":"","subunit":"","family":"","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":""},"PRAME":{"hgnc":"HGNC:9336","symbol":"PRAME","accessions":["P78395"],"name":"Melanoma antigen preferentially expressed in tumors","length":"509","function":"Substrate-recognition component of a Cul2-RING (CRL2) E3 ubiquitin-protein ligase complex, which mediates ubiquitination of target proteins, leading to their degradation (PubMed:21822215, PubMed:26138980). The CRL2(PRAME) complex mediates ubiquitination and degradation of truncated MSRB1/SEPX1 selenoproteins produced by failed UGA/Sec decoding (PubMed:26138980). In the nucleus, the CRL2(PRAME) complex is recruited to epigenetically and transcriptionally active promoter regions bound by nuclear transcription factor Y (NFY) and probably plays a role in chromstin regulation (PubMed:21822215). Functions as a transcriptional repressor, inhibiting the signaling of retinoic acid through the retinoic acid receptors RARA, RARB and RARG: prevents retinoic acid-induced cell proliferation arrest, differentiation and apoptosis (PubMed:16179254)","subunit":"Component of a CRL2 E3 ubiquitin-protein ligase complex, also named ECS (Elongin BC-CUL2/5-SOCS-box protein) complex, composed of CUL2, Elongin BC (ELOB and ELOC), RBX1 and substrate-specific adapter PRAME (PubMed:21822215, PubMed:23460923, PubMed:26138980). Interacts with RARA (via the ligand-binding domain); the interaction is direct and ligand (retinoic acid)-dependent (PubMed:16179254). Interacts with EZH2; required to repress RAR signaling (PubMed:16179254)","family":"Belongs to the PRAME family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["16179254","21822215","26138980"],"location":"Nucleus；Chromosome；Cytoplasm；Golgi apparatus；Cell membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化；注释原文：Substrate-recognition component of a Cul2-RING (CRL2) E3 ubiquitin-protein ligase complex, which mediates ubiquitination of target proteins, leading to their degradation (PubMed:21822215, PubMed:26138980).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化"},"PRAMEF12":{"hgnc":"HGNC:22125","symbol":"PRAMEF12","accessions":["O95522"],"name":"PRAME family member 12","length":"483","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the PRAME family","domains":"Repeat 97-122: LRR 1; degenerate [ECO:0000250/UniProtKB/Q3UWY1]\nRepeat 177-201: LRR 2; degenerate [ECO:0000250/UniProtKB/Q3UWY1]\nRepeat 202-228: LRR 3; degenerate [ECO:0000250/UniProtKB/Q3UWY1]\nRepeat 229-264: LRR 4; degenerate [ECO:0000250/UniProtKB/Q3UWY1]\nRepeat 265-290: LRR 5 [ECO:0000250/UniProtKB/Q3UWY1]\nRepeat 291-322: LRR 6 [ECO:0000250/UniProtKB/Q3UWY1]\nRepeat 323-341: LRR 7 [ECO:0000250/UniProtKB/Q3UWY1]\nRepeat 347-374: LRR 8 [ECO:0000250/UniProtKB/Q3UWY1]\nRepeat 375-399: LRR 9 [ECO:0000250/UniProtKB/Q3UWY1]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"PRC1":{"hgnc":"HGNC:9341","symbol":"PRC1","accessions":["O43663"],"name":"Protein regulator of cytokinesis 1","length":"620","function":"Key regulator of cytokinesis that cross-links antiparrallel microtubules at an average distance of 35 nM. Essential for controlling the spatiotemporal formation of the midzone and successful cytokinesis. Required for KIF14 localization to the central spindle and midbody. Required to recruit PLK1 to the spindle. Stimulates PLK1 phosphorylation of RACGAP1 to allow recruitment of ECT2 to the central spindle. Acts as an oncogene for promoting bladder cancer cells proliferation, apoptosis inhibition and carcinogenic progression (PubMed:17409436)","subunit":"Homodimer (PubMed:20691902). Interacts with the C-terminal Rho-GAP domain and the basic region of RACGAP1 (PubMed:14744859). The interaction with RACGAP1 inhibits its GAP activity towards CDC42 in vitro, which may be required for maintaining normal spindle morphology (PubMed:14744859). Interacts (via N-terminus) with the C-terminus of CENPE (via C-terminus); the interaction occurs during late mitosis (PubMed:15297875). Interacts (via N-terminus) with KIF4A (via C-terminus); the interaction is required for the progression of mitosis (PubMed:15297875, PubMed:16431929, PubMed:29848660). Interacts (via N-terminus) with KIF23 (via C-terminus); the interaction occurs during late mitosis (PubMed:15297875). Interacts with KIF14 and KIF20A (PubMed:15625105, PubMed:16431929). Interacts with PLK1 (PubMed:19468300). Interacts with KIF20B (PubMed:17409436). Interacts with CCDC66 (PubMed:35849559)","family":"Belongs to the MAP65/ASE1 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12082078","15297875","15625105","16431929","17409436","19468300","20691902","9885575"],"location":"Nucleus；Cytoplasm；Cytoplasm, cytoskeleton, spindle pole；Midbody；Chromosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；注释原文：Key regulator of cytokinesis that cross-links antiparrallel microtubules at an average distance of 35 nM.","function_evidence":"含实验支持条目；ECO:0000269","categories":"细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡"},"PRDM11":{"hgnc":"HGNC:13996","symbol":"PRDM11","accessions":["Q9NQV5"],"name":"PR domain-containing protein 11","length":"511","function":"May be involved in transcription regulation","subunit":"无可用SUBUNIT段","family":"Belongs to the class V-like SAM-binding methyltransferase superfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["25499759"],"location":"Nucleus；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；注释原文：May be involved in transcription regulation","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控"},"PRDM14":{"hgnc":"HGNC:14001","symbol":"PRDM14","accessions":["Q9GZV8"],"name":"PR domain zinc finger protein 14","length":"571","function":"Transcription factor that has both positive and negative roles on transcription. Required for the maintenance of embryonic stem cell identity and the reacquisition of pluripotency in somatic cells. May play an essential role in germ cell development at 2 levels: the reacquisition of potential pluripotency, including SOX2 up-regulation, and successful epigenetic reprogramming, characterized by EHMT1 repression. Its association with CBFA2T2 is required for the functions in pluripotency and germ cell formation (By similarity). Directly up-regulates the expression of pluripotency gene POU5F1 through its proximal enhancer. Binds to the DNA consensus sequence 5'-GGTC[TC]CTAA-3'","subunit":"Interacts with CBFA2T2","family":"Belongs to the class V-like SAM-binding methyltransferase superfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17942894","20953172"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Transcription factor that has both positive and negative roles on transcription.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；发育/分化"},"PRDM15":{"hgnc":"HGNC:13999","symbol":"PRDM15","accessions":["P57071"],"name":"PR domain zinc finger protein 15","length":"1141","function":"Sequence-specific DNA-binding transcriptional regulator. Plays a role as a molecular node in a transcriptional network regulating embryonic development and cell fate decision. Stimulates the expression of upstream key transcriptional activators and repressors of the Wnt/beta-catenin and MAPK/ERK pathways, respectively, that are essential for naive pluripotency and self-renewal maintenance of embryonic stem cells (ESCs). Specifically promotes SPRY1 and RSPO1 transcription activation through recognition and direct binding of a specific DNA sequence in their promoter regions. Involved in early embryo development (By similarity). Also plays a role in induced pluripotent stem cells (iPSCs) reprogramming (PubMed:28740264)","subunit":"Interacts with Zincore complex components QRICH1 and SEPHS1; probably stabilizing PRDM15 at DNA-binding sites across the genome","family":"Belongs to the class V-like SAM-binding methyltransferase superfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["28740264"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；发育/分化；注释原文：Sequence-specific DNA-binding transcriptional regulator.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；发育/分化"},"PRDM5":{"hgnc":"HGNC:9349","symbol":"PRDM5","accessions":["Q9NQX1"],"name":"PR domain zinc finger protein 5","length":"630","function":"Sequence-specific DNA-binding transcription factor. Represses transcription at least in part by recruitment of the histone methyltransferase EHMT2/G9A and histone deacetylases such as HDAC1. Regulates hematopoiesis-associated protein-coding and microRNA (miRNA) genes. May regulate the expression of proteins involved in extracellular matrix development and maintenance, including fibrillar collagens, such as COL4A1 and COL11A1, connective tissue components, such as HAPLN1, and molecules regulating cell migration and adhesion, including EDIL3 and TGFB2. May cause G2/M arrest and apoptosis in cancer cells","subunit":"Interacts with EHMT2/G9A, GFI1 and HDAC1","family":"Belongs to the class V-like SAM-binding methyltransferase superfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15077163","17636019","21664999"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化；注释原文：Sequence-specific DNA-binding transcription factor.","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面；发育/分化"},"PRDM6":{"hgnc":"HGNC:9350","symbol":"PRDM6","accessions":["Q9NQX0"],"name":"Putative histone-lysine N-methyltransferase PRDM6","length":"595","function":"Putative histone methyltransferase that acts as a transcriptional repressor of smooth muscle gene expression. Promotes the transition from differentiated to proliferative smooth muscle by suppressing differentiation and maintaining the proliferative potential of vascular smooth muscle cells. Also plays a role in endothelial cells by inhibiting endothelial cell proliferation, survival and differentiation. It is unclear whether it has histone methyltransferase activity in vivo. According to some authors, it does not act as a histone methyltransferase by itself and represses transcription by recruiting EHMT2/G9a. According to others, it possesses histone methyltransferase activity when associated with other proteins and specifically methylates 'Lys-20' of histone H4 in vitro. 'Lys-20' methylation represents a specific tag for epigenetic transcriptional repression","subunit":"Interacts with HDAC1, HDAC2, HDAC3, CBX1 and EP300","family":"Belongs to the class V-like SAM-binding methyltransferase superfamily","domains":[],"function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Putative histone methyltransferase that acts as a transcriptional repressor of smooth muscle gene expression. Promotes the transition from differentiated to proliferative smooth muscle by suppressing differentiation and maintaining the proliferative potential of vascular smooth muscle cells. Also plays a role in endothelial cells by inhibiting endothelial cell proliferation, survival and differentiation. It is unclear whether it has histone methyltransferase activity in vivo. According to some authors, it does not act as a histone methyltransferase by itself and represses transcription by recruiting EHMT2/G9a. According to others, it possesses histone methyltransferase activity when associated with other proteins and specifically methylates 'Lys-20' of histone H4 in vitro. 'Lys-20' methylation represents a specific tag for epigenetic transcriptional repression"},"PRDX1":{"hgnc":"HGNC:9352","symbol":"PRDX1","accessions":["Q06830"],"name":"Peroxiredoxin-1","length":"199","function":"Thiol-specific peroxidase that catalyzes the reduction of hydrogen peroxide and organic hydroperoxides to water and alcohols, respectively. Plays a role in cell protection against oxidative stress by detoxifying peroxides and as sensor of hydrogen peroxide-mediated signaling events. Might participate in the signaling cascades of growth factors and tumor necrosis factor-alpha by regulating the intracellular concentrations of H(2)O(2) (PubMed:9497357). Reduces an intramolecular disulfide bond in GDPD5 that gates the ability to GDPD5 to drive postmitotic motor neuron differentiation (By similarity)","subunit":"Homodimer; disulfide-linked, upon oxidation. 5 homodimers assemble to form a ring-like decamer (PubMed:18172504). Interacts with GDPD5; forms a mixed-disulfide with GDPD5 (By similarity). Interacts with SESN1 and SESN2 (PubMed:15105503). Interacts with FAM107A (PubMed:21969592)","family":"Belongs to the peroxiredoxin family. AhpC/Prx1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["9497357"],"location":"Cytoplasm；Melanosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"细胞周期/分裂；发育/分化；注释原文：Thiol-specific peroxidase that catalyzes the reduction of hydrogen peroxide and organic hydroperoxides to water and alcohols, respectively.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"细胞周期/分裂；发育/分化"},"PRDX6":{"hgnc":"HGNC:16753","symbol":"PRDX6","accessions":["P30041"],"name":"Peroxiredoxin-6","length":"224","function":"Thiol-specific peroxidase that catalyzes the reduction of hydrogen peroxide and organic hydroperoxides to water and alcohols, respectively (PubMed:10893423, PubMed:9497358). Can reduce H(2)O(2) and short chain organic, fatty acid, and phospholipid hydroperoxides (PubMed:10893423). Also has phospholipase activity, can therefore either reduce the oxidized sn-2 fatty acyl group of phospholipids (peroxidase activity) or hydrolyze the sn-2 ester bond of phospholipids (phospholipase activity) (PubMed:10893423, PubMed:26830860). These activities are dependent on binding to phospholipids at acidic pH and to oxidized phospholipds at cytosolic pH (PubMed:10893423). Plays a role in cell protection against oxidative stress by detoxifying peroxides and in phospholipid homeostasis (PubMed:10893423). Exhibits acyl-CoA-dependent lysophospholipid acyltransferase which mediates the conversion of lysophosphatidylcholine (1-acyl-sn-glycero-3-phosphocholine or LPC) into phosphatidylcholine (1,2-diacyl-sn-glycero-3-phosphocholine or PC) (PubMed:26830860). Shows a clear preference for LPC as the lysophospholipid and for palmitoyl CoA as the fatty acyl substrate (PubMed:26830860)","subunit":"Homodimer (PubMed:27353378, PubMed:9587003). Interacts with GSTP1; mediates PRDX6 glutathionylation and regeneration (By similarity). Interacts with APEX1 (PubMed:19188445). Interacts with STH (PubMed:16186110). May interact with FAM168B (PubMed:20716133). May interact with HTR2A (By similarity)","family":"Belongs to the peroxiredoxin family. Prx6 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10893423","26830860","9497358"],"location":"Cytoplasm；Lysosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"线粒体/代谢；注释原文：Thiol-specific peroxidase that catalyzes the reduction of hydrogen peroxide and organic hydroperoxides to water and alcohols, respectively (PubMed:10893423, PubMed:9497358).","function_evidence":"含实验支持条目；ECO:0000269","categories":"线粒体/代谢"},"PREB":{"hgnc":"HGNC:9356","symbol":"PREB","accessions":["Q9HCU5"],"name":"Guanine nucleotide-exchange factor SEC12","length":"417","function":"Guanine nucleotide exchange factor (GEF) that regulates the assembly of the coat protein complex II/COPII in endoplasmic reticulum (ER) to Golgi vesicle-mediated transport. Selectively activates SAR1A and SAR1B by promoting the exchange of guanosine diphosphate (GDP) for guanosine triphosphate (GTP) in these small GTPases (PubMed:32358066). In their activated GTP-bound state, SAR1A and SAR1B insert into the membrane of the endoplasmic reticulum where they recruit the remainder of the coat protein complex II/COPII which is responsible for both the sorting of proteins and the deformation and budding of membranes into vesicles destined to the Golgi (PubMed:32358066)\nWas first identified based on its probable role in the regulation of pituitary gene transcription. Binds to the prolactin gene (PRL) promoter and seems to activate transcription","subunit":"Interacts with SAR1B (GDP-bound form) (By similarity). Interacts with MIA2; recruits PREB to endoplasmic reticulum exit sites (PubMed:25202031, PubMed:27170179). Interacts with CIDEB; facilitating loading of SCAP-SREBP into COPII vesicles (By similarity)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["32358066"],"location":"Endoplasmic reticulum membrane；Single-pass membrane protein；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；膜运输/高尔基/内吞；注释原文：Guanine nucleotide exchange factor (GEF) that regulates the assembly of the coat protein complex II/COPII in endoplasmic reticulum (ER) to Golgi vesicle-mediated transport.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；膜运输/高尔基/内吞"},"PRELID2":{"hgnc":"HGNC:28306","symbol":"PRELID2","accessions":["Q8N945"],"name":"PRELI domain-containing protein 2","length":"189","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"Domain 1-187: PRELI/MSF1 [ECO:0000255/PROSITE-ProRule/PRU00158]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"PRICKLE4":{"hgnc":"HGNC:16805","symbol":"PRICKLE4","accessions":["Q2TBC4"],"name":"Prickle-like protein 4","length":"344","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"Belongs to the prickle / espinas / testin family","domains":"Domain 1-81: PET [ECO:0000255/PROSITE-ProRule/PRU00636]\nDomain 82-147: LIM zinc-binding 1 [ECO:0000255/PROSITE-ProRule/PRU00125]\nDomain 148-207: LIM zinc-binding 2 [ECO:0000255/PROSITE-ProRule/PRU00125]","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"PRIM1":{"hgnc":"HGNC:9369","symbol":"PRIM1","accessions":["P49642"],"name":"DNA primase small subunit","length":"420","function":"Catalytic subunit of the DNA primase complex and component of the DNA polymerase alpha complex (also known as the alpha DNA polymerase-primase complex - primosome/replisome) which play an essential role in the initiation of DNA synthesis (PubMed:17893144, PubMed:24043831, PubMed:25550159, PubMed:26975377, PubMed:31479243, PubMed:33060134, PubMed:9268648, PubMed:9705292). During the S phase of the cell cycle, the DNA polymerase alpha complex (composed of a catalytic subunit POLA1, an accessory subunit POLA2 and two primase subunits, the catalytic subunit PRIM1 and the regulatory subunit PRIM2) is recruited to DNA at the replicative forks via direct interactions with MCM10 and WDHD1 (By similarity). The primase subunit of the polymerase alpha complex initiates DNA synthesis by oligomerizing short RNA primers on both leading and lagging strands (PubMed:17893144). These primers are initially extended by the polymerase alpha catalytic subunit and subsequently transferred to polymerase delta and polymerase epsilon for processive synthesis on the lagging and leading strand, respectively (By similarity). In the primase complex, both subunits are necessary for the initial di-nucleotide formation, but the extension of the primer depends only on the catalytic subunit (PubMed:17893144). Synthesizes 9-mer RNA primers (also known as the 'unit length' RNA primers). Incorporates only ribonucleotides in the presence of ribo- and deoxy-nucleotide triphosphates (rNTPs, dNTPs) (PubMed:26975377). Requires template thymine or cytidine to start the RNA primer synthesis, with an adenine or guanine at its 5'-end (PubMed:25550159, PubMed:26975377). Binds single stranded DNA (By similarity)","subunit":"Heterodimer of a catalytic subunit PRIM1 and a regulatory subunit PRIM2, also known as the DNA primase complex (PubMed:17893144, PubMed:9705292). Interacts with PRIM2 (via C-terminus) (PubMed:17893144). Component of the alpha DNA polymerase complex (also known as the alpha DNA polymerase-primase complex) consisting of four subunits: the catalytic subunit POLA1, the regulatory subunit POLA2, and the primase complex subunits PRIM1 and PRIM2 respectively (PubMed:24043831, PubMed:26975377, PubMed:9705292). Within the complex, POLA1 directly interacts with PRIM2 (By similarity)","family":"Belongs to the eukaryotic-type primase small subunit family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["17893144","25550159","26975377","33060134","9268648","9705292"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"DNA修复/复制；细胞周期/分裂；注释原文：Catalytic subunit of the DNA primase complex and component of the DNA polymerase alpha complex (also known as the alpha DNA polymerase-primase complex - primosome/replisome) which play an essential role in the initiation of DNA synthesis (PubMed:17893144, PubMed:24043831, PubMed:25550159, PubMed:26975377, PubMed:31479243, PubMed:33060134, PubMed:9268648, PubMed:9705292).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"DNA修复/复制；细胞周期/分裂"},"PRIM2":{"hgnc":"HGNC:9370","symbol":"PRIM2","accessions":["P49643"],"name":"DNA primase large subunit","length":"509","function":"Regulatory subunit of the DNA primase complex and component of the DNA polymerase alpha complex (also known as the alpha DNA polymerase-primase complex) which play an essential role in the initiation of DNA synthesis (PubMed:17893144, PubMed:25550159, PubMed:26975377, PubMed:9705292). During the S phase of the cell cycle, the DNA polymerase alpha complex (composed of a catalytic subunit POLA1, an accessory subunit POLA2 and two primase subunits, the catalytic subunit PRIM1 and the regulatory subunit PRIM2) is recruited to DNA at the replicative forks via direct interactions with MCM10 and WDHD1 (By similarity). The primase subunit of the polymerase alpha complex initiates DNA synthesis by oligomerizing short RNA primers on both leading and lagging strands (PubMed:17893144). These primers are initially extended by the polymerase alpha catalytic subunit and subsequently transferred to polymerase delta and polymerase epsilon for processive synthesis on the lagging and leading strand, respectively (By similarity). In the primase complex, both subunits are necessary for the initial di-nucleotide formation, but the extension of the primer depends only on the catalytic subunit (PubMed:17893144, PubMed:25550159). Binds RNA:DNA duplex and coordinates the catalytic activities of PRIM1 and POLA2 during primase-to-polymerase switch","subunit":"Heterodimer of a catalytic subunit PRIM1 and a regulatory subunit PRIM2, also known as the DNA primase complex (PubMed:17893144, PubMed:9705292). Interacts via (C-terminus) with PRIM1 (PubMed:17893144). Component of the alpha DNA polymerase complex (also known as the alpha DNA polymerase-primase complex) consisting of four subunits: the catalytic subunit POLA1, the regulatory subunit POLA2, and the primase complex subunits PRIM1 and PRIM2 respectively (PubMed:26975377, PubMed:9705292). Within the complex, POLA1 directly interacts with PRIM2","family":"Belongs to the eukaryotic-type primase large subunit family","domains":[],"function_pmids":["17893144","25550159","26975377","9705292"],"location":"","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Regulatory subunit of the DNA primase complex and component of the DNA polymerase alpha complex (also known as the alpha DNA polymerase-primase complex) which play an essential role in the initiation of DNA synthesis (PubMed:17893144, PubMed:25550159, PubMed:26975377, PubMed:9705292). During the S phase of the cell cycle, the DNA polymerase alpha complex (composed of a catalytic subunit POLA1, an accessory subunit POLA2 and two primase subunits, the catalytic subunit PRIM1 and the regulatory subunit PRIM2) is recruited to DNA at the replicative forks via direct interactions with MCM10 and WDHD1 (By similarity). The primase subunit of the polymerase alpha complex initiates DNA synthesis by oligomerizing short RNA primers on both leading and lagging strands (PubMed:17893144). These primers are initially extended by the polymerase alpha catalytic subunit and subsequently transferred to polymerase delta and polymerase epsilon for processive synthesis on the lagging and leading strand, respectively (By similarity). In the primase complex, both subunits are necessary for the initial di-nucleotide formation, but the extension of the primer depends only on the catalytic subunit (PubMed:17893144, PubMed:25550159). Binds RNA:DNA duplex and coordinates the catalytic activities of PRIM1 and POLA2 during primase-to-polymerase switch"},"PRKAA1":{"hgnc":"HGNC:9376","symbol":"PRKAA1","accessions":["Q13131"],"name":"5'-AMP-activated protein kinase catalytic subunit alpha-1","length":"559","function":"Catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism (PubMed:17307971, PubMed:17712357, PubMed:24563466, PubMed:31492851, PubMed:37821951, PubMed:40233740). In response to reduction of intracellular ATP levels, AMPK activates energy-producing pathways and inhibits energy-consuming processes: inhibits protein, carbohydrate and lipid biosynthesis, as well as cell growth and proliferation (PubMed:17307971, PubMed:17712357). AMPK acts via direct phosphorylation of metabolic enzymes, and by longer-term effects via phosphorylation of transcription regulators (PubMed:17307971, PubMed:17712357). Regulates lipid synthesis by phosphorylating and inactivating lipid metabolic enzymes such as ACACA, ACACB, GYS1, HMGCR and LIPE; regulates fatty acid and cholesterol synthesis by phosphorylating acetyl-CoA carboxylase (ACACA and ACACB) and hormone-sensitive lipase (LIPE) enzymes, respectively (By similarity). Promotes lipolysis of lipid droplets by mediating phosphorylation of isoform 1 of CHKA (CHKalpha2) (PubMed:34077757). Regulates insulin-signaling and glycolysis by phosphorylating IRS1, PFKFB2 and PFKFB3 (By similarity). AMPK stimulates glucose uptake in muscle by increasing the translocation of the glucose transporter SLC2A4/GLUT4 to the plasma membrane, possibly by mediating phosphorylation of TBC1D4/AS160 (By similarity). Regulates transcription and chromatin structure by phosphorylating transcription regulators involved in energy metabolism such as CRTC2/TORC2, FOXO3, histone H2B, HDAC5, MEF2C, MLXIPL/ChREBP, EP300, HNF4A, p53/TP53, SREBF1, SREBF2 and PPARGC1A (PubMed:11518699, PubMed:11554766, PubMed:15866171, PubMed:17711846, PubMed:18184930). Acts as a key regulator of glucose homeostasis in liver by phosphorylating CRTC2/TORC2, leading to CRTC2/TORC2 sequestration in the cytoplasm (By similarity). In response to stress, phosphorylates 'Ser-36' of histone H2B (H2BS36ph), leading to promote transcription (By similarity). Acts as a key regulator of cell growth and proliferation by phosphorylating FNIP1, TSC2, RPTOR, WDR24 and ATG1/ULK1: in response to nutrient limitation, negatively regulates the mTORC1 complex by phosphorylating RPTOR component of the mTORC1 complex and by phosphorylating and activating TSC2 (PubMed:14651849, PubMed:18439900, PubMed:20160076, PubMed:21205641). Also phosphorylates and inhibits GATOR2 subunit WDR24 in response to nutrient limitation, leading to suppress glucose-mediated mTORC1 activation (PubMed:36732624). In response to energetic stress, phosphorylates FNIP1, inactivating the non-canonical mTORC1 signaling, thereby promoting nuclear translocation of TFEB and TFE3, and inducing transcription of lysosomal or autophagy genes (PubMed:37079666). In response to nutrient limitation, promotes autophagy by phosphorylating and activating ATG1/ULK1 (PubMed:21205641). In that process, it also activates WDR45/WIPI4 (PubMed:28561066). Phosphorylates CASP6, thereby preventing its autoprocessing and subsequent activation (PubMed:32029622). In response to nutrient limitation, phosphorylates transcription factor FOXO3 promoting FOXO3 mitochondrial import (By similarity). Also acts as a regulator of cellular polarity by remodeling the actin cytoskeleton; probably by indirectly activating myosin (PubMed:17486097). AMPK also acts as a regulator of circadian rhythm by mediating phosphorylation of CRY1, leading to destabilize it (By similarity). May regulate the Wnt signaling pathway by phosphorylating CTNNB1, leading to stabilize it (By similarity). Also has tau-protein kinase activity: in response to amyloid beta A4 protein (APP) exposure, activated by CAMKK2, leading to phosphorylation of MAPT/TAU; however the relevance of such data remains unclear in vivo (By similarity). Also phosphorylates CFTR, EEF2K, KLC1, NOS3 and SLC12A1 (PubMed:12519745, PubMed:20074060). Regulates hepatic lipogenesis. Activated via SIRT3, represses sterol regulatory element-binding protein (SREBP) transcriptional activities and ATP-consuming lipogenesis to restore cellular energy balance. Upon stress, regulates mitochondrial fragmentation through phosphorylation of MTFR1L (PubMed:36367943). Phosphorylates ALDH7A1 in response to cellular stress, such as hypoxia or ferroptotic stress, promoting ALDH7A1 recruitment to membranes (PubMed:31492851, PubMed:40233740)","subunit":"AMPK is a heterotrimer of an alpha catalytic subunit (PRKAA1 or PRKAA2), a beta (PRKAB1 or PRKAB2) and a gamma non-catalytic subunits (PRKAG1, PRKAG2 or PRKAG3) (PubMed:21680840). Interacts with FNIP1 and FNIP2 (PubMed:17028174, PubMed:18403135, PubMed:18663353). Interacts with LACC1; this interaction may regulate macrophage autophagic flux\n(Microbial infection) Interacts with Dengue type 2 virus non-structural protein 1; this interaction promotes the AMPK/ERK/mTOR signaling pathway to induce autophagy","family":"Belongs to the protein kinase superfamily. CAMK Ser/Thr protein kinase family. SNF1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11518699","11554766","12519745","14651849","15866171","17307971","17486097","17711846","17712357","18184930","18439900","20074060","20160076","21205641","24563466","28561066","31492851","32029622","34077757","36367943","36732624","37079666","37821951","40233740"],"location":"Cytoplasm；Nucleus；Late endosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；注释原文：Catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism (PubMed:17307971, PubMed:17712357, PubMed:24563466, PubMed:31492851, PubMed:37821951, PubMed:40233740).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000303","categories":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢"},"PRKAA2":{"hgnc":"HGNC:9377","symbol":"PRKAA2","accessions":["P54646"],"name":"5'-AMP-activated protein kinase catalytic subunit alpha-2","length":"552","function":"Catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism (PubMed:17307971, PubMed:17712357). In response to reduction of intracellular ATP levels, AMPK activates energy-producing pathways and inhibits energy-consuming processes: inhibits protein, carbohydrate and lipid biosynthesis, as well as cell growth and proliferation (PubMed:17307971, PubMed:17712357). AMPK acts via direct phosphorylation of metabolic enzymes, and by longer-term effects via phosphorylation of transcription regulators (PubMed:17307971, PubMed:17712357). Regulates lipid synthesis by phosphorylating and inactivating lipid metabolic enzymes such as ACACA, ACACB, GYS1, HMGCR and LIPE; regulates fatty acid and cholesterol synthesis by phosphorylating acetyl-CoA carboxylase (ACACA and ACACB) and hormone-sensitive lipase (LIPE) enzymes, respectively (PubMed:7959015). Promotes lipolysis of lipid droplets by mediating phosphorylation of isoform 1 of CHKA (CHKalpha2) (PubMed:34077757). Regulates insulin-signaling and glycolysis by phosphorylating IRS1, PFKFB2 and PFKFB3 (By similarity). Involved in insulin receptor/INSR internalization (PubMed:25687571). AMPK stimulates glucose uptake in muscle by increasing the translocation of the glucose transporter SLC2A4/GLUT4 to the plasma membrane, possibly by mediating phosphorylation of TBC1D4/AS160 (By similarity). Regulates transcription and chromatin structure by phosphorylating transcription regulators involved in energy metabolism such as CRTC2/TORC2, FOXO3, histone H2B, HDAC5, MEF2C, MLXIPL/ChREBP, EP300, HNF4A, p53/TP53, SREBF1, SREBF2 and PPARGC1A (PubMed:11518699, PubMed:11554766, PubMed:15866171, PubMed:17711846, PubMed:18184930). Acts as a key regulator of glucose homeostasis in liver by phosphorylating CRTC2/TORC2, leading to CRTC2/TORC2 sequestration in the cytoplasm (By similarity). In response to stress, phosphorylates 'Ser-36' of histone H2B (H2BS36ph), leading to promote transcription (By similarity). Acts as a key regulator of cell growth and proliferation by phosphorylating FNIP1, TSC2, RPTOR, WDR24 and ATG1/ULK1: in response to nutrient limitation, negatively regulates the mTORC1 complex by phosphorylating RPTOR component of the mTORC1 complex and by phosphorylating and activating TSC2 (PubMed:14651849, PubMed:20160076, PubMed:21205641). Also phosphorylates and inhibits GATOR2 subunit WDR24 in response to nutrient limitation, leading to suppress glucose-mediated mTORC1 activation (PubMed:36732624). In response to energetic stress, phosphorylates FNIP1, inactivating the non-canonical mTORC1 signaling, thereby promoting nuclear translocation of TFEB and TFE3, and inducing transcription of lysosomal or autophagy genes (PubMed:37079666). In response to nutrient limitation, promotes autophagy by phosphorylating and activating ATG1/ULK1 (PubMed:21205641). In that process, it also activates WDR45/WIPI4 (PubMed:28561066). Phosphorylates CASP6, thereby preventing its autoprocessing and subsequent activation (PubMed:32029622). AMPK also acts as a regulator of circadian rhythm by mediating phosphorylation of CRY1, leading to destabilize it (By similarity). May regulate the Wnt signaling pathway by phosphorylating CTNNB1, leading to stabilize it (By similarity). Also acts as a regulator of cellular polarity by remodeling the actin cytoskeleton; probably by indirectly activating myosin (PubMed:17486097). Also phosphorylates CFTR, EEF2K, KLC1, NOS3 and SLC12A1 (PubMed:12519745, PubMed:20074060). Plays an important role in the differential regulation of pro-autophagy (composed of PIK3C3, BECN1, PIK3R4 and UVRAG or ATG14) and non-autophagy (composed of PIK3C3, BECN1 and PIK3R4) complexes, in response to glucose starvation (By similarity). Can inhibit the non-autophagy complex by phosphorylating PIK3C3 and can activate the pro-autophagy complex by phosphorylating BECN1 (By similarity). Upon glucose starvation, promotes ARF6 activation in a kinase-independent manner leading to cell migration (PubMed:36017701). Upon glucose deprivation mediates the phosphorylation of ACSS2 at 'Ser-659', which exposes the nuclear localization signal of ACSS2, required for its interaction with KPNA1 and nuclear translocation (PubMed:28552616). Upon stress, regulates mitochondrial fragmentation through phosphorylation of MTFR1L (PubMed:36367943)","subunit":"AMPK is a heterotrimer of an alpha catalytic subunit (PRKAA1 or PRKAA2), a beta (PRKAB1 or PRKAB2) and a gamma non-catalytic subunits (PRKAG1, PRKAG2 or PRKAG3) (PubMed:21543851). Interacts with FNIP1 and FNIP2. Associates with internalized insulin receptor/INSR complexes on Golgi/endosomal membranes; PRKAA2/AMPK2 together with ATIC and HACD3/PTPLAD1 is proposed to be part of a signaling network regulating INSR autophosphorylation and endocytosis (PubMed:25687571). Interacts with ARF6 (PubMed:36017701). The phosphorylated form at Thr-172 mediated by CamKK2 interacts with ACSS2 (PubMed:28552616)","family":"Belongs to the protein kinase superfamily. CAMK Ser/Thr protein kinase family. SNF1 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11518699","11554766","12519745","14651849","15866171","17307971","17486097","17711846","17712357","18184930","20074060","20160076","21205641","25687571","28552616","28561066","32029622","34077757","36017701","36367943","36732624","37079666","7959015"],"location":"Cytoplasm；Nucleus；Late endosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；黏附/受体/细胞表面；注释原文：Catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism (PubMed:17307971, PubMed:17712357).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000303","categories":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；黏附/受体/细胞表面"},"PRKAB1":{"hgnc":"HGNC:9378","symbol":"PRKAB1","accessions":["Q9Y478"],"name":"5'-AMP-activated protein kinase subunit beta-1","length":"270","function":"Non-catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism. In response to reduction of intracellular ATP levels, AMPK activates energy-producing pathways and inhibits energy-consuming processes: inhibits protein, carbohydrate and lipid biosynthesis, as well as cell growth and proliferation. AMPK acts via direct phosphorylation of metabolic enzymes, and by longer-term effects via phosphorylation of transcription regulators. Also acts as a regulator of cellular polarity by remodeling the actin cytoskeleton; probably by indirectly activating myosin. Beta non-catalytic subunit acts as a scaffold on which the AMPK complex assembles, via its C-terminus that bridges alpha (PRKAA1 or PRKAA2) and gamma subunits (PRKAG1, PRKAG2 or PRKAG3)","subunit":"AMPK is a heterotrimer of an alpha catalytic subunit (PRKAA1 or PRKAA2), a beta (PRKAB1 or PRKAB2) and a gamma non-catalytic subunits (PRKAG1, PRKAG2 or PRKAG3). Interacts with FNIP1 and FNIP2","family":"Belongs to the 5'-AMP-activated protein kinase beta subunit family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；注释原文：Non-catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism.","function_evidence":"数据库整理/推断；按原文限定；","categories":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢"},"PRKAB2":{"hgnc":"HGNC:9379","symbol":"PRKAB2","accessions":["O43741"],"name":"5'-AMP-activated protein kinase subunit beta-2","length":"272","function":"Non-catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism. In response to reduction of intracellular ATP levels, AMPK activates energy-producing pathways and inhibits energy-consuming processes: inhibits protein, carbohydrate and lipid biosynthesis, as well as cell growth and proliferation. AMPK acts via direct phosphorylation of metabolic enzymes, and by longer-term effects via phosphorylation of transcription regulators. Also acts as a regulator of cellular polarity by remodeling the actin cytoskeleton; probably by indirectly activating myosin. Beta non-catalytic subunit acts as a scaffold on which the AMPK complex assembles, via its C-terminus that bridges alpha (PRKAA1 or PRKAA2) and gamma subunits (PRKAG1, PRKAG2 or PRKAG3)","subunit":"AMPK is a heterotrimer of an alpha catalytic subunit (PRKAA1 or PRKAA2), a beta (PRKAB1 or PRKAB2) and a gamma non-catalytic subunits (PRKAG1, PRKAG2 or PRKAG3)","family":"Belongs to the 5'-AMP-activated protein kinase beta subunit family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；注释原文：Non-catalytic subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism.","function_evidence":"数据库整理/推断；按原文限定；","categories":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢"},"PRKACA":{"hgnc":"HGNC:9380","symbol":"PRKACA","accessions":["P17612"],"name":"cAMP-dependent protein kinase catalytic subunit alpha","length":"351","function":"Phosphorylates a large number of substrates in the cytoplasm and the nucleus (PubMed:15642694, PubMed:15905176, PubMed:16387847, PubMed:17333334, PubMed:17565987, PubMed:17693412, PubMed:18836454, PubMed:19949837, PubMed:20356841, PubMed:21085490, PubMed:21514275, PubMed:21812984, PubMed:21852232, PubMed:31112131, PubMed:41652173). Phosphorylates CDC25B, ABL1, NFKB1, CLDN3, histone H1.4 (H1-4), PSMC5/RPT6, PJA2, RYR2, RORA, SLC6A6, SOX9, UHRF1 and VASP (PubMed:15178447, PubMed:15642694, PubMed:15905176, PubMed:16387847, PubMed:17333334, PubMed:17565987, PubMed:17693412, PubMed:18836454, PubMed:19949837, PubMed:20356841, PubMed:21085490, PubMed:21514275, PubMed:21812984, PubMed:41652173). Regulates the abundance of compartmentalized pools of its regulatory subunits through phosphorylation of PJA2 which binds and ubiquitinates these subunits, leading to their subsequent proteolysis (PubMed:21423175). RORA is activated by phosphorylation (PubMed:21514275). Required for glucose-mediated adipogenic differentiation increase and osteogenic differentiation inhibition from osteoblasts (PubMed:19949837). Involved in chondrogenesis by mediating phosphorylation of SOX9 (By similarity). Involved in the regulation of platelets in response to thrombin and collagen; maintains circulating platelets in a resting state by phosphorylating proteins in numerous platelet inhibitory pathways when in complex with NF-kappa-B (NFKB1 and NFKB2) and I-kappa-B-alpha (NFKBIA), but thrombin and collagen disrupt these complexes and free active PRKACA stimulates platelets and leads to platelet aggregation by phosphorylating VASP (PubMed:15642694, PubMed:20356841). Prevents the antiproliferative and anti-invasive effects of alpha-difluoromethylornithine in breast cancer cells when activated (PubMed:17333334). RYR2 channel activity is potentiated by phosphorylation in presence of luminal Ca(2+), leading to reduced amplitude and increased frequency of store overload-induced Ca(2+) release (SOICR) characterized by an increased rate of Ca(2+) release and propagation velocity of spontaneous Ca(2+) waves, despite reduced wave amplitude and resting cytosolic Ca(2+) (PubMed:17693412). PSMC5/RPT6 activation by phosphorylation stimulates proteasome (PubMed:17565987). Negatively regulates tight junctions (TJs) in ovarian cancer cells via CLDN3 phosphorylation (PubMed:15905176). NFKB1 phosphorylation promotes NF-kappa-B p50-p50 DNA binding (PubMed:15642694). Acts as a key inhibitor of smoothened signaling pathway by mediating phosphorylation of GLI (GLI1, GLI2 and GLI3) transcription factors in absence of hedgehog (DHH, IHH or SHH) morphogens: GLI phosphorylation promotes their processing and prevents transcriptional activation of smoothened target genes (PubMed:16705181). GLI transcription factor phosphorylation is inhibited by interaction of PRKACA with SMO which sequesters PRKACA at the cell membrane (PubMed:36202993, PubMed:39138140). Also inhibits the smoothened signaling pathway in embryonic development by catalyzing phosphorylation of OFD1 in ciliogenesis (PubMed:33934390). Prevents meiosis resumption in prophase-arrested oocytes via CDC25B inactivation by phosphorylation (By similarity). May also regulate rapid eye movement (REM) sleep in the pedunculopontine tegmental (PPT) (By similarity). Phosphorylates APOBEC3G and AICDA (PubMed:16387847, PubMed:18836454). Phosphorylates HSF1; this phosphorylation promotes HSF1 nuclear localization and transcriptional activity upon heat shock (PubMed:21085490). Acts as a negative regulator of mTORC1 by mediating phosphorylation of RPTOR (PubMed:31112131). Phosphorylates AKAP19 (PubMed:27028580)\nPhosphorylates and activates ABL1 in sperm flagellum to promote spermatozoa capacitation","subunit":"A number of inactive tetrameric holoenzymes are produced by the combination of homo- or heterodimers of the different regulatory subunits associated with two catalytic subunits. cAMP causes the dissociation of the inactive holoenzyme into a dimer of regulatory subunits bound to four cAMP and two free monomeric catalytic subunits. The cAMP-dependent protein kinase catalytic subunit binds PJA2. Both isoforms 1 and 2 forms activate cAMP-sensitive PKAI and PKAII holoenzymes by interacting with regulatory subunit (R) of PKA, PRKAR1A/PKR1 and PRKAR2A/PKR2, respectively. Interacts with PRKAR1A and PRKAR2B (PubMed:33058759). Interacts with NFKB1, NFKB2 and NFKBIA in platelets; these interactions are disrupted by thrombin and collagen. Binds to ABL1 in spermatozoa and with CDC25B in oocytes. Interacts with APOBEC3G and AICDA. Interacts with RAB13; downstream effector of RAB13 involved in tight junction assembly. Found in a complex at least composed of MROH2B, PRKACA isoform 2 and TCP11 (By similarity). Interacts with MROH2B (By similarity). Isoform 2 interacts with TCP11 (By similarity). Interacts with HSF1 (PubMed:21085490). Interacts with TBC1D31; in regulation of OFD1 (PubMed:33934390). Interacts in free form with SMO (via C-terminus); the interaction leads to sequestration of PRKACA at the membrane, preventing PRKACA-mediated phosphorylation of GLI transcription factors (PubMed:36202993, PubMed:39138140)","family":"Belongs to the protein kinase superfamily. AGC Ser/Thr protein kinase family. cAMP subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15178447","15642694","15905176","16387847","16705181","17333334","17565987","17693412","18836454","19949837","20356841","21085490","21423175","21514275","21812984","21852232","27028580","31112131","33934390","36202993","39138140","41652173"],"location":"Cytoplasm；Cell membrane；Membrane；Lipid-anchor；Nucleus；Mitochondrion；Cell projection, cilium, flagellum；Cytoplasmic vesicle, secretory vesicle, acrosome","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；发育/分化；注释原文：Phosphorylates a large number of substrates in the cytoplasm and the nucleus (PubMed:15642694, PubMed:15905176, PubMed:16387847, PubMed:17333334, PubMed:17565987, PubMed:17693412, PubMed:18836454, PubMed:19949837, PubMed:20356841, PubMed:21085490, PubMed:21514275, PubMed:21812984, PubMed:21852232, PubMed:31112131, PubMed:41652173).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；发育/分化"},"PRKACB":{"hgnc":"HGNC:9381","symbol":"PRKACB","accessions":["P22694"],"name":"cAMP-dependent protein kinase catalytic subunit beta","length":"351","function":"Mediates cAMP-dependent signaling triggered by receptor binding to GPCRs (PubMed:12420224, PubMed:21423175, PubMed:31112131). PKA activation regulates diverse cellular processes such as cell proliferation, the cell cycle, differentiation and regulation of microtubule dynamics, chromatin condensation and decondensation, nuclear envelope disassembly and reassembly, as well as regulation of intracellular transport mechanisms and ion flux (PubMed:12420224, PubMed:21423175). Regulates the abundance of compartmentalized pools of its regulatory subunits through phosphorylation of PJA2 which binds and ubiquitinates these subunits, leading to their subsequent proteolysis (PubMed:12420224, PubMed:21423175). Phosphorylates GPKOW which regulates its ability to bind RNA (PubMed:21880142). Acts as a negative regulator of mTORC1 by mediating phosphorylation of RPTOR (PubMed:31112131)","subunit":"A number of inactive tetrameric holoenzymes are produced by the combination of homo- or heterodimers of the different regulatory subunits associated with two catalytic subunits. cAMP causes the dissociation of the inactive holoenzyme into a dimer of regulatory subunits bound to four cAMP and two free monomeric catalytic subunits (By similarity). Interacts with PRKAR1A and PRKAR2B (PubMed:33058759). The cAMP-dependent protein kinase catalytic subunit binds PJA2 (PubMed:21423175). Interacts with GPKOW (PubMed:21880142)","family":"Belongs to the protein kinase superfamily. AGC Ser/Thr protein kinase family. cAMP subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12420224","21423175","21880142","31112131"],"location":"Cytoplasm；Cell membrane；Membrane；Lipid-anchor；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面；发育/分化；注释原文：Mediates cAMP-dependent signaling triggered by receptor binding to GPCRs (PubMed:12420224, PubMed:21423175, PubMed:31112131).","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；黏附/受体/细胞表面；发育/分化"},"PRKAG1":{"hgnc":"HGNC:9385","symbol":"PRKAG1","accessions":["P54619"],"name":"5'-AMP-activated protein kinase subunit gamma-1","length":"331","function":"AMP/ATP-binding subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism (PubMed:21680840, PubMed:24563466). In response to reduction of intracellular ATP levels, AMPK activates energy-producing pathways and inhibits energy-consuming processes: inhibits protein, carbohydrate and lipid biosynthesis, as well as cell growth and proliferation (PubMed:21680840, PubMed:24563466). AMPK acts via direct phosphorylation of metabolic enzymes, and by longer-term effects via phosphorylation of transcription regulators (PubMed:21680840, PubMed:24563466). Also acts as a regulator of cellular polarity by remodeling the actin cytoskeleton; probably by indirectly activating myosin (PubMed:21680840, PubMed:24563466). Gamma non-catalytic subunit mediates binding to AMP, ADP and ATP, leading to activate or inhibit AMPK: AMP-binding results in allosteric activation of alpha catalytic subunit (PRKAA1 or PRKAA2) both by inducing phosphorylation and preventing dephosphorylation of catalytic subunits (PubMed:21680840, PubMed:24563466). ADP also stimulates phosphorylation, without stimulating already phosphorylated catalytic subunit (PubMed:21680840, PubMed:24563466). ATP promotes dephosphorylation of catalytic subunit, rendering the AMPK enzyme inactive (PubMed:21680840, PubMed:24563466)","subunit":"AMPK is a heterotrimer of an alpha catalytic subunit (PRKAA1 or PRKAA2), a beta (PRKAB1 or PRKAB2) and a gamma non-catalytic subunits (PRKAG1, PRKAG2 or PRKAG3). Interacts with FNIP1 and FNIP2","family":"Belongs to the 5'-AMP-activated protein kinase gamma subunit family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21680840","24563466"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢；注释原文：AMP/ATP-binding subunit of AMP-activated protein kinase (AMPK), an energy sensor protein kinase that plays a key role in regulating cellular energy metabolism (PubMed:21680840, PubMed:24563466).","function_evidence":"含实验支持条目；ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；细胞骨架/纤毛；线粒体/代谢"},"PRKCD":{"hgnc":"HGNC:9399","symbol":"PRKCD","accessions":["Q05655"],"name":"Protein kinase C delta type","length":"676","function":"Calcium-independent, phospholipid- and diacylglycerol (DAG)-dependent serine/threonine-protein kinase that plays contrasting roles in cell death and cell survival by functioning as a pro-apoptotic protein during DNA damage-induced apoptosis, but acting as an anti-apoptotic protein during cytokine receptor-initiated cell death, is involved in tumor suppression as well as survival of several cancers, is required for oxygen radical production by NADPH oxidase and acts as positive or negative regulator in platelet functional responses (PubMed:21406692, PubMed:21810427). Negatively regulates B cell proliferation and also has an important function in self-antigen induced B cell tolerance induction (By similarity). Upon DNA damage, activates the promoter of the death-promoting transcription factor BCLAF1/Btf to trigger BCLAF1-mediated p53/TP53 gene transcription and apoptosis (PubMed:21406692, PubMed:21810427). In response to oxidative stress, interact with and activate CHUK/IKKA in the nucleus, causing the phosphorylation of p53/TP53 (PubMed:21406692, PubMed:21810427). In the case of ER stress or DNA damage-induced apoptosis, can form a complex with the tyrosine-protein kinase ABL1 which trigger apoptosis independently of p53/TP53 (PubMed:21406692, PubMed:21810427). In cytosol can trigger apoptosis by activating MAPK11 or MAPK14, inhibiting AKT1 and decreasing the level of X-linked inhibitor of apoptosis protein (XIAP), whereas in nucleus induces apoptosis via the activation of MAPK8 or MAPK9. Upon ionizing radiation treatment, is required for the activation of the apoptosis regulators BAX and BAK, which trigger the mitochondrial cell death pathway. Can phosphorylate MCL1 and target it for degradation which is sufficient to trigger for BAX activation and apoptosis. Is required for the control of cell cycle progression both at G1/S and G2/M phases. Mediates phorbol 12-myristate 13-acetate (PMA)-induced inhibition of cell cycle progression at G1/S phase by up-regulating the CDK inhibitor CDKN1A/p21 and inhibiting the cyclin CCNA2 promoter activity. In response to UV irradiation can phosphorylate CDK1, which is important for the G2/M DNA damage checkpoint activation (By similarity). Can protect glioma cells from the apoptosis induced by TNFSF10/TRAIL, probably by inducing increased phosphorylation and subsequent activation of AKT1 (PubMed:15774464). Is highly expressed in a number of cancer cells and promotes cell survival and resistance against chemotherapeutic drugs by inducing cyclin D1 (CCND1) and hyperphosphorylation of RB1, and via several pro-survival pathways, including NF-kappa-B, AKT1 and MAPK1/3 (ERK1/2). Involved in antifungal immunity by mediating phosphorylation and activation of CARD9 downstream of C-type lectin receptors activation, promoting interaction between CARD9 and BCL10, followed by activation of NF-kappa-B and MAP kinase p38 pathways (By similarity). Can also act as tumor suppressor upon mitogenic stimulation with PMA or TPA. In N-formyl-methionyl-leucyl-phenylalanine (fMLP)-treated cells, is required for NCF1 (p47-phox) phosphorylation and activation of NADPH oxidase activity, and regulates TNF-elicited superoxide anion production in neutrophils, by direct phosphorylation and activation of NCF1 or indirectly through MAPK1/3 (ERK1/2) signaling pathways (PubMed:19801500). May also play a role in the regulation of NADPH oxidase activity in eosinophil after stimulation with IL5, leukotriene B4 or PMA (PubMed:11748588). In collagen-induced platelet aggregation, acts a negative regulator of filopodia formation and actin polymerization by interacting with and negatively regulating VASP phosphorylation (PubMed:16940418). Downstream of PAR1, PAR4 and CD36/GP4 receptors, regulates differentially platelet dense granule secretion; acts as a positive regulator in PAR-mediated granule secretion, whereas it negatively regulates CD36/GP4-mediated granule release (PubMed:19587372). Phosphorylates MUC1 in the C-terminal and regulates the interaction between MUC1 and beta-catenin (PubMed:11877440). The catalytic subunit phosphorylates 14-3-3 proteins (YWHAB, YWHAZ and YWHAH) in a sphingosine-dependent fashion (By similarity). Phosphorylates ELAVL1 in response to angiotensin-2 treatment (PubMed:18285462). Phosphorylates mitochondrial phospholipid scramblase 3 (PLSCR3), resulting in increased cardiolipin expression on the mitochondrial outer membrane which facilitates apoptosis (PubMed:12649167). Phosphorylates SMPD1 which induces SMPD1 secretion (PubMed:17303575). Acts as a negative regulator of smoothened signaling by mediating phosphorylation of GLI1, preventing its localization to the nucleus (PubMed:19015273). Acts as a regulator of dopamine signaling by mediating constitutive phosphorylation of dopamine receptor DRD1, inhibiting G protein-coupled receptor signaling (PubMed:20969574)","subunit":"Interacts with PDPK1 (via N-terminal region) (PubMed:11781095). Interacts with RAD9A (PubMed:12628935). Interacts with CDCP1 (PubMed:15851033). Interacts with MUC1 (PubMed:11877440). Interacts with VASP (PubMed:16940418). Interacts with CAVIN3 (By similarity). Interacts with PRKD2 (via N-terminus and zing-finger domain 1 and 2) in response to oxidative stress; the interaction is independent of PRKD2 tyrosine phosphorylation (PubMed:28428613). Interacts with PLSC3; interaction is enhanced by UV irradiation (PubMed:12649167). Interacts with PRKCH upstream open reading frame 2; the interaction leads to inhibition of kinase activity (PubMed:34593629)","family":"Belongs to the protein kinase superfamily. AGC Ser/Thr protein kinase family. PKC subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11748588","11877440","12649167","15774464","16940418","17303575","18285462","19015273","19587372","19801500","20969574","21406692","21810427"],"location":"Cytoplasm；Cytoplasm, perinuclear region；Nucleus；Cell membrane；Peripheral membrane protein；Mitochondrion；Endomembrane system","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面；注释原文：Calcium-independent, phospholipid- and diacylglycerol (DAG)-dependent serine/threonine-protein kinase that plays contrasting roles in cell death and cell survival by functioning as a pro-apoptotic protein during DNA damage-induced apoptosis, but acting as an anti-apoptotic protein during cytokine receptor-initiated cell death, is involved in tumor suppression as well as survival of several cancers, is required for oxygen radical production by NADPH oxidase and acts as positive or negative regulator in platelet functional responses (PubMed:21406692, PubMed:21810427).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000303","categories":"染色质/转录调控；DNA修复/复制；细胞周期/分裂；激酶/磷酸化信号；细胞骨架/纤毛；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"PRKCI":{"hgnc":"HGNC:9404","symbol":"PRKCI","accessions":["P41743"],"name":"Protein kinase C iota type","length":"596","function":"Calcium- and diacylglycerol-independent serine/ threonine-protein kinase that plays a general protective role against apoptotic stimuli, is involved in NF-kappa-B activation, cell survival, differentiation and polarity, and contributes to the regulation of microtubule dynamics in the early secretory pathway. Is necessary for BCR-ABL oncogene-mediated resistance to apoptotic drug in leukemia cells, protecting leukemia cells against drug-induced apoptosis. In cultured neurons, prevents amyloid beta protein-induced apoptosis by interrupting cell death process at a very early step. In glioblastoma cells, may function downstream of phosphatidylinositol 3-kinase (PI(3)K) and PDPK1 in the promotion of cell survival by phosphorylating and inhibiting the pro-apoptotic factor BAD. Can form a protein complex in non-small cell lung cancer (NSCLC) cells with PARD6A and ECT2 and regulate ECT2 oncogenic activity by phosphorylation, which in turn promotes transformed growth and invasion. In response to nerve growth factor (NGF), acts downstream of SRC to phosphorylate and activate IRAK1, allowing the subsequent activation of NF-kappa-B and neuronal cell survival. Functions in the organization of the apical domain in epithelial cells by phosphorylating EZR. This step is crucial for activation and normal distribution of EZR at the early stages of intestinal epithelial cell differentiation. Forms a protein complex with LLGL1 and PARD6B independently of PARD3 to regulate epithelial cell polarity. Plays a role in microtubule dynamics in the early secretory pathway through interaction with RAB2A and GAPDH and recruitment to vesicular tubular clusters (VTCs). In human coronary artery endothelial cells (HCAEC), is activated by saturated fatty acids and mediates lipid-induced apoptosis. Involved in early synaptic long term potentiation phase in CA1 hippocampal cells and short term memory formation (By similarity)","subunit":"Forms a complex with SQSTM1 and MP2K5 (By similarity). Interacts directly with SQSTM1 (Probable). Interacts with IKBKB. Interacts with PARD6A, PARD6B and PARD6G. Part of a quaternary complex containing aPKC, PARD3, a PARD6 protein (PARD6A, PARD6B or PARD6G) and a GTPase protein (CDC42 or RAC1). Part of a complex with LLGL1 and PARD6B. Interacts with ADAP1/CENTA1. Interaction with SMG1, through the ZN-finger domain, activates the kinase activity. Interacts with CDK7. Forms a complex with RAB2A and GAPDH involved in recruitment onto the membrane of vesicular tubular clusters (VTCs). Interacts with ECT2 ('Thr-359' phosphorylated form). Interacts with VAMP2 (PubMed:17313651). Interacts with WDFY2 (via WD repeats 1-3) (PubMed:16792529)","family":"Belongs to the protein kinase superfamily. AGC Ser/Thr protein kinase family. PKC subfamily","domains":[],"function_pmids":["10356400","10467349","10906326","11042363","11724794","12871960","14684752","15994303","18270268","19327373","21189248","21419810","8226978","9346882"],"location":"Cytoplasm; Membrane; Endosome; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Calcium- and diacylglycerol-independent serine/ threonine-protein kinase that plays a general protective role against apoptotic stimuli, is involved in NF-kappa-B activation, cell survival, differentiation and polarity, and contributes to the regulation of microtubule dynamics in the early secretory pathway. Is necessary for BCR-ABL oncogene-mediated resistance to apoptotic drug in leukemia cells, protecting leukemia cells against drug-induced apoptosis. In cultured neurons, prevents amyloid beta protein-induced apoptosis by interrupting cell death process at a very early step. In glioblastoma cells, may function downstream of phosphatidylinositol 3-kinase (PI(3)K) and PDPK1 in the promotion of cell survival by phosphorylating and inhibiting the pro-apoptotic factor BAD. Can form a protein complex in non-small cell lung cancer (NSCLC) cells with PARD6A and ECT2 and regulate ECT2 oncogenic activity by phosphorylation, which in turn promotes transformed growth and invasion. In response to nerve growth factor (NGF), acts downstream of SRC to phosphorylate and activate IRAK1, allowing the subsequent activation of NF-kappa-B and neuronal cell survival. Functions in the organization of the apical domain in epithelial cells by phosphorylating EZR. This step is crucial for activation and normal distribution of EZR at the early stages of intestinal epithelial cell differentiation. Forms a protein complex with LLGL1 and PARD6B independently of PARD3 to regulate epithelial cell polarity. Plays a role in microtubule dynamics in the early secretory pathway through interaction with RAB2A and GAPDH and recruitment to vesicular tubular clusters (VTCs). In human coronary artery endothelial cells (HCAEC), is activated by saturated fatty acids and mediates lipid-induced apoptosis. Involved in early synaptic long term potentiation phase in CA1 hippocampal cells and short term memory formation (By similarity)"},"PRKD2":{"hgnc":"HGNC:17293","symbol":"PRKD2","accessions":["Q9BZL6"],"name":"Serine/threonine-protein kinase D2","length":"878","function":"Serine/threonine-protein kinase that converts transient diacylglycerol (DAG) signals into prolonged physiological effects downstream of PKC, and is involved in the regulation of cell proliferation via MAPK1/3 (ERK1/2) signaling, oxidative stress-induced NF-kappa-B activation, inhibition of HDAC7 transcriptional repression, signaling downstream of T-cell antigen receptor (TCR) and cytokine production, and plays a role in Golgi membrane trafficking, angiogenesis, secretory granule release and cell adhesion (PubMed:14743217, PubMed:15604256, PubMed:16928771, PubMed:17077180, PubMed:17951978, PubMed:17962809, PubMed:18262756, PubMed:19001381, PubMed:19192391, PubMed:23503467, PubMed:28428613). May potentiate mitogenesis induced by the neuropeptide bombesin by mediating an increase in the duration of MAPK1/3 (ERK1/2) signaling, which leads to accumulation of immediate-early gene products including FOS that stimulate cell cycle progression (By similarity). In response to oxidative stress, is phosphorylated at Tyr-438 and Tyr-717 by ABL1, which leads to the activation of PRKD2 without increasing its catalytic activity, and mediates activation of NF-kappa-B (PubMed:15604256, PubMed:28428613). In response to the activation of the gastrin receptor CCKBR, is phosphorylated at Ser-244 by CSNK1D and CSNK1E, translocates to the nucleus, phosphorylates HDAC7, leading to nuclear export of HDAC7 and inhibition of HDAC7 transcriptional repression of NR4A1/NUR77 (PubMed:17962809). Upon TCR stimulation, is activated independently of ZAP70, translocates from the cytoplasm to the nucleus and is required for interleukin-2 (IL2) promoter up-regulation (PubMed:17077180). During adaptive immune responses, is required in peripheral T-lymphocytes for the production of the effector cytokines IL2 and IFNG after TCR engagement and for optimal induction of antibody responses to antigens (By similarity). In epithelial cells stimulated with lysophosphatidic acid (LPA), is activated through a PKC-dependent pathway and mediates LPA-stimulated interleukin-8 (IL8) secretion via a NF-kappa-B-dependent pathway (PubMed:16928771). During TCR-induced T-cell activation, interacts with and is activated by the tyrosine kinase LCK, which results in the activation of the NFAT transcription factors (PubMed:19192391). In the trans-Golgi network (TGN), regulates the fission of transport vesicles that are on their way to the plasma membrane and in polarized cells is involved in the transport of proteins from the TGN to the basolateral membrane (PubMed:14743217). Plays an important role in endothelial cell proliferation and migration prior to angiogenesis, partly through modulation of the expression of KDR/VEGFR2 and FGFR1, two key growth factor receptors involved in angiogenesis (PubMed:19001381). In secretory pathway, is required for the release of chromogranin-A (CHGA)-containing secretory granules from the TGN (PubMed:18262756). Downstream of PRKCA, plays important roles in angiotensin-2-induced monocyte adhesion to endothelial cells (PubMed:17951978). Plays a regulatory role in angiogenesis and tumor growth by phosphorylating a downstream mediator CIB1 isoform 2, resulting in vascular endothelial growth factor A (VEGFA) secretion (PubMed:23503467)","subunit":"Interacts (via C-terminus) with LCK (PubMed:19192391). Interacts (via N-terminal AP-rich region) with CIB1 isoform 2 (PubMed:23503467). Interacts (via N-terminus and zing-finger domain 1 and 2) with PRKCD in response to oxidative stress; the interaction is independent of PRKD2 tyrosine phosphorylation (PubMed:28428613)","family":"Belongs to the protein kinase superfamily. CAMK Ser/Thr protein kinase family. PKD subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["14743217","15604256","16928771","17077180","17951978","17962809","18262756","19001381","19192391","23503467","28428613"],"location":"Cytoplasm；Cell membrane；Nucleus；Golgi apparatus, trans-Golgi network","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"核质运输；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Serine/threonine-protein kinase that converts transient diacylglycerol (DAG) signals into prolonged physiological effects downstream of PKC, and is involved in the regulation of cell proliferation via MAPK1/3 (ERK1/2) signaling, oxidative stress-induced NF-kappa-B activation, inhibition of HDAC7 transcriptional repression, signaling downstream of T-cell antigen receptor (TCR) and cytokine production, and plays a role in Golgi membrane trafficking, angiogenesis, secretory granule release and cell adhesion (PubMed:14743217, PubMed:15604256, PubMed:16928771, PubMed:17077180, PubMed:17951978, PubMed:17962809, PubMed:18262756, PubMed:19001381, PubMed:19192391, PubMed:23503467, PubMed:28428613).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"核质运输；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"PRKDC":{"hgnc":"HGNC:9413","symbol":"PRKDC","accessions":["P78527"],"name":"DNA-dependent protein kinase catalytic subunit","length":"4128","function":"Serine/threonine-protein kinase that acts as a molecular sensor for DNA damage (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:33854234). Involved in DNA non-homologous end joining (NHEJ) required for double-strand break (DSB) repair and V(D)J recombination (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:33854234, PubMed:34352203). Must be bound to DNA to express its catalytic properties (PubMed:11955432). Promotes processing of hairpin DNA structures in V(D)J recombination by activation of the hairpin endonuclease artemis (DCLRE1C) (PubMed:11955432). Recruited by XRCC5 and XRCC6 to DNA ends and is required to (1) protect and align broken ends of DNA, thereby preventing their degradation, (2) and sequester the DSB for repair by NHEJ (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326, PubMed:33854234). Acts as a scaffold protein to aid the localization of DNA repair proteins to the site of damage (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326). The assembly of the DNA-PK complex at DNA ends is also required for the NHEJ ligation step (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326). Found at the ends of chromosomes, suggesting a further role in the maintenance of telomeric stability and the prevention of chromosomal end fusion (By similarity). Also involved in modulation of transcription (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326). As part of the DNA-PK complex, involved in the early steps of ribosome assembly by promoting the processing of precursor rRNA into mature 18S rRNA in the small-subunit processome (PubMed:32103174). Binding to U3 small nucleolar RNA, recruits PRKDC and XRCC5/Ku86 to the small-subunit processome (PubMed:32103174). Recognizes the substrate consensus sequence [ST]-Q (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:15574326). Phosphorylates 'Ser-139' of histone variant H2AX, thereby regulating DNA damage response mechanism (PubMed:14627815, PubMed:16046194). Phosphorylates ASF1A, DCLRE1C, c-Abl/ABL1, histone H1, HSPCA, c-jun/JUN, p53/TP53, PARP1, POU2F1, DHX9, FH, SRF, NHEJ1/XLF, XRCC1, XRCC4, XRCC5, XRCC6, WRN, MYC and RFA2 (PubMed:10026262, PubMed:10467406, PubMed:11889123, PubMed:12509254, PubMed:14599745, PubMed:14612514, PubMed:14704337, PubMed:15177042, PubMed:1597196, PubMed:16397295, PubMed:18644470, PubMed:2247066, PubMed:2507541, PubMed:26237645, PubMed:26666690, PubMed:28712728, PubMed:29478807, PubMed:30247612, PubMed:8407951, PubMed:8464713, PubMed:9139719, PubMed:9362500). Can phosphorylate C1D not only in the presence of linear DNA but also in the presence of supercoiled DNA (PubMed:9679063). Ability to phosphorylate p53/TP53 in the presence of supercoiled DNA is dependent on C1D (PubMed:9363941). Acts as a regulator of the phosphatidylinositol 3-kinase/protein kinase B signal transduction by mediating phosphorylation of 'Ser-473' of protein kinase B (PKB/AKT1, PKB/AKT2, PKB/AKT3), promoting their activation (PubMed:15262962). Contributes to the determination of the circadian period length by antagonizing phosphorylation of CRY1 'Ser-588' and increasing CRY1 protein stability, most likely through an indirect mechanism (By similarity). Plays a role in the regulation of DNA virus-mediated innate immune response by assembling into the HDP-RNP complex, a complex that serves as a platform for IRF3 phosphorylation and subsequent innate immune response activation through the cGAS-STING pathway (PubMed:28712728). Also regulates the cGAS-STING pathway by catalyzing phosphorylation of CGAS, thereby impairing CGAS oligomerization and activation (PubMed:33273464). Also regulates the cGAS-STING pathway by mediating phosphorylation of PARP1 (PubMed:35460603)","subunit":"DNA-PK is a heterotrimer of PRKDC and the Ku dimer (composed of XRCC6/Ku70 and XRCC5/Ku86) (PubMed:15758953, PubMed:25670504). Formation of this complex may be promoted by interaction with ILF3 (PubMed:9442054). Component of the core long-range non-homologous end joining (NHEJ) complex (also named DNA-PK complex) composed of PRKDC, LIG4, XRCC4, XRCC6/Ku70, XRCC5/Ku86 and NHEJ1/XLF (PubMed:15758953, PubMed:25670504, PubMed:33854234, PubMed:34352203). Additional component of the NHEJ complex includes PAXX (PubMed:25574025, PubMed:25941166). Following autophosphorylation, PRKDC dissociates from DNA (PubMed:33854234). Interacts with DNA-PKcs-interacting protein (KIP) with the region upstream the kinase domain (PubMed:9372844). PRKDC alone also interacts with and phosphorylates DCLRE1C, thereby activating the latent endonuclease activity of this protein (PubMed:11955432, PubMed:14744996, PubMed:15071507, PubMed:15456891, PubMed:15574326, PubMed:15811628, PubMed:15936993). Interacts with C1D (PubMed:9679063). Interacts with TTI1 and TELO2 (PubMed:20427287, PubMed:20801936, PubMed:20810650). Interacts with CIB1 (PubMed:9372844). Interacts with SETX (PubMed:23149945). Interacts with NR4A3; the DNA-dependent protein kinase complex DNA-PK phosphorylates and activates NR4A3 and prevents NR4A3 ubiquitination and degradation (PubMed:25852083). Interacts with BRAT1 (PubMed:22977523). Part of the HDP-RNP complex composed of at least HEXIM1, PRKDC, XRCC5, XRCC6, paraspeckle proteins (SFPQ, NONO, PSPC1, RBM14, and MATR3) and NEAT1 RNA (PubMed:28712728). Interacts with KAT5 (PubMed:32832608)","family":"Belongs to the PI3/PI4-kinase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10026262","10467406","11889123","11955432","12509254","12649176","14599745","14612514","14627815","14704337","14734805","15177042","15262962","15574326","1597196","16046194","16397295","18644470","2247066","2507541","26237645","26666690","28712728","29478807","30247612","32103174","33273464","33854234","34352203","35460603","8407951","8464713","9139719","9362500","9363941","9679063"],"location":"Nucleus；Nucleus, nucleolus；Cytoplasm, cytosol","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；翻译/核糖体；免疫/炎症/细胞死亡；注释原文：Serine/threonine-protein kinase that acts as a molecular sensor for DNA damage (PubMed:11955432, PubMed:12649176, PubMed:14734805, PubMed:33854234).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；翻译/核糖体；免疫/炎症/细胞死亡"},"PRKN":{"hgnc":"HGNC:8607","symbol":"PRKN","accessions":["O60260"],"name":"E3 ubiquitin-protein ligase parkin","length":"465","function":"Functions within a multiprotein E3 ubiquitin ligase complex, catalyzing the covalent attachment of ubiquitin moieties onto substrate proteins (PubMed:10888878, PubMed:10973942, PubMed:11431533, PubMed:12150907, PubMed:12628165, PubMed:15105460, PubMed:16135753, PubMed:21376232, PubMed:21532592, PubMed:22396657, PubMed:23620051, PubMed:23754282, PubMed:24660806, PubMed:24751536, PubMed:29311685, PubMed:32047033). Substrates include SYT11 and VDAC1 (PubMed:29311685, PubMed:32047033). Other substrates are BCL2, CCNE1, GPR37, RHOT1/MIRO1, MFN1, MFN2, STUB1, SNCAIP, SEPTIN5, TOMM20, USP30, ZNF746, MIRO1 and AIMP2 (PubMed:10888878, PubMed:10973942, PubMed:11431533, PubMed:12150907, PubMed:12628165, PubMed:15105460, PubMed:16135753, PubMed:21376232, PubMed:21532592, PubMed:22396657, PubMed:23620051, PubMed:23754282, PubMed:24660806, PubMed:24751536). Mediates monoubiquitination as well as 'Lys-6', 'Lys-11', 'Lys-48'-linked and 'Lys-63'-linked polyubiquitination of substrates depending on the context (PubMed:19229105, PubMed:20889974, PubMed:25474007, PubMed:25621951, PubMed:32047033). Participates in the removal and/or detoxification of abnormally folded or damaged protein by mediating 'Lys-63'-linked polyubiquitination of misfolded proteins such as PARK7: 'Lys-63'-linked polyubiquitinated misfolded proteins are then recognized by HDAC6, leading to their recruitment to aggresomes, followed by degradation (PubMed:17846173, PubMed:19229105). Mediates 'Lys-63'-linked polyubiquitination of a 22 kDa O-linked glycosylated isoform of SNCAIP, possibly playing a role in Lewy-body formation (PubMed:11431533, PubMed:11590439, PubMed:15105460, PubMed:15728840, PubMed:19229105). Mediates monoubiquitination of BCL2, thereby acting as a positive regulator of autophagy (PubMed:20889974). Protects against mitochondrial dysfunction during cellular stress, by acting downstream of PINK1 to coordinate mitochondrial quality control mechanisms that remove and replace dysfunctional mitochondrial components (PubMed:11439185, PubMed:18957282, PubMed:19029340, PubMed:19966284, PubMed:21376232, PubMed:22082830, PubMed:22396657, PubMed:23620051, PubMed:23933751, PubMed:24660806, PubMed:24784582, PubMed:24896179, PubMed:25474007, PubMed:25527291, PubMed:32047033). Depending on the severity of mitochondrial damage and/or dysfunction, activity ranges from preventing apoptosis and stimulating mitochondrial biogenesis to regulating mitochondrial dynamics and eliminating severely damaged mitochondria via mitophagy (PubMed:11439185, PubMed:19029340, PubMed:19801972, PubMed:19966284, PubMed:21376232, PubMed:22082830, PubMed:22396657, PubMed:23620051, PubMed:23685073, PubMed:23933751, PubMed:24896179, PubMed:25527291, PubMed:32047033, PubMed:33499712). Activation and recruitment onto the outer membrane of damaged/dysfunctional mitochondria (OMM) requires PINK1-mediated phosphorylation of both PRKN and ubiquitin (PubMed:24660806, PubMed:24784582, PubMed:25474007, PubMed:25527291). After mitochondrial damage, functions with PINK1 to mediate the decision between mitophagy or preventing apoptosis by inducing either the poly- or monoubiquitination of VDAC1, respectively; polyubiquitination of VDAC1 promotes mitophagy, while monoubiquitination of VDAC1 decreases mitochondrial calcium influx which ultimately inhibits apoptosis (PubMed:27534820, PubMed:32047033). When cellular stress results in irreversible mitochondrial damage, promotes the autophagic degradation of dysfunctional depolarized mitochondria (mitophagy) by promoting the ubiquitination of mitochondrial proteins such as TOMM20, RHOT1/MIRO1, MFN1 and USP30 (PubMed:19029340, PubMed:19966284, PubMed:21753002, PubMed:22396657, PubMed:23620051, PubMed:23685073, PubMed:23933751, PubMed:24896179, PubMed:25527291). Preferentially assembles 'Lys-6'-, 'Lys-11'- and 'Lys-63'-linked polyubiquitin chains, leading to mitophagy (PubMed:25621951, PubMed:32047033). The PINK1-PRKN pathway also promotes fission of damaged mitochondria by PINK1-mediated phosphorylation which promotes the PRKN-dependent degradation of mitochondrial proteins involved in fission such as MFN2 (PubMed:23620051). This prevents the refusion of unhealthy mitochondria with the mitochondrial network or initiates mitochondrial fragmentation facilitating their later engulfment by autophagosomes (PubMed:23620051). Regulates motility of damaged mitochondria via the ubiquitination and subsequent degradation of MIRO1 and MIRO2; in motor neurons, this likely inhibits mitochondrial intracellular anterograde transport along the axons which probably increases the chance of the mitochondria undergoing mitophagy in the soma (PubMed:22396657). Involved in mitochondrial biogenesis via the 'Lys-48'-linked polyubiquitination of transcriptional repressor ZNF746/PARIS which leads to its subsequent proteasomal degradation and allows activation of the transcription factor PPARGC1A (PubMed:21376232). Limits the production of reactive oxygen species (ROS) (PubMed:18541373). Regulates cyclin-E during neuronal apoptosis (PubMed:12628165). In collaboration with CHPF isoform 2, may enhance cell viability and protect cells from oxidative stress (PubMed:22082830). Independently of its ubiquitin ligase activity, protects from apoptosis by the transcriptional repression of p53/TP53 (PubMed:19801972). May protect neurons against alpha synuclein toxicity, proteasomal dysfunction, GPR37 accumulation, and kainate-induced excitotoxicity (PubMed:11439185). May play a role in controlling neurotransmitter trafficking at the presynaptic terminal and in calcium-dependent exocytosis. May represent a tumor suppressor gene (PubMed:12719539)","subunit":"Forms an E3 ubiquitin ligase complex with UBE2L3 or UBE2L6 (PubMed:11078524, PubMed:21532592). Mediates 'Lys-63'-linked polyubiquitination by associating with UBE2V1. Part of a SCF-like complex, consisting of PRKN, CUL1 and FBXW7 (PubMed:12628165). Interacts with SNCAIP (PubMed:11590439, PubMed:15728840). Binds to the C2A and C2B domains of SYT11 (PubMed:12925569). Interacts and regulates the turnover of SEPTIN5 (PubMed:11078524). Part of a complex, including STUB1, HSP70 and GPR37 (PubMed:12150907). The amount of STUB1 in the complex increases during ER stress (PubMed:12150907). STUB1 promotes the dissociation of HSP70 from PRKN and GPR37, thus facilitating PRKN-mediated GPR37 ubiquitination (PubMed:12150907). HSP70 transiently associates with unfolded GPR37 and inhibits the E3 activity of PRKN, whereas, STUB1 enhances the E3 activity of PRKN through promotion of dissociation of HSP70 from PRKN-GPR37 complexes (PubMed:12150907). Interacts with PSMD4 and PACRG (PubMed:12634850, PubMed:14532270). Interacts with LRRK2 (PubMed:16352719). Interacts with RANBP2 (PubMed:16332688). Interacts with SUMO1 but not SUMO2, which promotes nuclear localization and autoubiquitination (PubMed:16955485). Interacts (via first RING-type domain) with AIMP2 (via N-terminus) (PubMed:16135753). Interacts with PSMA7 and RNF41 (PubMed:15987638, PubMed:18541373). Interacts with PINK1 (PubMed:19966284, PubMed:20798600). Forms a complex with PINK1 and PARK7 (PubMed:19229105). Interacts with CHPF, the interaction with isoform 2 may facilitate PRKN transport into the mitochondria (PubMed:22082830). Interacts with MFN2 (phosphorylated), promotes PRKN localization in dysfunctional depolarized mitochondria (PubMed:23620051). Interacts with FBXO7; this promotes translocation to dysfunctional depolarized mitochondria (PubMed:23933751). Interacts with ZNF746 (PubMed:21376232). Interacts with heat shock protein 70 family members, including HSPA1L, HSPA1A and HSPA8; interaction HSPA1L promotes translocation to damaged mitochondria (PubMed:24270810). Interacts with BAG4 and, to a lesser extent, BAG5; interaction with BAG4 inhibits translocation to damaged mitochondria (PubMed:24270810). Forms a complex with PRKN and PARK7 (PubMed:19229105). Interacts with AMBRA1 (By similarity)","family":"Belongs to the RBR family. Parkin subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10888878","10973942","11431533","11439185","11590439","12150907","12628165","12719539","15105460","15728840","16135753","17846173","18541373","18957282","19029340","19229105","19801972","19966284","20889974","21376232","21532592","21753002","22082830","22396657","23620051","23685073","23754282","23933751","24660806","24751536","24784582","24896179","25474007","25527291","25621951","27534820","29311685","32047033","33499712"],"location":"Cytoplasm, cytosol；Nucleus；Endoplasmic reticulum；Mitochondrion；Mitochondrion outer membrane；Cell projection, neuron projection；Postsynaptic density；Presynapse","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"Parkin；RBR型E3，蛋白稳态及线粒体质量控制。","function_evidence":"含实验支持条目；ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；激酶/磷酸化信号；免疫/炎症/细胞死亡；线粒体/代谢；黏附/受体/细胞表面"},"PRKRA":{"hgnc":"HGNC:9438","symbol":"PRKRA","accessions":["O75569"],"name":"Interferon-inducible double-stranded RNA-dependent protein kinase activator A","length":"313","function":"Activates EIF2AK2/PKR in the absence of double-stranded RNA (dsRNA), leading to phosphorylation of EIF2S1/EFI2-alpha and inhibition of translation and induction of apoptosis. Required for siRNA production by DICER1 and for subsequent siRNA-mediated post-transcriptional gene silencing. Does not seem to be required for processing of pre-miRNA to miRNA by DICER1. Promotes UBC9-p53/TP53 association and sumoylation and phosphorylation of p53/TP53 at 'Lys-386' at 'Ser-392' respectively and enhances its activity in a EIF2AK2/PKR-dependent manner (By similarity). May function as regulator of gastric epithelial differentiation (By similarity)","subunit":"Homodimer. Interacts with EIF2AK2/PKR through its DRBM domains. Interacts with DICER1, AGO2 and TARBP2. Also able to interact with dsRNA. Interacts with UBC9 (By similarity). Forms a complex with UBC9 and p53/TP53 (By similarity). Interacts with DUS2L (via DRBM domain). Interacts with RIGI\n(Microbial infection) Interacts with ebolavirus protein VP35; this interaction inhibits the interaction between RIGI and PRKRA. In addition, this interaction disrupts the interaction between VP35 and the viral polymerase L. So the VP35-PRKRA interaction plays a critical role in determining the outcome of ebolavirus infection (PubMed:23870315). The interaction PRKRA-VP35 also prevents PRKRA binding to DICER1 and thus allows the virus to counteract host RNA silencing (PubMed:21228243)\n(Microbial infection) Interacts with human herpesvirus 8 protein MTA/ORF57; this interaction inhibits stress granule formation","family":"Belongs to the PRKRA family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10336432","11238927","16424907","16982605","17452327","9687506"],"location":"Cytoplasm, perinuclear region；Cytoplasm","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；激酶/磷酸化信号；翻译/核糖体；免疫/炎症/细胞死亡；发育/分化；注释原文：Activates EIF2AK2/PKR in the absence of double-stranded RNA (dsRNA), leading to phosphorylation of EIF2S1/EFI2-alpha and inhibition of translation and induction of apoptosis.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；激酶/磷酸化信号；翻译/核糖体；免疫/炎症/细胞死亡；发育/分化"},"PRMT1":{"hgnc":"HGNC:5187","symbol":"PRMT1","accessions":["Q99873"],"name":"Protein arginine N-methyltransferase 1","length":"371","function":"Arginine methyltransferase that methylates (mono and asymmetric dimethylation) the guanidino nitrogens of arginyl residues present in proteins such as ESR1, histone H2, H3 and H4, FMR1, ILF3, HNRNPA1, HNRNPD, NFATC2IP, SUPT5H, TAF15, EWS, HABP4, SERBP1, RBM15, FOXO1, CHTOP, MAP3K5/ASK1, MICU1 and NPRL2 (PubMed:10749851, PubMed:15741314, PubMed:16879614, PubMed:18951090, PubMed:22095282, PubMed:25284789, PubMed:26575292, PubMed:26876602, PubMed:27642082, PubMed:30765518, PubMed:31257072, PubMed:38006878). Constitutes the main enzyme that mediates monomethylation and asymmetric dimethylation of histone H4 'Arg-3' (H4R3me1 and H4R3me2a, respectively), a specific tag for epigenetic transcriptional activation. May be involved in the regulation of TAF15 transcriptional activity, act as an activator of estrogen receptor (ER)-mediated transactivation, play a key role in neurite outgrowth and act as a negative regulator of megakaryocytic differentiation, by modulating p38 MAPK pathway. Methylates RBM15, promoting ubiquitination and degradation of RBM15 (PubMed:26575292). Methylates MRE11 and TP53BP1, promoting the DNA damage response (PubMed:15741314, PubMed:16294045, PubMed:29651020). Methylates FOXO1 and retains it in the nucleus increasing its transcriptional activity (PubMed:18951090). Methylates CHTOP and this methylation is critical for its 5-hydroxymethylcytosine (5hmC)-binding activity (PubMed:25284789). Methylates MAP3K5/ASK1 at 'Arg-78' and 'Arg-80' which promotes association of MAP3K5 with thioredoxin and negatively regulates MAP3K5 association with TRAF2, inhibiting MAP3K5 stimulation and MAP3K5-induced activation of JNK (PubMed:22095282). Methylates H4R3 in genes involved in glioblastomagenesis in a CHTOP- and/or TET1-dependent manner (PubMed:25284789). Plays a role in regulating alternative splicing in the heart (By similarity). Methylates NPRL2 at 'Arg-78' leading to inhibition of its GTPase activator activity and then the GATOR1 complex and consequently inducing timely mTORC1 activation under methionine-sufficient conditions (PubMed:38006878). Methylates the C-terminus of DSP, promoting its phosphorylation by GSK3B and subsequent recruitment to desmosome cell-cell junctions (PubMed:25733715)","subunit":"Homodimer (PubMed:16879614, PubMed:26876602). Homooctamer; individual homodimers associates to form a homooctamer (PubMed:26876602). Individual homodimers can associate to form a homohexamer. Heterodimer with PRMT8. Interacts with BTG1, BTG2, NFATC2IP and IFNAR1 (By similarity). Interacts with and methylates CHTOP, thereby enabling the interaction of CHTOP with the 5FMC complex (PubMed:25284789). Interacts with ILF3 and SUPT5H. Interacts with and methylates FOXO1, leading to the nuclear retention of FOXO1 and the stimulation of FOXO1 transcriptional activity. Methylation of FOXO1 is increased upon oxidative stress. Interacts with and probably methylates ATXN2L (PubMed:25748791). Component of the methylosome, a 20S complex containing at least CLNS1A/pICln, PRMT5/SKB1, WDR77/MEP50, PRMT1 and ERH (PubMed:25284789). Interacts with DHX9 (via RGG region) (PubMed:15084609). Interacts (via N-terminus) with HABP4 (PubMed:16879614). Interacts with MAP3K5/ASK1; the interaction results in MAP3K5 methylation by PRMT1 which inhibits MAP3K5 activation (PubMed:22095282). Interacts with TRIM48; the interaction results in ubiquitination of PRMT1 by TRIM48, leading to PRMT1 proteasomal degradation and activation of MAP3K5 (PubMed:29186683). Interacts with GATOR1 complex; this interaction is S-adenosyl-L-methionine (SAM) dependent and is perturbated by SAMTOR in a SAM-sensitive manner (PubMed:38006878). Interacts with GFI1; promoting recognition and binding of MRE11 and TP53BP1 substrates by PRMT1 (PubMed:29651020)","family":"Belongs to the class I-like SAM-binding methyltransferase superfamily. Protein arginine N-methyltransferase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10749851","11387442","11448779","12718890","15741314","16294045","16879614","18320585","18657504","18773938","19124016","20442406","22095282","25284789","25733715","26575292","26876602","27642082","28040436","29651020","30765518","31257072","38006878"],"location":"Nucleus；Nucleus, nucleoplasm；Cytoplasm；Cytoplasm, cytosol；Lysosome membrane","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；黏附/受体/细胞表面；发育/分化；注释原文：Arginine methyltransferase that methylates (mono and asymmetric dimethylation) the guanidino nitrogens of arginyl residues present in proteins such as ESR1, histone H2, H3 and H4, FMR1, ILF3, HNRNPA1, HNRNPD, NFATC2IP, SUPT5H, TAF15, EWS, HABP4, SERBP1, RBM15, FOXO1, CHTOP, MAP3K5/ASK1, MICU1 and NPRL2 (PubMed:10749851, PubMed:15741314, PubMed:16879614, PubMed:18951090, PubMed:22095282, PubMed:25284789, PubMed:26575292, PubMed:26876602, PubMed:27642082, PubMed:30765518, PubMed:31257072, PubMed:38006878).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；激酶/磷酸化信号；黏附/受体/细胞表面；发育/分化"},"PRMT2":{"hgnc":"HGNC:5186","symbol":"PRMT2","accessions":["P55345"],"name":"Protein arginine N-methyltransferase 2","length":"433","function":"Arginine methyltransferase that methylates the guanidino nitrogens of arginyl residues in proteins such as STAT3, FBL, histone H4 (PubMed:19405910). Acts as a coactivator (with NCOA2) of the androgen receptor (AR)-mediated transactivation (PubMed:17587566). Acts as a coactivator (with estrogen) of estrogen receptor (ER)-mediated transactivation (PubMed:12039952). Enhances PGR, PPARG, RARA-mediated transactivation (PubMed:12039952). May inhibit NF-kappa-B transcription and promote apoptosis (PubMed:16648481). Represses E2F1 transcriptional activity (in a RB1-dependent manner) (By similarity). May be involved in growth regulation (By similarity). Involved in PRMT2IP-mediated inhibition of the microglial inflammatory responses through suppression of NF-kappa-B signaling, thereby reducing the production of pro-inflammatory cytokines (PubMed:38892217)","subunit":"Self-associates. Interacts with RB1 and E2F1 (By similarity). Interacts with NCOA6 coactivator. Interacts (via SH3 domain) with PRMT8. Interacts with AR. Interacts with NFKBIA. Interacts with ESR1, ESR2, PGR, PPARG, RARA, RXRA and THRB. Interacts with HNRNPUL1. Interacts with PRMT2IP (PubMed:38892217)","family":"Belongs to the class I-like SAM-binding methyltransferase superfamily. Protein arginine N-methyltransferase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12039952","16648481","17587566","19405910","38892217"],"location":"Cytoplasm；Nucleus；Nucleus, nucleolus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面；注释原文：Arginine methyltransferase that methylates the guanidino nitrogens of arginyl residues in proteins such as STAT3, FBL, histone H4 (PubMed:19405910).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"染色质/转录调控；免疫/炎症/细胞死亡；黏附/受体/细胞表面"},"PRMT2IP":{"hgnc":"HGNC:24497","symbol":"PRMT2IP","accessions":["Q6ZRI6"],"name":"PRMT2-interacting protein","length":"1047","function":"Negatively regulates microglial inflammatory responses (PubMed:38892217). Inhibits NF-kappa-B signaling by interacting with PRMT2, thereby reducing the production of pro-inflammatory cytokines, maintaining a steady-state in microglia and limiting excessive inflammation (PubMed:38892217)","subunit":"Interacts with PRMT2","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["38892217"],"location":"Cytoplasm；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"免疫/炎症/细胞死亡；注释原文：Negatively regulates microglial inflammatory responses (PubMed:38892217).","function_evidence":"含实验支持条目；ECO:0000269","categories":"免疫/炎症/细胞死亡"},"PRMT3":{"hgnc":"HGNC:30163","symbol":"PRMT3","accessions":["O60678"],"name":"Protein arginine N-methyltransferase 3","length":"531","function":"Protein-arginine N-methyltransferase that catalyzes both the monomethylation and asymmetric dimethylation of the guanidino nitrogens of arginine residues in target proteins, and therefore falls into the group of type I methyltransferases (PubMed:22795084, PubMed:23445220, PubMed:25728001, PubMed:31378783, PubMed:33495566, PubMed:39513743). Catalyzes the asymmetric arginine dimethylation at multiple sites in the Arg/Gly-rich region of small ribosomal subunit protein uS5/RPS2 (PubMed:22795084). Also appears to methylate other ribosomal proteins (By similarity). May regulate retinoic acid synthesis and signaling by inhibiting ALDH1A1 retinal dehydrogenase activity (PubMed:33495566). Contributes to methylation of histone H4 'Arg-3', a specific tag for epigenetic transcriptional activation (PubMed:25728001, PubMed:31378783, PubMed:39513743). Mediates asymmetric arginine dimethylation of histone H4 'Arg-3' (H4R3me2a) in the promoter region of miRNA miR-3648, to promote its transcription and osteogenesis (PubMed:31378783)","subunit":"Monomer and homodimer (By similarity). Interacts with EPB41L3 (via FERM domain); the interaction is direct and inhibits the protein-arginine N-methyltransferase activity of PRMT3 (PubMed:15334060). Interacts with the 40S ribosomal protein RPS2/uS5 (PubMed:21059412, PubMed:27697862, PubMed:30530495). Interacts with ALDH1A1; the interaction is direct, inhibits ALDH1A1 aldehyde dehydrogenase activity and is independent of the methyltransferase activity of PRMT3 (PubMed:33495566). Interacts (via zinc-finger) with ZNF200 (via C-terminus); the interaction is direct and required to localize PRMT3 to the nucleus and inhibit its proteasomal degradation (PubMed:39513743)","family":"Belongs to the class I-like SAM-binding methyltransferase superfamily. Protein arginine N-methyltransferase family","domains":[],"function_pmids":["22795084","23445220","25728001","31378783","33495566","39513743"],"location":"Cytoplasm, cytosol; Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Protein-arginine N-methyltransferase that catalyzes both the monomethylation and asymmetric dimethylation of the guanidino nitrogens of arginine residues in target proteins, and therefore falls into the group of type I methyltransferases (PubMed:22795084, PubMed:23445220, PubMed:25728001, PubMed:31378783, PubMed:33495566, PubMed:39513743). Catalyzes the asymmetric arginine dimethylation at multiple sites in the Arg/Gly-rich region of small ribosomal subunit protein uS5/RPS2 (PubMed:22795084). Also appears to methylate other ribosomal proteins (By similarity). May regulate retinoic acid synthesis and signaling by inhibiting ALDH1A1 retinal dehydrogenase activity (PubMed:33495566). Contributes to methylation of histone H4 'Arg-3', a specific tag for epigenetic transcriptional activation (PubMed:25728001, PubMed:31378783, PubMed:39513743). Mediates asymmetric arginine dimethylation of histone H4 'Arg-3' (H4R3me2a) in the promoter region of miRNA miR-3648, to promote its transcription and osteogenesis (PubMed:31378783)"},"PRMT5":{"hgnc":"HGNC:10894","symbol":"PRMT5","accessions":["O14744"],"name":"Protein arginine N-methyltransferase 5","length":"637","function":"Arginine methyltransferase that can both catalyze the formation of omega-N monomethylarginine (MMA) and symmetrical dimethylarginine (sDMA), with a preference for the formation of MMA (PubMed:10531356, PubMed:11152681, PubMed:11747828, PubMed:12411503, PubMed:15737618, PubMed:17709427, PubMed:20159986, PubMed:20810653, PubMed:21081503, PubMed:21258366, PubMed:21917714, PubMed:22269951, PubMed:33762328). Specifically mediates the symmetrical dimethylation of arginine residues in the small nuclear ribonucleoproteins Sm D1 (SNRPD1) and Sm D3 (SNRPD3); such methylation being required for the assembly and biogenesis of snRNP core particles (PubMed:11747828, PubMed:12411503, PubMed:17709427). Methylates SUPT5H and may regulate its transcriptional elongation properties (PubMed:12718890). May methylate the N-terminal region of MBD2 (PubMed:16428440). Mono- and dimethylates arginine residues of myelin basic protein (MBP) in vitro. May play a role in cytokine-activated transduction pathways. Negatively regulates cyclin E1 promoter activity and cellular proliferation. Methylates histone H2A and H4 'Arg-3' during germ cell development (By similarity). Methylates histone H3 'Arg-8', which may repress transcription (By similarity). Methylates the Piwi proteins (PIWIL1, PIWIL2 and PIWIL4), methylation of Piwi proteins being required for the interaction with Tudor domain-containing proteins and subsequent localization to the meiotic nuage (By similarity). Methylates RPS10 (PubMed:20159986). Attenuates EGF signaling through the MAPK1/MAPK3 pathway acting at 2 levels. First, monomethylates EGFR; this enhances EGFR 'Tyr-1197' phosphorylation and PTPN6 recruitment, eventually leading to reduced SOS1 phosphorylation (PubMed:21258366, PubMed:21917714). Second, methylates RAF1 and probably BRAF, hence destabilizing these 2 signaling proteins and reducing their catalytic activity (PubMed:21917714). Required for induction of E-selectin and VCAM-1, on the endothelial cells surface at sites of inflammation. Methylates HOXA9 (PubMed:22269951). Methylates and regulates SRGAP2 which is involved in cell migration and differentiation (PubMed:20810653). Acts as a transcriptional corepressor in CRY1-mediated repression of the core circadian component PER1 by regulating the H4R3 dimethylation at the PER1 promoter (By similarity). Methylates GM130/GOLGA2, regulating Golgi ribbon formation (PubMed:20421892). Methylates H4R3 in genes involved in glioblastomagenesis in a CHTOP- and/or TET1-dependent manner (PubMed:25284789). Symmetrically methylates POLR2A, a modification that allows the recruitment to POLR2A of proteins including SMN1/SMN2 and SETX. This is required for resolving RNA-DNA hybrids created by RNA polymerase II, that form R-loop in transcription terminal regions, an important step in proper transcription termination (PubMed:26700805). Along with LYAR, binds the promoter of gamma-globin HBG1/HBG2 and represses its expression (PubMed:25092918). Symmetrically methylates NCL (PubMed:21081503). Methylates p53/TP53; methylation might possibly affect p53/TP53 target gene specificity (PubMed:19011621). Involved in spliceosome maturation and mRNA splicing in prophase I spermatocytes through the catalysis of the symmetrical arginine dimethylation of SNRPB (small nuclear ribonucleoprotein-associated protein) and the interaction with tudor domain-containing protein TDRD6 (By similarity). Acts as a negative regulator of cGAS-STING signaling by mediating methylation of CGAS, preventing DNA-binding ability of CGAS (PubMed:33762328)","subunit":"Forms, at least, homodimers and homotetramers (PubMed:11152681). Component of the methylosome complex, composed of PRMT5, WDR77 and CLNS1A (PubMed:21081503, PubMed:23071334, PubMed:33376131). Found in a complex composed of PRMT5, WDR77 and RIOK1 (PubMed:21081503). RIOK1 and CLNS1A associate with PRMT5 in a mutually exclusive fashion, which allows the recruitment of distinct methylation substrates, such as nucleolin/NCL and Sm proteins, respectively (PubMed:21081503). Interacts with PRDM1 (By similarity). Identified in a complex composed of methylosome and PRMT1 and ERH (PubMed:25284789). Interacts with EGFR; methylates EGFR and stimulates EGFR-mediated ERK activation. Interacts with HOXA9. Interacts with SRGAP2. Found in a complex with COPRS, RUNX1 and CBFB. Interacts with CHTOP; the interaction symmetrically methylates CHTOP, but seems to require the presence of PRMT1 (PubMed:25284789). Interacts with EPB41L3; this modulates methylation of target proteins. Component of a high molecular weight E2F-pocket protein complex, CERC (cyclin E1 repressor complex). Associates with SWI/SNF remodeling complexes containing SMARCA2 and SMARCA4. Interacts with JAK2, SSTR1, SUPT5H, BRAF and with active RAF1. Interacts with LSM11, PRMT7 and SNRPD3 (PubMed:16087681, PubMed:17709427). Interacts with COPRS; promoting its recruitment on histone H4. Interacts with CLNS1A/pICln (PubMed:21081503, PubMed:9556550). Identified in a complex with CLNS1A/pICln and Sm proteins. Interacts with RPS10 (PubMed:20159986). Interacts with WDR77. Interacts with IWS1. Interacts with CRY1. Interacts with POLR2A (PubMed:26700805). Interacts with SMN1/SMN2 (PubMed:26700805). Interacts with LYAR; this interaction is direct (PubMed:25092918). Interacts with TTC5/STRAP; this interaction is DNA damage-dependent and promotes PRMT5 interaction with p53/TP53 (PubMed:19011621). Interacts with p53/TP53 in response to DNA damage; the interaction is TTC5/STRAP dependent (PubMed:19011621). Interacts with FAM47E; the interaction is direct, promotes PRMT5 localization to chromatin, and does not disrupt its association with WDR77 or STUB1 (PubMed:33376131). Interacts with TDRD6 (By similarity). Interacts with STUB1 (PubMed:33376131). Interacts with MBD2 (PubMed:16428440). Does not interact with MBD3 (PubMed:16428440)","family":"Belongs to the class I-like SAM-binding methyltransferase superfamily. Protein arginine N-methyltransferase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10531356","11152681","11747828","12411503","12718890","15737618","16428440","17709427","19011621","20159986","20421892","20810653","21081503","21258366","21917714","22269951","25092918","25284789","26700805","33762328"],"location":"Cytoplasm；Nucleus；Chromosome；Golgi apparatus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"对称性精氨酸甲基转移酶；影响染色质、剪接/RNP及生殖发育。","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；激酶/磷酸化信号；膜运输/高尔基/内吞；免疫/炎症/细胞死亡；发育/分化"},"PRMT6":{"hgnc":"HGNC:18241","symbol":"PRMT6","accessions":["Q96LA8"],"name":"Protein arginine N-methyltransferase 6","length":"375","function":"Arginine methyltransferase that can catalyze the formation of both omega-N monomethylarginine (MMA) and asymmetrical dimethylarginine (aDMA), with a strong preference for the formation of aDMA (PubMed:17898714, PubMed:18077460, PubMed:18079182, PubMed:19405910, PubMed:30420520). Preferentially methylates arginyl residues present in a glycine and arginine-rich domain and displays preference for monomethylated substrates (PubMed:17898714, PubMed:18077460, PubMed:18079182, PubMed:19405910). Specifically mediates the asymmetric dimethylation of histone H3 'Arg-2' to form H3R2me2a (PubMed:17898714, PubMed:18077460, PubMed:18079182). H3R2me2a represents a specific tag for epigenetic transcriptional repression and is mutually exclusive with methylation on histone H3 'Lys-4' (H3K4me2 and H3K4me3) (PubMed:17898714, PubMed:18077460). Acts as a transcriptional repressor of various genes such as HOXA2, THBS1 and TP53 (PubMed:19509293). Repression of TP53 blocks cellular senescence (By similarity). Also methylates histone H2A and H4 'Arg-3' (H2AR3me and H4R3me, respectively). Acts as a regulator of DNA base excision during DNA repair by mediating the methylation of DNA polymerase beta (POLB), leading to the stimulation of its polymerase activity by enhancing DNA binding and processivity (PubMed:16600869). Methylates HMGA1 (PubMed:16157300, PubMed:16159886). Regulates alternative splicing events. Acts as a transcriptional coactivator of a number of steroid hormone receptors including ESR1, ESR2, PGR and NR3C1. Promotes fasting-induced transcriptional activation of the gluconeogenic program through methylation of the CRTC2 transcription coactivator (By similarity). May play a role in innate immunity against HIV-1 in case of infection by methylating and impairing the function of various HIV-1 proteins such as Tat, Rev and Nucleocapsid protein p7 (NC) (PubMed:17267505). Methylates GPS2, protecting GPS2 from ubiquitination and degradation (By similarity). Methylates SIRT7, inhibiting SIRT7 histone deacetylase activity and promoting mitochondria biogenesis (PubMed:30420520)","subunit":"Interacts with EPB41L3 and NCOA1. Interacts with FBXO24 (PubMed:32828318)\n(Microbial infection) Interacts with (and methylates) HIV-1 Tat, Rev and Nucleocapsid protein p7 (NC)\n(Microbial infection) Interacts with human cytomegalovirus protein UL69","family":"Belongs to the class I-like SAM-binding methyltransferase superfamily. Protein arginine N-methyltransferase family. PRMT6 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11724789","16157300","16159886","16600869","17267505","17898714","18077460","18079182","19405910","19509293","20047962","30420520"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；线粒体/代谢；黏附/受体/细胞表面；注释原文：Arginine methyltransferase that can catalyze the formation of both omega-N monomethylarginine (MMA) and asymmetrical dimethylarginine (aDMA), with a strong preference for the formation of aDMA (PubMed:17898714, PubMed:18077460, PubMed:18079182, PubMed:19405910, PubMed:30420520).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"泛素化/蛋白稳态；染色质/转录调控；DNA修复/复制；线粒体/代谢；黏附/受体/细胞表面"},"PRMT7":{"hgnc":"HGNC:25557","symbol":"PRMT7","accessions":["Q9NVM4"],"name":"Protein arginine N-methyltransferase 7","length":"692","function":"Arginine methyltransferase that can both catalyze the formation of omega-N monomethylarginine (MMA) and symmetrical dimethylarginine (sDMA), with a preference for the formation of MMA. Specifically mediates the symmetrical dimethylation of arginine residues in the small nuclear ribonucleoproteins Sm D1 (SNRPD1) and Sm D3 (SNRPD3); such methylation being required for the assembly and biogenesis of snRNP core particles. Specifically mediates the symmetric dimethylation of histone H4 'Arg-3' to form H4R3me2s. Plays a role in gene imprinting by being recruited by CTCFL at the H19 imprinted control region (ICR) and methylating histone H4 to form H4R3me2s, possibly leading to recruit DNA methyltransferases at these sites. May also play a role in embryonic stem cell (ESC) pluripotency. Also able to mediate the arginine methylation of histone H2A and myelin basic protein (MBP) in vitro; the relevance of such results is however unclear in vivo","subunit":"Homodimer and heterodimer (By similarity). Interacts with CTCFL (By similarity). Interacts with PRMT5 and SNRPD3","family":"Belongs to the class I-like SAM-binding methyltransferase superfamily. Protein arginine N-methyltransferase family. PRMT7 subfamily","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["15044439","15494416","17709427","19110445"],"location":"Cytoplasm, cytosol；Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；注释原文：Arginine methyltransferase that can both catalyze the formation of omega-N monomethylarginine (MMA) and symmetrical dimethylarginine (sDMA), with a preference for the formation of MMA.","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控"},"PROB1":{"hgnc":"HGNC:41906","symbol":"PROB1","accessions":["E7EW31"],"name":"Proline-rich basic protein 1","length":"1015","function":"未获得FUNCTION段；不等于没有已发表研究","subunit":"无可用SUBUNIT段","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"本次数据库无可用FUNCTION；只可据蛋白名称/结构域提出方向，不据此称全新功能。","function_evidence":"本次数据库无FUNCTION段；不等于无研究/无功能","categories":"未归类"},"PROP1":{"hgnc":"HGNC:9455","symbol":"PROP1","accessions":["O75360"],"name":"Homeobox protein prophet of Pit-1","length":"226","function":"Possibly involved in the ontogenesis of pituitary gonadotropes, as well as somatotropes, lactotropes and caudomedial thyrotropes","subunit":"无可用SUBUNIT段","family":"Belongs to the paired homeobox family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"；注释原文：Possibly involved in the ontogenesis of pituitary gonadotropes, as well as somatotropes, lactotropes and caudomedial thyrotropes","function_evidence":"数据库整理/推断；按原文限定；","categories":"未归类"},"PRORP":{"hgnc":"HGNC:19958","symbol":"PRORP","accessions":["O15091"],"name":"Mitochondrial ribonuclease P catalytic subunit","length":"583","function":"Catalytic ribonuclease component of mitochondrial ribonuclease P, a complex composed of TRMT10C/MRPP1, HSD17B10/MRPP2 and PRORP/MRPP3, which cleaves tRNA molecules in their 5'-ends (PubMed:18984158, PubMed:25953853, PubMed:34715011). The presence of TRMT10C/MRPP1, HSD17B10/MRPP2 is required to catalyze tRNA molecules in their 5'-ends (PubMed:25953853)","subunit":"Catalytic component of mitochondrial ribonuclease P, a complex composed of TRMT10C/MRPP1, HSD17B10/MRPP2 and PRORP/MRPP3 (PubMed:18984158)","family":"Belongs to the PPR family. P subfamily","domains":[],"function_pmids":["18984158","25953853","34715011"],"location":"Mitochondrion","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Catalytic ribonuclease component of mitochondrial ribonuclease P, a complex composed of TRMT10C/MRPP1, HSD17B10/MRPP2 and PRORP/MRPP3, which cleaves tRNA molecules in their 5'-ends (PubMed:18984158, PubMed:25953853, PubMed:34715011). The presence of TRMT10C/MRPP1, HSD17B10/MRPP2 is required to catalyze tRNA molecules in their 5'-ends (PubMed:25953853)"},"PRP4K":{"hgnc":"HGNC:17346","symbol":"PRP4K","accessions":["Q13523"],"name":"Serine/threonine-protein kinase PRP4 homolog","length":"1007","function":"Serine/threonine kinase involved in spliceosomal assembly as well as mitosis and signaling regulation (PubMed:10799319, PubMed:12077342, PubMed:17513757, PubMed:17998396). Connects chromatin mediated regulation of transcription and pre-mRNA splicing (PubMed:12077342). During spliceosomal assembly, interacts with and phosphorylates PRPF6 and PRPF31, components of the U4/U6-U5 tri-small nuclear ribonucleoprotein (snRNP), to facilitate the formation of the spliceosome B complex. Plays a role in regulating transcription and the spindle assembly checkpoint (SAC) (PubMed:20118938). Associates with U5 snRNP and NCOR1 deacetylase complexes which may allow a coordination of pre-mRNA splicing with chromatin remodeling events involved in transcriptional regulation (PubMed:12077342). Associates and probably phosphorylates SMARCA4 and NCOR1 (PubMed:12077342). Phosphorylates SRSF1 (PubMed:11418604). Associates with kinetochores during mitosis and is necessary for recruitment and maintenance of the checkpoint proteins such as MAD1L1 and MAD12L1 at the kinetochores (PubMed:17998396). Phosphorylates and regulates the activity of the transcription factors such as ELK1 and KLF13 (PubMed:10799319, PubMed:17513757). Phosphorylates nuclear YAP1 and WWTR1/TAZ which induces nuclear exclusion and regulates Hippo signaling pathway, involved in tissue growth control (PubMed:29695716)","subunit":"Interacts with CLK1 C-terminus (PubMed:11418604). Associates with the U5 snRNP and NCOR1 deacetylase complexes (PubMed:12077342). Identified in the spliceosome C complex (PubMed:11991638)","family":"Belongs to the protein kinase superfamily. CMGC Ser/Thr protein kinase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10799319","11418604","12077342","17513757","17998396","20118938","29695716"],"location":"Nucleus；Chromosome, centromere, kinetochore","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号；注释原文：Serine/threonine kinase involved in spliceosomal assembly as well as mitosis and signaling regulation (PubMed:10799319, PubMed:12077342, PubMed:17513757, PubMed:17998396).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接；染色质/转录调控；细胞周期/分裂；激酶/磷酸化信号"},"PRPF18":{"hgnc":"HGNC:17351","symbol":"PRPF18","accessions":["Q99633"],"name":"Pre-mRNA-splicing factor 18","length":"342","function":"Participates in the second step of pre-mRNA splicing","subunit":"Heterodimer with PPIH. Interacts with PRPF4 and with the spliceosome. Part of a complex containing U4/U6 snRNPs","family":"Belongs to the PRP18 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["9000057"],"location":"Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Participates in the second step of pre-mRNA splicing","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"PRPF19":{"hgnc":"HGNC:17896","symbol":"PRPF19","accessions":["Q9UMS4"],"name":"Pre-mRNA-processing factor 19","length":"504","function":"Ubiquitin-protein ligase which is a core component of several complexes mainly involved pre-mRNA splicing and DNA repair. Required for pre-mRNA splicing as component of the spliceosome (PubMed:28076346, PubMed:28502770, PubMed:29301961, PubMed:29360106, PubMed:30705154). Core component of the PRP19C/Prp19 complex/NTC/Nineteen complex which is part of the spliceosome and participates in its assembly, its remodeling and is required for its activity. During assembly of the spliceosome, mediates 'Lys-63'-linked polyubiquitination of the U4 spliceosomal protein PRPF3. Ubiquitination of PRPF3 allows its recognition by the U5 component PRPF8 and stabilizes the U4/U5/U6 tri-snRNP spliceosomal complex (PubMed:20595234). Recruited to RNA polymerase II C-terminal domain (CTD) and the pre-mRNA, it may also couple the transcriptional and spliceosomal machineries (PubMed:21536736). The XAB2 complex, which contains PRPF19, is also involved in pre-mRNA splicing, transcription and transcription-coupled repair (PubMed:17981804). Beside its role in pre-mRNA splicing PRPF19, as part of the PRP19-CDC5L complex, plays a role in the DNA damage response/DDR. It is recruited to the sites of DNA damage by the RPA complex where PRPF19 directly ubiquitinates RPA1 and RPA2. 'Lys-63'-linked polyubiquitination of the RPA complex allows the recruitment of the ATR-ATRIP complex and the activation of ATR, a master regulator of the DNA damage response (PubMed:24332808). May also play a role in DNA double-strand break (DSB) repair by recruiting the repair factor SETMAR to altered DNA (PubMed:18263876). As part of the PSO4 complex may also be involved in the DNA interstrand cross-links/ICLs repair process (PubMed:16223718). In addition, may also mediate 'Lys-48'-linked polyubiquitination of substrates and play a role in proteasomal degradation (PubMed:11435423). May play a role in the biogenesis of lipid droplets (By similarity). May play a role in neural differentiation possibly through its function as part of the spliceosome (By similarity)","subunit":"Homotetramer. Component of activated, catalytic and post-catalytic spliceosomes (PubMed:28076346, PubMed:28502770, PubMed:29301961, PubMed:29360106, PubMed:30705154). Component of the Prp19 complex/PRP19C/Nineteen complex/NTC and related complexes described as PRP19-CDC5L splicing complex and PSO4 complex. A homotetramer of PRPF19, CDC5L, PLRG1 and BCAS2 constitute the core of those complexes. The interaction with CDC5L, PLRG1 and BCAS2 is direct within this core complex. At least three less stably associated proteins CTNNBL1, CWC15 and HSPA8 are found in the Prp19 complex. The Prp19 complex associates with the spliceosome during its assembly and remodeling recruiting additional proteins. Component of the XAB2 complex, a multimeric protein complex composed of XAB2, PRPF19, AQR, ZNF830, ISY1, and PPIE. Interacts with CWC22 and EIF4A3 in an RNA-independent manner. Interacts with RPA1 and RPA2; the PRP19-CDC5L complex is recruited to the sites of DNA repair where it interacts with the replication protein A complex (RPA). Interacts with SETMAR; required for SETMAR recruitment to site of DNA damage. Interacts with U2AF2; the interaction is direct and recruits the Prp19 complex to RNA polymerase II C-terminal domain (CTD) and the pre-mRNA. Interacts with PRPF3. Interacts with APEX1, DNTT and PSMB4. Interacts with PSMC5 (By similarity). Interacts with KNSTRN (PubMed:24718257). Interacts (via N-terminus) with CDC5L (By similarity). Interacts with KHDC4 (PubMed:19641227). Interacts with USB1 (PubMed:23022480). Interacts with DDX41 (PubMed:36229594)","family":"Belongs to the WD repeat PRP19 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11082287","11435423","12960389","15660529","16223718","16332694","16388800","17349974","17981804","18263876","20595234","21536736","24332808","28076346","28502770","29301961","29360106","30705154"],"location":"Nucleus；Nucleus, nucleoplasm；Cytoplasm, cytoskeleton, spindle；Cytoplasm；Lipid droplet","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"泛素化/蛋白稳态；RNA加工/剪接；染色质/转录调控；DNA修复/复制；线粒体/代谢；发育/分化；注释原文：Ubiquitin-protein ligase which is a core component of several complexes mainly involved pre-mRNA splicing and DNA repair.","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269,ECO:0000303","categories":"泛素化/蛋白稳态；RNA加工/剪接；染色质/转录调控；DNA修复/复制；线粒体/代谢；发育/分化"},"PRPF3":{"hgnc":"HGNC:17348","symbol":"PRPF3","accessions":["O43395"],"name":"U4/U6 small nuclear ribonucleoprotein Prp3","length":"683","function":"Plays a role in pre-mRNA splicing as component of the U4/U6-U5 tri-snRNP complex that is involved in spliceosome assembly, and as component of the precatalytic spliceosome (spliceosome B complex)","subunit":"Component of the precatalytic spliceosome (spliceosome B complex) (PubMed:28781166). Component of the U4/U6-U5 tri-snRNP complex, a building block of the precatalytic spliceosome (spliceosome B complex) (PubMed:17932117, PubMed:26912367, PubMed:28781166, PubMed:9328476, PubMed:9404889). The U4/U6-U5 tri-snRNP complex is composed of the U4, U6 and U5 snRNAs and at least PRPF3, PRPF4, PRPF6, PRPF8, PRPF31, SNRNP200, TXNL4A, SNRNP40, SNRPB, SNRPD1, SNRPD2, SNRPD3, SNRPE, SNRPF, SNRPG, DDX23, CD2BP2, PPIH, SNU13, EFTUD2, SART1 and USP39, plus LSM2, LSM3, LSM4, LSM5, LSM6, LSM7 and LSM8 (PubMed:16723661, PubMed:26912367). Interacts directly with PRPF4 (PubMed:17932117, PubMed:9328476, PubMed:9404889). Part of a heteromeric complex containing PPIH, PRPF3 and PRPF4 that is stable in the absence of RNA (PubMed:9404889). Interacts with SART3; the interaction is direct and recruits the deubiquitinase USP4 to PRPF3 (PubMed:15314151, PubMed:20595234). Interacts with PRPF19. Interacts ('Lys-63'-linked polyubiquitinated) with PRPF8 (via the MPN (JAB/Mov34) domain); may stabilize the U4/U6-U5 tri-snRNP complex (PubMed:20595234). Interacts with ERCC6 (PubMed:26030138)","family":"","domains":[],"function_pmids":["20595234","26912367","28781166"],"location":"Nucleus; Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Plays a role in pre-mRNA splicing as component of the U4/U6-U5 tri-snRNP complex that is involved in spliceosome assembly, and as component of the precatalytic spliceosome (spliceosome B complex)"},"PRPF31":{"hgnc":"HGNC:15446","symbol":"PRPF31","accessions":["Q8WWY3"],"name":"U4/U6 small nuclear ribonucleoprotein Prp31","length":"499","function":"Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11867543, PubMed:20118938, PubMed:28781166). Required for the assembly of the U4/U5/U6 tri-snRNP complex, one of the building blocks of the spliceosome (PubMed:11867543)","subunit":"Identified in the spliceosome B complex (PubMed:28781166). Component of the U4/U6-U5 tri-snRNP complex composed of the U4, U6 and U5 snRNAs and at least PRPF3, PRPF4, PRPF6, PRPF8, PRPF31, SNRNP200, TXNL4A, SNRNP40, DDX23, CD2BP2, PPIH, SNU13, EFTUD2, SART1 and USP39 (PubMed:11867543, PubMed:16723661, PubMed:26912367). Interacts with a complex formed by SNU13 and U4 snRNA, but not with SNU13 or U4 snRNA alone (PubMed:17412961, PubMed:21784869). The complex formed by SNU13 and PRPF31 also binds U4atac snRNA, a characteristic component of specific, less abundant spliceosomal complexes (PubMed:21784869). Interacts with PRPF6/U5 snRNP-associated 102 kDa protein (PubMed:11867543, PubMed:17412961, PubMed:26912367). Component of some MLL1/MLL complex, at least composed of the core components KMT2A/MLL1, ASH2L, HCFC1/HCF1, WDR5 and RBBP5, as well as the facultative components BACC1, CHD8, E2F6, HSP70, INO80C, KANSL1, LAS1L, MAX, MCRS1, MGA, KAT8/MOF, PELP1, PHF20, PRP31, RING2, RUVB1/TIP49A, RUVB2/TIP49B, SENP3, TAF1, TAF4, TAF6, TAF7, TAF9 and TEX10 (PubMed:15960975). Interacts (via its NLS) with CTNNBL1 (PubMed:21385873). Interacts with USH1G (PubMed:34023904)","family":"Belongs to the PRP31 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["11867543","20118938","28781166"],"location":"Nucleus；Nucleus speckle；Nucleus, Cajal body","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Involved in pre-mRNA splicing as component of the spliceosome (PubMed:11867543, PubMed:20118938, PubMed:28781166).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"PRPF38A":{"hgnc":"HGNC:25930","symbol":"PRPF38A","accessions":["Q8NAV1"],"name":"Pre-mRNA-splicing factor 38A","length":"312","function":"Involved in pre-mRNA splicing as a component of the spliceosome","subunit":"Component of the spliceosome B complex (PubMed:26673105, PubMed:28781166). Interacts (via N-terminal interaction domain) with ZMAT2 and MFAP1 (Probable) (PubMed:27773687)","family":"Belongs to the PRP38 family","domains":[],"function_pmids":["26673105","28781166"],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Involved in pre-mRNA splicing as a component of the spliceosome"},"PRPF39":{"hgnc":"HGNC:20314","symbol":"PRPF39","accessions":["Q86UA1"],"name":"Pre-mRNA-processing factor 39","length":"669","function":"Involved in pre-mRNA splicing","subunit":"无可用SUBUNIT段","family":"Belongs to the PRP39 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":[],"location":"Nucleus","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Involved in pre-mRNA splicing","function_evidence":"含同源推断，不能当该成员实测；ECO:0000250","categories":"RNA加工/剪接"},"PRPF4":{"hgnc":"HGNC:17349","symbol":"PRPF4","accessions":["O43172"],"name":"U4/U6 small nuclear ribonucleoprotein Prp4","length":"522","function":"Plays a role in pre-mRNA splicing as component of the U4/U6-U5 tri-snRNP complex that is involved in spliceosome assembly, and as component of the precatalytic spliceosome (spliceosome B complex)","subunit":"Component of the precatalytic spliceosome (spliceosome B complex) (PubMed:28781166). Component of the U4/U6-U5 tri-snRNP complex, a building block of the precatalytic spliceosome (spliceosome B complex) (PubMed:26912367, PubMed:28781166, PubMed:9257651, PubMed:9328476, PubMed:9404889). The U4/U6-U5 tri-snRNP complex is composed of the U4, U6 and U5 snRNAs and at least PRPF3, PRPF4, PRPF6, PRPF8, PRPF31, SNRNP200, TXNL4A, SNRNP40, SNRPB, SNRPD1, SNRPD2, SNRPD3, SNRPE, SNRPF, SNRPG, DDX23, CD2BP2, PPIH, SNU13, EFTUD2, SART1 and USP39, plus LSM2, LSM3, LSM4, LSM5, LSM6, LSM7 and LSM8 (PubMed:16723661, PubMed:26912367). Interacts directly with PRPF18, PPIH and PRPF3 (PubMed:12875835, PubMed:25383878, PubMed:9000057, PubMed:9328476, PubMed:9404889). Part of a heteromeric complex containing PPIH, PRPF3 and PRPF4 that is stable in the absence of RNA (PubMed:9404889). Interacts with ERCC6 (PubMed:26030138)","family":"","domains":[],"function_pmids":["25383878","28781166"],"location":"Nucleus; Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"project UniProt records20261017/18","brief":"Plays a role in pre-mRNA splicing as component of the U4/U6-U5 tri-snRNP complex that is involved in spliceosome assembly, and as component of the precatalytic spliceosome (spliceosome B complex)"},"PRPF40A":{"hgnc":"HGNC:16463","symbol":"PRPF40A","accessions":["O75400"],"name":"Pre-mRNA-processing factor 40 homolog A","length":"957","function":"Binds to WASL/N-WASP and suppresses its translocation from the nucleus to the cytoplasm, thereby inhibiting its cytoplasmic function (By similarity). Plays a role in the regulation of cell morphology and cytoskeletal organization. Required in the control of cell shape and migration. May play a role in cytokinesis. May be involved in pre-mRNA splicing","subunit":"Interacts with the N-terminus of HTT. Interacts with the phosphorylated C-terminal domain of POLR2A. Interacts with AKAP8L, SF1, SRPK1, ENAH, ATBF1 and MECP2 (By similarity). Interacts through the WW domains with formin proline-rich regions and with WASL/N-WASP (By similarity)","family":"Belongs to the PRPF40 family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["21834987"],"location":"Nucleus speckle；Nucleus matrix","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；细胞周期/分裂；细胞骨架/纤毛；注释原文：Binds to WASL/N-WASP and suppresses its translocation from the nucleus to the cytoplasm, thereby inhibiting its cytoplasmic function (By similarity).","function_evidence":"含实验支持条目；含同源推断，不能当该成员实测；ECO:0000250,ECO:0000269","categories":"RNA加工/剪接；细胞周期/分裂；细胞骨架/纤毛"},"PRPF6":{"hgnc":"HGNC:15860","symbol":"PRPF6","accessions":["O94906"],"name":"Pre-mRNA-processing factor 6","length":"941","function":"Involved in pre-mRNA splicing as component of the U4/U6-U5 tri-snRNP complex, one of the building blocks of the spliceosome (PubMed:20118938, PubMed:21549338, PubMed:28781166). Enhances dihydrotestosterone-induced transactivation activity of AR, as well as dexamethasone-induced transactivation activity of NR3C1, but does not affect estrogen-induced transactivation","subunit":"Identified in the spliceosome B complex (PubMed:28781166). Identified in the spliceosome C complex (PubMed:11991638). Associates with the U5 snRNP particle (PubMed:10788320). Component of the U4/U6-U5 tri-snRNP complex composed of the U4, U6 and U5 snRNAs and at least PRPF3, PRPF4, PRPF6, PRPF8, PRPF31, SNRNP200, TXNL4A, SNRNP40, DDX23, CD2BP2, PPIH, SNU13, EFTUD2, SART1 and USP39, LSm proteins LSm2-8 and Sm proteins (PubMed:16723661, PubMed:26912367, PubMed:28781166). Interacts with ARAF (PubMed:10848612). Interacts with AR and NR3C1, but not ESR1, independently of the presence of hormones (PubMed:12039962). Interacts with USH1G (PubMed:34023904)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["12039962","20118938","21549338","28781166"],"location":"Nucleus, nucleoplasm；Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Involved in pre-mRNA splicing as component of the U4/U6-U5 tri-snRNP complex, one of the building blocks of the spliceosome (PubMed:20118938, PubMed:21549338, PubMed:28781166).","function_evidence":"含实验支持条目；ECO:0000269","categories":"RNA加工/剪接"},"PRPF8":{"hgnc":"HGNC:17340","symbol":"PRPF8","accessions":["Q6P2Q9"],"name":"Pre-mRNA-processing-splicing factor 8","length":"2335","function":"Plays a role in pre-mRNA splicing as core component of precatalytic, catalytic and postcatalytic spliceosomal complexes, both of the predominant U2-type spliceosome and the minor U12-type spliceosome (PubMed:10411133, PubMed:11971955, PubMed:28076346, PubMed:28502770, PubMed:28781166, PubMed:29301961, PubMed:29360106, PubMed:29361316, PubMed:30315277, PubMed:30705154, PubMed:30728453). Functions as a scaffold that mediates the ordered assembly of spliceosomal proteins and snRNAs. Required for the assembly of the U4/U6-U5 tri-snRNP complex, a building block of the spliceosome. Functions as a scaffold that positions spliceosomal U2, U5 and U6 snRNAs at splice sites on pre-mRNA substrates, so that splicing can occur. Interacts with both the 5' and the 3' splice site","subunit":"Part of the U5 snRNP complex (PubMed:2527369, PubMed:2532307). Component of the U4/U6-U5 tri-snRNP complex composed of the U4, U6 and U5 snRNAs and at least PRPF3, PRPF4, PRPF6, PRPF8, PRPF31, SNRNP200, TXNL4A, SNRNP40, DDX23, CD2BP2, PPIH, SNU13, EFTUD2, SART1 and USP39 (PubMed:16723661, PubMed:2479028, PubMed:26912367). Component of the U5.U4atac/U6atac snRNP complexes in U12-dependent spliceosomes (PubMed:11971955). Within the minor spliceosome, which acts on U12-type introns, interacts with PPIL2 and RBM48 (PubMed:33509932). Core component of U2-type precatalytic, catalytic and postcatalytic spliceosomal complexes (PubMed:10411133, PubMed:28076346, PubMed:28502770, PubMed:28781166, PubMed:29301961, PubMed:29360106, PubMed:29361316, PubMed:30315277, PubMed:30705154, PubMed:30728453). Found in a mRNA splicing-dependent exon junction complex (EJC) with SRRM1. Interacts with U5 snRNP proteins SNRP116 and SNRNP40. Interacts with EFTUD2. Interacts (via the MPN (JAB/Mov34) domain) with PRPF3 ('Lys-63'-linked polyubiquitinated); may stabilize the U4/U6-U5 tri-snRNP complex. Interacts (via RNase H homology domain) with AAR2 (PubMed:26527271). Interacts with RPAP3 and URI1 in a ZNHIT2-dependent manner (PubMed:28561026). Interacts with C9orf78 (PubMed:35167828, PubMed:35241646). Interacts with SNRNP200; the interaction is direct (PubMed:35188580, PubMed:35241646). Interacts with TSSC4; the interaction is direct (PubMed:35188580)","family":"","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["10411133","11971955","15840809","20595234","28076346","28502770","28781166","29301961","29360106","29361316","30315277","30705154","30728453"],"location":"Nucleus；Nucleus speckle","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"RNA加工/剪接；注释原文：Plays a role in pre-mRNA splicing as core component of precatalytic, catalytic and postcatalytic spliceosomal complexes, both of the predominant U2-type spliceosome and the minor U12-type spliceosome (PubMed:10411133, PubMed:11971955, PubMed:28076346, PubMed:28502770, PubMed:28781166, PubMed:29301961, PubMed:29360106, PubMed:29361316, PubMed:30315277, PubMed:30705154, PubMed:30728453).","function_evidence":"含实验支持条目；ECO:0000269,ECO:0000303","categories":"RNA加工/剪接"},"PRPS2":{"hgnc":"HGNC:9465","symbol":"PRPS2","accessions":["P11908"],"name":"Ribose-phosphate pyrophosphokinase 2","length":"318","function":"Catalyzes the transfer of the pyrophosphoryl group from ATP to the 1-hydroxyl of ribose-5-phosphate to form 5-phospho-ribosyl-1-pyrophosphate (PRPP), a key intermediate in the biosynthesis of several metabolites including nucleotides, dinucleotides and some amino acids (PubMed:37248548, PubMed:40295500, PubMed:8387514). Involved in the production of newly synthesized ATP/GTP through the purine biosynthesis pathway (PubMed:40295500)","subunit":"Homohexamer (PubMed:37248548, PubMed:40295500, Ref.9). Dimer of trimers (PubMed:40295500). In vitro, polymerizes into filaments of stacked hexamer, with D3 symmetry, through three interaction sites between two adjacent hexamers (PubMed:37248548). Filamentation is very important for its ribose phosphate diphosphokinase activity (PubMed:37248548)","family":"Belongs to the ribose-phosphate pyrophosphokinase family","domains":"当前缓存无可用结构域细节；不解释为无结构域","function_pmids":["37248548","40295500","8387514"],"location":"当前记录无定位注释","shared_sequence_gene_count":"1","source_snapshot":"项目UniProt20261017/18；497成员补充策展20261020","brief":"激酶/磷酸化信号；注释原文：Catalyzes the transfer of the pyrophosphoryl group from ATP to the 1-hydroxyl of ribose-5-phosphate to form 5-phospho-ribosyl-1-pyrophosphate (PRPP), a key intermediate in the biosynthesis of several metabolites including nucleotides, dinucleotides and some amino acids (PubMed:37248548, PubMed:40295500, PubMed:8387514).","function_evidence":"含实验支持条目；ECO:0000269","categories":"激酶/磷酸化信号"}};
